import type { GameRuntime } from '../types/game.js';
import type { ICreature, PartialTrapState } from '../types/creature.ts';
import { isPartialTrapMove, moveClearsPartialTrap } from './moveCombatModifiers.ts';
import { isTrainerBattle } from './combatHpRatio.ts';

export const PARTIAL_TRAP_HP_FRACTION = 1 / 16;
export const PARTIAL_TRAP_MIN_TURNS = 4;
export const PARTIAL_TRAP_MAX_TURNS = 5;

export function hasPartialTrap(creature: ICreature | null | undefined): boolean {
    const trap = creature?.partialTrap;
    return !!(trap && trap.turnsLeft > 0);
}

export function clearPartialTrap(creature: ICreature | null | undefined): void {
    if (!creature) return;
    creature.partialTrap = null;
}

export function rollPartialTrapTurns(random: () => number = Math.random): number {
    const span = PARTIAL_TRAP_MAX_TURNS - PARTIAL_TRAP_MIN_TURNS + 1;
    return PARTIAL_TRAP_MIN_TURNS + Math.floor(random() * span);
}

export function applyPartialTrapOnHit(
    target: ICreature,
    attacker: ICreature,
    moveDef: Record<string, unknown>,
    moveName: string,
    random: () => number = Math.random,
): void {
    if (!isPartialTrapMove(moveDef) || !target) return;
    target.partialTrap = {
        moveName,
        turnsLeft: rollPartialTrapTurns(random),
        sourceAttacker: attacker,
    };
}

export function clearPartialTrapFromMove(
    attacker: ICreature,
    moveDef: Record<string, unknown> | null | undefined,
): boolean {
    if (!moveClearsPartialTrap(moveDef) || !hasPartialTrap(attacker)) return false;
    clearPartialTrap(attacker);
    return true;
}

function resolveTrapVictimMaxHp(creature: ICreature, game: GameRuntime | null | undefined): number {
    if (!creature.isEnemy && game && !isTrainerBattle(game) && typeof game.getPlayerMaxHp === 'function') {
        return Math.max(1, Number(game.getPlayerMaxHp()) || creature.maxHp || 1);
    }
    return Math.max(1, creature.maxHp || (creature.stats?.HP ?? 1) || 1);
}

export function computePartialTrapTickDamage(creature: ICreature, game?: GameRuntime | null): number {
    const maxHp = resolveTrapVictimMaxHp(creature, game);
    return Math.max(1, Math.floor(maxHp * PARTIAL_TRAP_HP_FRACTION));
}

export interface PartialTrapTickResult {
    damage: number;
    applied: number;
    isDead: boolean;
    cleared: boolean;
}

export function processPartialTrapTick(
    creature: ICreature,
    game: GameRuntime | null | undefined,
    playerMainStats: Record<string, number> | null | undefined,
    opts: {
        random?: () => number;
        silent?: boolean;
    } = {},
): PartialTrapTickResult {
    const empty: PartialTrapTickResult = { damage: 0, applied: 0, isDead: false, cleared: false };
    const trap = creature.partialTrap as PartialTrapState | null | undefined;
    if (!trap || trap.turnsLeft <= 0) return empty;

    const damage = computePartialTrapTickDamage(creature, game);
    const trainer = game ? isTrainerBattle(game) : false;
    const prevHp = creature.isEnemy
        ? (creature.currentHp || 0)
        : (trainer ? (creature.currentHp || 0) : (creature.mainAccountCurrentHp ?? creature.currentHp ?? 0));

    const isDead = creature.takeDamage
        ? creature.takeDamage(damage, playerMainStats ?? null, false, 'special', 0, game ?? null, opts.silent)
        : false;

    const newHp = creature.isEnemy
        ? (creature.currentHp || 0)
        : (trainer ? (creature.currentHp || 0) : (creature.mainAccountCurrentHp ?? creature.currentHp ?? 0));
    const applied = Math.max(0, prevHp - newHp);

    trap.turnsLeft -= 1;
    let cleared = false;
    if (trap.turnsLeft <= 0) {
        clearPartialTrap(creature);
        cleared = true;
    }

    return { damage, applied, isDead, cleared };
}
