/**
 * Team reset at the start of each tower ascent (including chained batch runs).
 */

import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';
import { arrayAt } from './safeAccess.ts';
import { resetFaintedThisCombat } from './faintedThisCombat.ts';
import { isTrainerBattle } from './combatHpRatio.ts';

/** Restore zone HP pool on the team (tower uses mainAccountCurrentHp, not trainer currentHp). */
export function restoreZoneHpPoolOnTeam(game: GameRuntime): void {
    if (typeof game.getPlayerMaxHp !== 'function') return;
    const pool = game.getPlayerMaxHp();
    if (!isTrainerBattle(game)) {
        for (const creature of game.playerTeam) {
            creature.mainAccountCurrentHp = pool;
        }
    } else if (game.currentPlayerCreature) {
        game.currentPlayerCreature.mainAccountCurrentHp = pool;
    }
}

export function healTeamForTowerRun(game: GameRuntime): void {
    resetFaintedThisCombat(game);
    for (const creature of game.playerTeam) {
        (creature as CreatureData & { heal?: () => void; clearStatusEffect?: () => void }).heal?.();
        (creature as CreatureData & { clearStatusEffect?: () => void }).clearStatusEffect?.();
    }
    if (typeof game.fastForwardPpRegenTicks === 'function') game.fastForwardPpRegenTicks(80);
    if (game.playerTeam.length > 0) {
        game.activeCreatureIndex = 0;
        game.currentPlayerCreature = arrayAt(game.playerTeam, 0) ?? null;
    }
    restoreZoneHpPoolOnTeam(game);
}

/** Full reset before a new arena / league / trainer battle (per-monster currentHp, not zone pool). */
export function healTeamForTrainerBattle(game: GameRuntime): void {
    resetFaintedThisCombat(game);
    for (const creature of game.playerTeam) {
        const c = creature as CreatureData & {
            heal?: () => void;
            clearStatusEffect?: () => void;
            currentStamina?: number;
            maxStamina?: number;
            actionGauge?: number;
        };
        c.heal?.();
        c.clearStatusEffect?.();
        if (c.maxStamina != null) c.currentStamina = c.maxStamina;
        c.actionGauge = 0;
    }
    if (typeof game.fastForwardPpRegenTicks === 'function') game.fastForwardPpRegenTicks(80);
}
