/**
 * @file enemySubwayAdvanced.ts
 * Auto Fight Advanced–style move selection and mid-combat switching for trainer battles
 * (Battle Subway, gym leaders, Pokémon League). Excludes zone gym trainers (gymTrainerState).
 */

import { BALANCE } from '../../constants/balance/balance.ts';
import { ARENAS } from '../../constants/balance/arenasTrainers/index.ts';
import { getMoveDefinition } from '../../constants/movesDb.ts';
import {
    type AdvancedSwitchCandidate,
    applyNormalizedCombined,
    buildNormalizedMemberVsOpponentCandidates,
    canAutoSwitchAtAtbBreakpoint,
    defaultAutoFightAdvancedOptions,
    estimateBestMoveDamage,
    getPlayerHpRatioForScoring,
    getWorstPlayerMoveTypeAgainst,
    hasDoubleWeakness,
    isPlayerAdvancedViableMove,
    scoreMemberVsOpponentRaw,
    type AdvancedSwitchScore,
} from './autoFightAdvanced.ts';
import { getTypeMultiplier } from './typeEffectiveness.ts';
import { logMessage } from '../ui/modals.ts';
import type { GameRuntime, AutoFightAdvancedOptions } from '../types/game.ts';
import type { CreatureData, ICreature } from '../types/creature.ts';

export interface TrainerEnemyAdvancedAiConfig {
    posture: number;
    minScoreGainPct: number;
    minHpPct: number;
    neverSendWeakMatchup: boolean;
    avoidDoubleWeakness: boolean;
    skipIfCanFinish: boolean;
    switchCooldownMs: number;
    cooldownAfterPlayerSwitchMs: number;
    maxDiscretionarySwitchesPerBattle: number;
}

/** @deprecated Use TrainerEnemyAdvancedAiConfig */
export type SubwayEnemyAdvancedAiConfig = TrainerEnemyAdvancedAiConfig;

const DEFAULT_TRAINER_ENEMY_AI: TrainerEnemyAdvancedAiConfig = {
    posture: 50,
    minScoreGainPct: 0.30,
    minHpPct: 0.25,
    neverSendWeakMatchup: true,
    avoidDoubleWeakness: true,
    skipIfCanFinish: true,
    switchCooldownMs: 2000,
    cooldownAfterPlayerSwitchMs: 5000,
    maxDiscretionarySwitchesPerBattle: 3,
};

export function getTrainerEnemyAdvancedAiConfig(): TrainerEnemyAdvancedAiConfig {
    const balance = BALANCE as {
        TRAINER_ENEMY_ADVANCED_AI?: Partial<TrainerEnemyAdvancedAiConfig>;
        SUBWAY_DIFFICULTY?: { enemyAdvancedAi?: Partial<TrainerEnemyAdvancedAiConfig> };
    };
    const raw = balance.TRAINER_ENEMY_ADVANCED_AI
        ?? balance.SUBWAY_DIFFICULTY?.enemyAdvancedAi;
    return { ...DEFAULT_TRAINER_ENEMY_AI, ...raw };
}

/** @deprecated Use getTrainerEnemyAdvancedAiConfig */
export const getSubwayEnemyAdvancedAiConfig = getTrainerEnemyAdvancedAiConfig;

/** Subway + arena (gym leaders / League). Excludes zone gymTrainerState. */
export function isEnemyTrainerAdvancedAiActive(game: GameRuntime | null | undefined): boolean {
    if (!game) return false;
    return !!game.subwayState?.isActive || !!game.arenaState?.active;
}

/** @deprecated Use isEnemyTrainerAdvancedAiActive */
export const isSubwayAdvancedAiActive = isEnemyTrainerAdvancedAiActive;

type TrainerAdvancedAiMode = 'subway' | 'arena';

interface TrainerAdvancedAiContext {
    mode: TrainerAdvancedAiMode;
    team: CreatureData[];
    activeIndex: number;
    trainerName: string;
    getDiscretionaryCount: () => number;
    setDiscretionaryCount: (n: number) => void;
    applyActiveIndex: (index: number, incoming: CreatureData) => void;
}

function resolveArenaTrainerName(game: GameRuntime, slotIndex: number): string {
    const arenaState = game.arenaState;
    if (!arenaState?.active) return '';
    if (typeof game.getEliteFourTrainerNameAtSlot === 'function' && arenaState.arenaId) {
        const e4Name = game.getEliteFourTrainerNameAtSlot(slotIndex, arenaState.arenaId);
        if (e4Name) return e4Name;
    }
    const arenaId = arenaState.arenaId;
    if (arenaId) {
        const arena = (ARENAS as Record<string, { championName?: string }>)[arenaId];
        if (arena?.championName) return arena.championName;
    }
    return '';
}

export function resolveTrainerAdvancedAiContext(game: GameRuntime): TrainerAdvancedAiContext | null {
    if (game.subwayState?.isActive) {
        const subway = game.subwayState;
        const team = subway.enemyTeam;
        if (!Array.isArray(team) || team.length === 0) return null;
        const activeIndex = subway.currentEnemyIndex ?? 0;
        return {
            mode: 'subway',
            team,
            activeIndex,
            trainerName: subway.trainerName ?? '',
            getDiscretionaryCount: () => subway.discretionarySwitchesThisBattle ?? 0,
            setDiscretionaryCount: (n) => { subway.discretionarySwitchesThisBattle = n; },
            applyActiveIndex: (index, incoming) => {
                subway.currentEnemyIndex = index;
                game.currentEnemy = incoming;
            },
        };
    }
    if (game.arenaState?.active) {
        const arena = game.arenaState;
        const team = arena.championTeam;
        if (!Array.isArray(team) || team.length === 0) return null;
        const activeIndex = arena.currentChampionIndex ?? 0;
        return {
            mode: 'arena',
            team,
            activeIndex,
            trainerName: resolveArenaTrainerName(game, activeIndex),
            getDiscretionaryCount: () => arena.discretionarySwitchesThisBattle ?? 0,
            setDiscretionaryCount: (n) => { arena.discretionarySwitchesThisBattle = n; },
            applyActiveIndex: (index, incoming) => {
                arena.currentChampionIndex = index;
                game.currentEnemy = incoming;
            },
        };
    }
    return null;
}

export function resetEnemySubwaySwitchCounters(game: GameRuntime): void {
    if (!game.subwayState) return;
    game.subwayState.discretionarySwitchesThisBattle = 0;
}

export function resetEnemyArenaSwitchCounters(game: GameRuntime): void {
    if (!game.arenaState) return;
    game.arenaState.discretionarySwitchesThisBattle = 0;
}

/** Reset discretionary cap when Elite Four advances to a new trainer. */
export function resetEnemyArenaSwitchCountersOnEliteFourTrainerChange(
    game: GameRuntime,
    prevSlotIndex: number,
    newSlotIndex: number,
): void {
    if (!game.arenaState?.active || !game.arenaState.arenaId) return;
    if (typeof game.getEliteFourTrainerNameAtSlot !== 'function') return;
    const arenaId = game.arenaState.arenaId;
    const prevTrainer = game.getEliteFourTrainerNameAtSlot(prevSlotIndex, arenaId);
    const curTrainer = game.getEliteFourTrainerNameAtSlot(newSlotIndex, arenaId);
    if (curTrainer && curTrainer !== prevTrainer) {
        resetEnemyArenaSwitchCounters(game);
    }
}

function toAdvancedOptions(cfg: TrainerEnemyAdvancedAiConfig): AutoFightAdvancedOptions {
    return {
        ...defaultAutoFightAdvancedOptions(),
        neverSendWeakMatchup: cfg.neverSendWeakMatchup,
        avoidDoubleWeakness: cfg.avoidDoubleWeakness,
        minHpPct: cfg.minHpPct,
        skipIfCanFinish: cfg.skipIfCanFinish,
        minScoreGainPct: cfg.minScoreGainPct,
        respectPreferredActive: false,
        excludedSwitchIndices: [],
        preferXpEligible: false,
    };
}

function getMemberOffensiveEffectiveness(member: CreatureData, opponent: CreatureData): number {
    let eff = getTypeMultiplier(member.type, opponent.type, opponent.secondaryType ?? null);
    if (member.secondaryType) {
        eff = Math.max(
            eff,
            getTypeMultiplier(member.secondaryType, opponent.type, opponent.secondaryType ?? null),
        );
    }
    return eff;
}

export function passesEnemyTrainerSwitchFilters(
    game: GameRuntime,
    member: CreatureData,
    player: CreatureData,
    options: AutoFightAdvancedOptions,
): boolean {
    const eff = getMemberOffensiveEffectiveness(member, player);
    if (options.neverSendWeakMatchup && eff < 1) return false;

    const hpRatio = getPlayerHpRatioForScoring(game, member);
    const minHp = typeof options.minHpPct === 'number' ? options.minHpPct : 0.25;
    if (hpRatio < minHp) return false;

    if (options.avoidDoubleWeakness) {
        const threatType = getWorstPlayerMoveTypeAgainst(game, player, member);
        if (hasDoubleWeakness(member, threatType)) return false;
    }

    return true;
}

/** @deprecated Use passesEnemyTrainerSwitchFilters */
export const passesEnemySubwaySwitchFilters = passesEnemyTrainerSwitchFilters;

function passesForcedEnemyTrainerSwitchFilters(
    game: GameRuntime,
    member: CreatureData,
    player: CreatureData,
    options: AutoFightAdvancedOptions,
): boolean {
    const hpRatio = getPlayerHpRatioForScoring(game, member);
    const minHp = typeof options.minHpPct === 'number' ? options.minHpPct : 0.25;
    if (hpRatio < minHp) return false;

    if (options.avoidDoubleWeakness) {
        const threatType = getWorstPlayerMoveTypeAgainst(game, player, member);
        if (hasDoubleWeakness(member, threatType)) return false;
    }

    return true;
}

export function canEnemyActiveDealDamage(
    game: GameRuntime,
    active: CreatureData,
    player: CreatureData,
): boolean {
    const activeIc = { ...active, isEnemy: true } as unknown as ICreature;
    const playerIc = { ...player, isEnemy: false } as unknown as ICreature;
    const moves = active.currentMoves || [];
    for (const moveName of moves) {
        const moveDef = getMoveDefinition(moveName);
        if (isPlayerAdvancedViableMove(game, activeIc, playerIc, moveDef)) {
            return true;
        }
    }
    return false;
}

function canEnemyActiveFinishPlayer(
    game: GameRuntime,
    active: CreatureData,
    player: CreatureData,
    maxHits: number = 2,
): boolean {
    const perHit = estimateBestMoveDamage(game, active, player, true);
    if (perHit <= 0) return false;
    const playerHp = player.currentHp || player.mainAccountCurrentHp || player.maxHp || 1;
    return perHit * maxHits >= playerHp;
}

function getActionThreshold(entity: CreatureData | null | undefined): number {
    const t = Number(entity?.actionThreshold);
    const def = BALANCE.ATB_ACTION_THRESHOLD ?? 10000;
    return Number.isFinite(t) && t > 0 ? t : def;
}

function isEnemyReadyPlayerNot(game: GameRuntime): boolean {
    const player = game.currentPlayerCreature;
    const enemy = game.currentEnemy;
    if (!player || !enemy) return false;
    const pGauge = Number(player.actionGauge) || 0;
    const eGauge = Number(enemy.actionGauge) || 0;
    return eGauge >= getActionThreshold(enemy) && pGauge < getActionThreshold(player);
}

function canEnemyDiscretionarySwitchNow(game: GameRuntime): boolean {
    return canAutoSwitchAtAtbBreakpoint(game) || isEnemyReadyPlayerNot(game);
}

function countAliveEnemyBench(ctx: TrainerAdvancedAiContext): number {
    let count = 0;
    for (let i = 0; i < ctx.team.length; i++) {
        if (i === ctx.activeIndex) continue;
        if (ctx.team[i]?.isAlive?.()) count++;
    }
    return count;
}

function canEnemySwitchNow(game: GameRuntime, now: number): boolean {
    const cfg = getTrainerEnemyAdvancedAiConfig();
    const last = (game as GameRuntime & { _lastEnemyAutoSwitchTime?: number })._lastEnemyAutoSwitchTime;
    if (typeof last === 'number' && (now - last) < cfg.switchCooldownMs) return false;
    return true;
}

function markEnemySwitch(game: GameRuntime, now: number): void {
    (game as GameRuntime & { _lastEnemyAutoSwitchTime?: number })._lastEnemyAutoSwitchTime = now;
}

function isInPlayerSwitchWindow(game: GameRuntime, now: number): boolean {
    const cfg = getTrainerEnemyAdvancedAiConfig();
    const g = game as GameRuntime & {
        _lastAutoSwitchTime?: number;
        _lastPlayerAdvancedSwitchTime?: number;
    };
    const lastClassic = typeof g._lastAutoSwitchTime === 'number' ? g._lastAutoSwitchTime : 0;
    const lastAdvanced = typeof g._lastPlayerAdvancedSwitchTime === 'number'
        ? g._lastPlayerAdvancedSwitchTime
        : 0;
    const lastPlayerSwitch = Math.max(lastClassic, lastAdvanced);
    return lastPlayerSwitch > 0 && (now - lastPlayerSwitch) < cfg.cooldownAfterPlayerSwitchMs;
}

function getNormalizedEnemyScore(
    game: GameRuntime,
    ctx: TrainerAdvancedAiContext,
    index: number,
    cfg: TrainerEnemyAdvancedAiConfig,
    options: AutoFightAdvancedOptions,
    player: CreatureData,
): AdvancedSwitchScore | null {
    const candidates = buildNormalizedMemberVsOpponentCandidates(game, ctx.team, player, {
        posture: cfg.posture,
        options,
        memberIsEnemy: true,
        passesFilters: passesEnemyTrainerSwitchFilters,
    });
    return candidates.find((c) => c.index === index)?.score ?? null;
}

function pickBestEnemyForcedSwitchTarget(
    game: GameRuntime,
    ctx: TrainerAdvancedAiContext,
): AdvancedSwitchCandidate | null {
    const player = game.currentPlayerCreature;
    if (!player) return null;

    const cfg = getTrainerEnemyAdvancedAiConfig();
    const options = toAdvancedOptions(cfg);
    const activeIdx = ctx.activeIndex;

    let bestIndex = -1;
    let bestDmg = 0;
    let bestCreature: CreatureData | null = null;

    for (let i = 0; i < ctx.team.length; i++) {
        if (i === activeIdx) continue;
        const member = ctx.team[i];
        if (!member?.isAlive?.()) continue;
        if (!passesForcedEnemyTrainerSwitchFilters(game, member, player, options)) continue;

        const dmg = estimateBestMoveDamage(game, member, player, true);
        if (dmg > bestDmg) {
            bestDmg = dmg;
            bestIndex = i;
            bestCreature = member;
        }
    }

    if (bestIndex < 0 || !bestCreature || bestDmg <= 0) return null;

    const score = scoreMemberVsOpponentRaw(game, bestCreature, player, options, cfg.posture, true);
    const normalized = applyNormalizedCombined(
        [{ index: bestIndex, creature: bestCreature, defScore: score.defScore, offScore: score.offScore }],
        cfg.posture,
    );
    return normalized[0] ?? null;
}

/** @deprecated Use pickBestEnemyForcedSwitchTarget via context */
export function pickBestEnemySubwayForcedSwitchTarget(game: GameRuntime): AdvancedSwitchCandidate | null {
    const ctx = resolveTrainerAdvancedAiContext(game);
    if (!ctx) return null;
    return pickBestEnemyForcedSwitchTarget(game, ctx);
}

function pickBestEnemySwitchTarget(
    game: GameRuntime,
    ctx: TrainerAdvancedAiContext,
): AdvancedSwitchCandidate | null {
    const player = game.currentPlayerCreature;
    if (!player) return null;

    const cfg = getTrainerEnemyAdvancedAiConfig();
    const options = toAdvancedOptions(cfg);
    const candidates = buildNormalizedMemberVsOpponentCandidates(game, ctx.team, player, {
        excludeIndex: ctx.activeIndex,
        posture: cfg.posture,
        options,
        memberIsEnemy: true,
        passesFilters: passesEnemyTrainerSwitchFilters,
    });
    if (!candidates.length) return null;
    candidates.sort((a, b) => b.score.combined - a.score.combined);
    return candidates[0] ?? null;
}

/** @deprecated */
export function pickBestEnemySubwaySwitchTarget(game: GameRuntime): AdvancedSwitchCandidate | null {
    const ctx = resolveTrainerAdvancedAiContext(game);
    if (!ctx) return null;
    return pickBestEnemySwitchTarget(game, ctx);
}

function shouldForceEnemyTrainerSwitch(
    game: GameRuntime,
    active: CreatureData,
    best: AdvancedSwitchCandidate,
    options: AutoFightAdvancedOptions,
): boolean {
    const player = game.currentPlayerCreature;
    if (!player) return false;
    if (options.skipIfCanFinish && canEnemyActiveFinishPlayer(game, active, player)) return false;
    if (canEnemyActiveDealDamage(game, active, player)) return false;
    return estimateBestMoveDamage(game, best.creature, player, true) > 0;
}

/** @deprecated */
export const shouldForceEnemySubwaySwitch = shouldForceEnemyTrainerSwitch;

function shouldEnemyTrainerSwitch(
    game: GameRuntime,
    ctx: TrainerAdvancedAiContext,
    active: CreatureData,
    best: AdvancedSwitchCandidate,
    options: AutoFightAdvancedOptions,
): boolean {
    const player = game.currentPlayerCreature;
    if (!player) return false;

    if (shouldForceEnemyTrainerSwitch(game, active, best, options)) {
        return true;
    }

    if (options.skipIfCanFinish && canEnemyActiveFinishPlayer(game, active, player)) {
        return false;
    }

    const cfg = getTrainerEnemyAdvancedAiConfig();
    const activeScore = ctx.activeIndex >= 0
        ? getNormalizedEnemyScore(game, ctx, ctx.activeIndex, cfg, options, player)
        : null;

    const gainPct = typeof options.minScoreGainPct === 'number'
        ? options.minScoreGainPct
        : cfg.minScoreGainPct;
    const bestCombined = best.score.combined;
    const activeCombined = activeScore?.combined ?? 0;

    if (activeCombined <= 0) {
        return bestCombined > 0;
    }

    const relativeGain = (bestCombined - activeCombined) / activeCombined;
    return relativeGain >= gainPct;
}

/** @deprecated */
export function shouldEnemySubwaySwitch(
    game: GameRuntime,
    active: CreatureData,
    best: AdvancedSwitchCandidate,
    options: AutoFightAdvancedOptions,
): boolean {
    const ctx = resolveTrainerAdvancedAiContext(game);
    if (!ctx) return false;
    return shouldEnemyTrainerSwitch(game, ctx, active, best, options);
}

function executeEnemyTrainerSwitch(
    game: GameRuntime,
    ctx: TrainerAdvancedAiContext,
    targetIndex: number,
    discretionary: boolean,
): boolean {
    if (targetIndex < 0 || targetIndex >= ctx.team.length) return false;

    const incoming = ctx.team[targetIndex];
    if (!incoming?.isAlive?.()) return false;

    ctx.applyActiveIndex(targetIndex, incoming);
    incoming._focusSashUsed = false;
    incoming.clearStatusEffect?.();
    incoming.actionGauge = 0;

    if (discretionary) {
        ctx.setDiscretionaryCount(ctx.getDiscretionaryCount() + 1);
    }

    const trainerName = ctx.trainerName;
    if (typeof game.t === 'function') {
        logMessage(game.t('log.subwayTrainerSwitch', { trainer: trainerName, name: incoming.name }));
    } else {
        logMessage(`${trainerName} envoie ${incoming.name} !`);
    }

    if (typeof game.updateCombatDisplay === 'function') {
        game.updateCombatDisplay();
    }
    return true;
}

/** Mid-combat proactive switch for Subway / gym leaders / League trainers. */
export function tryEnemyTrainerAdvancedSwitch(game: GameRuntime): boolean {
    if (!isEnemyTrainerAdvancedAiActive(game)) return false;
    if (game.isAttacking) return false;

    const arenaId = game.arenaState?.active ? game.arenaState.arenaId : null;
    if (
        arenaId
        && typeof game.isEliteFourArenaId === 'function'
        && game.isEliteFourArenaId(String(arenaId))
    ) {
        return false;
    }

    const ctx = resolveTrainerAdvancedAiContext(game);
    if (!ctx) return false;

    const player = game.currentPlayerCreature;
    const active = game.currentEnemy;
    const activeIdx = ctx.activeIndex;
    if (!player || !active) return false;
    if (!active.isAlive?.()) return false;
    if (countAliveEnemyBench(ctx) === 0) return false;

    const now = Date.now();
    if (!canEnemySwitchNow(game, now)) return false;

    const cfg = getTrainerEnemyAdvancedAiConfig();
    const options = toAdvancedOptions(cfg);
    const activeCantDamage = !canEnemyActiveDealDamage(game, active, player);
    const inPlayerWindow = isInPlayerSwitchWindow(game, now);

    if (!activeCantDamage && !canEnemyDiscretionarySwitchNow(game)) return false;

    if (activeCantDamage) {
        const forced = pickBestEnemyForcedSwitchTarget(game, ctx);
        if (!forced || forced.index === activeIdx) return false;
        if (!shouldForceEnemyTrainerSwitch(game, active, forced, options)) return false;
        markEnemySwitch(game, now);
        return executeEnemyTrainerSwitch(game, ctx, forced.index, false);
    }

    if (inPlayerWindow) return false;

    const discretionaryUsed = ctx.getDiscretionaryCount();
    if (discretionaryUsed >= cfg.maxDiscretionarySwitchesPerBattle) return false;

    const best = pickBestEnemySwitchTarget(game, ctx);
    if (!best || best.index === activeIdx) return false;
    if (!shouldEnemyTrainerSwitch(game, ctx, active, best, options)) return false;

    markEnemySwitch(game, now);
    return executeEnemyTrainerSwitch(game, ctx, best.index, true);
}

/** @deprecated Use tryEnemyTrainerAdvancedSwitch */
export const tryEnemySubwayAdvancedSwitch = tryEnemyTrainerAdvancedSwitch;

/** First advanced-viable move for an enemy trainer battle. */
export function findFirstEnemyAdvancedViableMove(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
): string {
    const moves = attacker.currentMoves || [];
    for (const moveName of moves) {
        const moveDef = getMoveDefinition(moveName);
        if (isPlayerAdvancedViableMove(game, attacker, target, moveDef)) {
            return moveName;
        }
    }
    return '';
}
