/**
 * @file src/lib/applyPriorityMoveNextActionBoost.ts
 * Moves à priorité > 0 : buff vitesse ATB pour la prochaine action après coup réussi.
 */

import { PRIORITY_MOVE_NEXT_ACTION_SPEED_MULT } from '../../constants/balance/talentsAndCombat.ts';
import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';

function combatLang(game: GameRuntime | null | undefined): 'fr' | 'en' {
    const lang = game?.language;
    return String(lang || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
}

export function getMovePriority(move: Record<string, unknown> | null | undefined): number {
    const priority = Number(move?.priority);
    return Number.isFinite(priority) ? priority : 0;
}

export function consumeNextActionSpeedBoost(creature: ICreature | null | undefined): void {
    if (!creature) return;
    creature.nextActionSpeedMult = 1;
}

export function applyPriorityMoveNextActionBoost(ctx: {
    game?: GameRuntime | null;
    attacker: ICreature;
    move: Record<string, unknown> | null | undefined;
    totalApplied: number;
    log?: (msg: string) => void;
    onProc?: (text: string) => void;
}): boolean {
    const { game, attacker, move, totalApplied, log, onProc } = ctx;
    if (!move || totalApplied <= 0) return false;

    const priority = getMovePriority(move);
    if (priority <= 0) return false;

    attacker.nextActionSpeedMult = PRIORITY_MOVE_NEXT_ACTION_SPEED_MULT;

    if (log) {
        const fr = `${attacker.name} accélère sa prochaine action !`;
        const en = `${attacker.name} speeds up its next action!`;
        log(combatLang(game) === 'en' ? en : fr);
    }

    if (onProc) {
        const fr = 'Prochaine action accélérée';
        const en = 'Next action sped up';
        onProc(combatLang(game) === 'en' ? en : fr);
    }

    return true;
}
