import { POKERUS_LEVEL_MULTIPLIERS } from '../../Creature.ts';
import { toast } from '../../toastManager.ts';
import type { GameRuntime } from '../types/game.js';

const POKERUS_ROMAN = ['', 'I', 'II', 'III', 'IV', 'V'] as const;

export interface PokerusToastOptions {
    name: string;
    level: number;
    leveledUp?: boolean;
    leveledDown?: boolean;
    /** First infection (level was 0 before). */
    firstInfection?: boolean;
    /** Combat path: show × multiplier and late re-infection body. */
    showMultiplier?: boolean;
    lateReinfection?: boolean;
}

function pokerusRoman(level: number): string {
    return POKERUS_ROMAN[level] ?? String(level);
}

export function showPokerusToast(game: GameRuntime, opts: PokerusToastOptions): void {
    if (typeof toast === 'undefined' || typeof toast.info !== 'function') return;
    if (typeof game.t !== 'function') return;

    const displayName = opts.name || game.t('toast.pokerusDefaultName');
    const roman = pokerusRoman(opts.level);
    const mult = (POKERUS_LEVEL_MULTIPLIERS[opts.level] ?? 1).toFixed(2);
    const vars = { name: displayName, roman, mult };

    let title = '';
    let body = '';

    if (opts.leveledUp) {
        title = game.t('toast.pokerusLevelUpTitle');
        body = opts.showMultiplier
            ? game.t('toast.pokerusLevelUpBodyWithMult', vars)
            : game.t('toast.pokerusLevelUpBody', vars);
    } else if (opts.leveledDown) {
        title = game.t('toast.pokerusWeakenedTitle');
        body = opts.lateReinfection
            ? game.t('toast.pokerusWeakenedBodyLate', vars)
            : game.t('toast.pokerusWeakenedBody', vars);
    } else if (opts.firstInfection) {
        title = game.t('toast.pokerusInfectionTitle');
        body = game.t('toast.pokerusInfectionBody', vars);
    }

    if (title) toast.info(title, body, 0, true);
}
