/** Effective tower victory XP level multiplier (base + shop bonus). */
export function getTowerVictoryExpLevelMult(
    baseMult: number,
    permanentBoosts: { tower_combat_xp_bonus?: number } | null | undefined,
): number {
    const bonus = Number(permanentBoosts?.tower_combat_xp_bonus) || 0;
    return baseMult + bonus;
}

/** Cumule l'XP combat Tour dans runStats (même sémantique que farmingMetrics.xp : pool par victoire). */
export function recordTowerRunXp(
    runStats: { teamXpGained?: number; pensionXpGained?: number } | undefined,
    expGain: number,
    pensionExpGain: number,
): void {
    if (!runStats) return;
    if (expGain > 0) runStats.teamXpGained = (runStats.teamXpGained || 0) + expGain;
    if (pensionExpGain > 0) runStats.pensionXpGained = (runStats.pensionXpGained || 0) + pensionExpGain;
}

/** Durée de run figée à la fin d'ascension (ms). */
export function finalizeTowerRunDuration(
    runStats: { runStartedAt?: number; runDurationMs?: number } | undefined,
    endedAtMs: number = Date.now(),
): void {
    if (!runStats) return;
    const started = runStats.runStartedAt ?? endedAtMs;
    runStats.runDurationMs = Math.max(1000, endedAtMs - started);
}

/** Taux XP/heure aligné farming metric (extrapolation sur la durée réelle). */
export function getTowerXpRateStats(
    xp: number,
    durationMs: number,
): { durationMin: number; xpPerHour: number } {
    const ms = Math.max(1000, Math.floor(durationMs) || 0);
    return {
        durationMin: Math.max(1, Math.ceil(ms / 60_000)),
        xpPerHour: Math.round((Math.max(0, xp) * 3_600_000) / ms),
    };
}

/** Ex. « +1 200 en 5 min (14 400 /h) » */
export function formatTowerXpRateDisplay(
    xp: number,
    durationMs: number,
    fmtNumber: (n: number) => string,
): string {
    if (xp <= 0) return '';
    const { durationMin, xpPerHour } = getTowerXpRateStats(xp, durationMs);
    return `+${fmtNumber(xp)} en ${durationMin} min (${fmtNumber(xpPerHour)} /h)`;
}
