/**
 * @file subwayTrainerSpriteUrl.ts
 * Showdown trainer sprite URLs for Battle Subway (preview + combat).
 */

const SHOWDOWN_TRAINER_BASE = 'https://play.pokemonshowdown.com/sprites/trainers';

/** Legacy / data aliases → canonical Showdown trainer sprite ids. */
export const SUBWAY_TRAINER_SPRITE_ALIASES: Readonly<Record<string, string>> = Object.freeze({
    'backpacker-m': 'backpacker',
    'backpacker-f': 'backpackerf',
    'tourist-m': 'tourist',
    'veteran-m': 'veteran',
    'veteran-f': 'veteranf',
    fisher: 'fisherman',
    hexmaniac: 'hexmaniac-gen3',
    subwayboss: 'ingo',
});

export function resolveSubwayTrainerSpriteKey(spriteKey: string): string {
    const base = spriteKey.endsWith('.png') ? spriteKey.slice(0, -4) : spriteKey;
    return SUBWAY_TRAINER_SPRITE_ALIASES[base] ?? base;
}

export function getSubwayTrainerSpriteUrl(spriteKey: string): string {
    const resolved = resolveSubwayTrainerSpriteKey(spriteKey);
    const file = resolved.endsWith('.png') ? resolved : `${resolved}.png`;
    return `${SHOWDOWN_TRAINER_BASE}/${file}`;
}
