/**
 * Per-duel turn tally for Marathon Battle achievement (player + enemy ATB turns).
 * One duel = versus a single opposing Pokémon (not an entire trainer team).
 */

import type { GameRuntime } from '../types/game.js';

export interface CombatTurnTally {
    player: number;
    enemy: number;
}

type GameWithTurnTally = GameRuntime & {
    combatTurnTally?: CombatTurnTally;
    _updateGlobalCombatRecords?: (data: Record<string, unknown>, opts?: Record<string, unknown>) => void;
};

export function resetCombatTurnTally(game: GameWithTurnTally): void {
    game.combatTurnTally = { player: 0, enemy: 0 };
}

export function getCombatDurationTurns(game: GameWithTurnTally): number {
    const t = game.combatTurnTally;
    if (!t) return 0;
    return (t.player || 0) + (t.enemy || 0);
}

export function recordCombatTurn(game: GameWithTurnTally, isPlayer: boolean): void {
    if (!game.combatTurnTally) {
        resetCombatTurnTally(game);
    }
    const tally = game.combatTurnTally!;
    if (isPlayer) tally.player += 1;
    else tally.enemy += 1;

    const total = getCombatDurationTurns(game);
    if (total > 0 && typeof game._updateGlobalCombatRecords === 'function') {
        game._updateGlobalCombatRecords({ combatDurationTurns: total });
    }
}

export function flushCombatTurnRecords(game: GameWithTurnTally): void {
    const total = getCombatDurationTurns(game);
    if (total > 0 && typeof game._updateGlobalCombatRecords === 'function') {
        game._updateGlobalCombatRecords({ combatDurationTurns: total });
    }
}

/** End the current Pokémon duel (flush record) and reset for the next opponent. */
export function commitCombatTurnDuelAndReset(game: GameWithTurnTally): void {
    flushCombatTurnRecords(game);
    resetCombatTurnTally(game);
}
