type AttackerStatQuad = { attack: number; spattack: number; defense: number; spdefense: number };

/** Reused stat bag — avoids per-attack object spreads. */
const _effAtkStats: AttackerStatQuad = { attack: 0, spattack: 0, defense: 0, spdefense: 0 };

export function resolveAttackerStats(attacker: ICreature, overlay: AttackerStatQuad | null): AttackerStatQuad {
  if (overlay) {
    _effAtkStats.attack = overlay.attack;
    _effAtkStats.spattack = overlay.spattack;
    _effAtkStats.defense = overlay.defense;
    _effAtkStats.spdefense = overlay.spdefense;
  } else {
    _effAtkStats.attack = attacker.attack;
    _effAtkStats.spattack = attacker.spattack;
    _effAtkStats.defense = attacker.defense;
    _effAtkStats.spdefense = attacker.spdefense;
  }
  return _effAtkStats;
}

/** Minimal attacker view for Creature.calculateDamageOutput (no spread). */
const _damageCalcView = {
  attack: 0,
  spattack: 0,
  defense: 0,
  spdefense: 0,
  type: 'normal',
  secondaryType: null as string | null,
  isEnemy: false,
  heldItem: null as string | null,
};

function damageCalcAttacker(base: ICreature, attack: number, spattack: number): ICreature {
  const v = _damageCalcView;
  v.attack = attack;
  v.spattack = spattack;
  v.defense = base.defense;
  v.spdefense = base.spdefense;
  v.type = base.type;
  v.secondaryType = base.secondaryType ?? null;
  v.isEnemy = !!base.isEnemy;
  v.heldItem = base.heldItem ?? null;
  return v as unknown as ICreature;
}

