export function combatFormatText(game: GameRuntime | null, text: string, vars: Record<string, unknown> = {}): string {
    const localizeVars = (window as unknown as Record<string, unknown>).localizeTemplateSubstitutionVars;
    const localized = (typeof localizeVars === 'function' && game)
        ? (localizeVars as (g: GameRuntime, v: Record<string, unknown>) => Record<string, unknown>)(game, vars)
        : vars;
    return coerceStr(text, '').replace(/\{(\w+)\}/g, (_, k: string) => coerceStr(localized[k], ''));
}

export function combatLang(game: GameRuntime): string {
    if (!game || typeof game.normalizeLanguage !== 'function') return 'fr';
    return game.normalizeLanguage(game.language);
}

export function combatText(game: GameRuntime, key: string, fallbackFr: string, fallbackEn: string, vars: Record<string, unknown> = {}): string {
    if (game && typeof game.t === 'function' && key) {
        const translated = game.t(key, vars);
        if (translated && translated !== key) return translated;
    }
    const fallback = combatLang(game) === 'en' ? fallbackEn : fallbackFr;
    return combatFormatText(game, fallback, vars);
}

/**
 * @param {*} gameRef
 * @param {number} raw
 * @param {number} applied
 */
export function resolveDamagePopupDisplayAmount(gameRef: GameRuntime | null, raw: number, applied: number): number {
    const g = gameRef != null ? gameRef : null;
    if (g && g.damagePopupMode === 'true' && Number.isFinite(applied)) return Math.max(0, applied);
    return raw;
}

/** OHKO + Vertige : modifie les dégâts infligés (joueur -> ennemi). */
export function applyPlayerOffensivePassiveDamageMods(game: GameRuntime, attacker: ICreature, target: ICreature, damage: number): number {
    if (!game || !attacker || !target || attacker.isEnemy || !target.isEnemy || damage <= 0) return damage;
    let d = damage;
    const elu = (typeof game.getEluFactorFor === 'function') ? game.getEluFactorFor(attacker) : 1.0;

    if (attacker.passiveTalent === 'ohko' && (target.maxHp || 0) > 0) {
        const enemyRatio = (target.currentHp || 0) / target.maxHp;
        if (enemyRatio > 0.75) d = Math.floor(d * (1 + 0.30 * elu));
        const atkRatio = getAttackerHpRatio(game, attacker);
        if (atkRatio < 0.5) d = Math.floor(d * Math.max(0.5, 1 - 0.24 * elu));
    }
    if (attacker.passiveTalent === 'vertige' && (target.speed || 0) > (attacker.speed || 0)) {
        d = Math.floor(d * (1 + 0.20 * elu));
    }
    if (game && !attacker.isEnemy) {
        d = applyDynamaxOffensiveDamageMod(game, attacker, d);
        d = applyZRingElectriumOffensiveDamageMod(game, attacker, d);
    }
    return Math.max(1, d);
}

/** Renvoie true si le move requiert un seuil HP (requiresHpAbove) que l'attaquant n'atteint pas. */
export function moveBlockedByHpRequirement(moveDef: Record<string, unknown> | null, hpRatio: number): boolean {
    if (!moveDef || typeof moveDef.requiresHpAbove !== 'number') return false;
    return hpRatio <= moveDef.requiresHpAbove;
}

/**
 * Centralised combat heal: handles player (trainer-battle vs zone/shared-pool) and enemy HP pools.
 * @param {object} game       - Game instance
 * @param {object} creature   - The creature to heal
 * @param {number} healAmount - Flat HP to restore (already computed by caller)
 * @param {object} [opts]     - { silent: false }
 * @returns {number} Actual HP restored
 */
export function applyCombatHeal(game: GameRuntime, creature: ICreature, healAmount: number, opts?: Record<string, unknown>): number {
    if (!creature || healAmount <= 0) return 0;
    if (!creature.isEnemy && game && typeof game.getActiveSynergies === 'function') {
        const hm = game.getActiveSynergies().heal_mult || 0;
        if (hm > 0) healAmount = Math.floor(healAmount * (1 + hm));
    }
    if (healAmount <= 0) return 0;
    const silent = opts && opts.silent;

    if (creature.isEnemy) {
        const max = creature.maxHp || (creature.stats ? creature.stats.HP : 100) || 100;
        const old = Number(creature.currentHP || creature.currentHp || 0);
        const hp  = Math.min(max, old + healAmount);
        creature.currentHP = hp;
        return hp - old;
    }

    const isArena = isTrainerBattle(game);
    if (isArena) {
        const max = creature.maxHp || (creature.stats ? creature.stats.HP : 100) || 100;
        const old = creature.currentHp || 0;
        creature.currentHp = Math.min(max, old + healAmount);
        const actual = creature.currentHp - old;
        if (!silent && actual > 0 && showFloatingText) {
            showFloatingText(formatCombatFloatingNumber(game, actual), document.getElementById('playerSpriteContainer')!, 'ft-heal');
        }
        return actual;
    }

    const maxHp = game.getPlayerMaxHp();
    const old   = creature.mainAccountCurrentHp || 0;
    creature.mainAccountCurrentHp = Math.min(maxHp, old + healAmount);
    const actual = creature.mainAccountCurrentHp - old;
    if (!silent && actual > 0 && showFloatingText) {
        showFloatingText(formatCombatFloatingNumber(game, actual), document.getElementById('playerSpriteContainer')!, 'ft-heal');
    }
    return actual;
}

export function resetTowerCombatRelicState(game: GameRuntime): void {
    if (!game || !game.towerState || !game.towerState.isActive || !game.towerState.buffs) return;
    const buffs = game.towerState.buffs;
    if (buffs.first_blood_bonus) buffs.first_blood_used = false;
    if (buffs.brutal_rhythm_gain) buffs.brutal_rhythm_bonus = 0;
}

/**
 * Dégâts attendus sans critique (choix de capacité) — aligné sur la boucle d'attaque réelle.
 */
export function estimatePlayerMoveDamageForSelection(game: GameRuntime, attacker: ICreature, target: ICreature, moveDef: Record<string, unknown>, ctx: CombatContext = {}): number {
    const {
        effectiveAttacker = {},
        attackerStatsIncludeTalentMult = false,
        bonusDamageMult = 0,
        ultimateDamageMult = 1,
        ultimateDefensePen = 0,
        ultimateHits = 0,
        towerBuffs = {}
    } = ctx;
    if (isRetaliationMove(moveDef)) {
        return estimateRetaliationDamageForSelection(attacker, target, moveDef);
    }

    let rawPower = resolveEffectiveMovePower(moveDef, { target, attacker, game });
    if (!rawPower || rawPower <= 0) return 0;

    let attackMultiplier = 1;
    if (!attackerStatsIncludeTalentMult && attacker.getAttackMultiplier) {
        attackMultiplier = attacker.getAttackMultiplier(game);
    }
    if (towerBuffs && towerBuffs.brutal_rhythm_bonus) {
        attackMultiplier *= (1 + towerBuffs.brutal_rhythm_bonus);
    }
    const eff = effectiveAttacker as AttackerStatQuad;
    const attackForDamage = Math.floor((eff.attack || 0) * attackMultiplier);
    const spAttackForDamage = Math.floor((eff.spattack || 0) * attackMultiplier);
    let damage = Creature.calculateDamageOutput(
        damageCalcAttacker(attacker, attackForDamage, spAttackForDamage),
        target,
        {
            isCritical: false,
            ultMultiplier: ultimateDamageMult * bonusDamageMult,
            ignoreDefensePct: Math.min(0.75, Math.max(0, ultimateDefensePen)),
            attackCategory: moveDef.category as string | undefined,
            movePower: rawPower,
            moveType: moveDef.type as string | null | undefined,
            moveDef,
            gameContext: game
        }
    );

    const modeSpec = (game.getMasteryArenaTowerCombatBonus ? game.getMasteryArenaTowerCombatBonus() : 0);
    if (!attacker.isEnemy && target.isEnemy) {
        const synergyDmg = (game.getMasterySynergyDamageBonus ? game.getMasterySynergyDamageBonus() : 0);
        const moveType = moveDef.type as string | null | undefined;
        const academyDmg = getAcademyCourseBonus(game, 'damage_mult', moveType);
        const dmgBonus = (game.getAccountTalentBonus ? game.getAccountTalentBonus('damage_mult') : 0) + academyDmg + ((game.getCollectionBonuses ? game.getCollectionBonuses() : {}).damage_mult || 0) + (game.getMasteryBonus ? game.getMasteryBonus('damage_mult') : 0) + modeSpec + synergyDmg;
        damage = Math.floor(damage * (1 + dmgBonus));
        if (game.getMasteryBonus) {
            const bh = game.getMasteryBonus('boss_hunter') || 0;
            if (bh > 0 && target && (target.isBoss || target.isEpic)) {
                damage = Math.floor(damage * (1 + bh));
            }
        }
    }
    if (attacker.isEnemy && !target.isEnemy) {
        const red = (game.getAccountTalentBonus ? game.getAccountTalentBonus('damage_reduction') : 0) + (game.getMasteryBonus ? game.getMasteryBonus('damage_reduction') : 0) + modeSpec;
        damage = Math.floor(damage * (1 - (red || 0)));
    }

    const hits = ultimateHits > 1 ? ultimateHits : getExpectedMoveHits(moveDef, ultimateHits);
    return damage * hits;
}

let _lastOptimalMoveKey = '';
let _lastOptimalMovePick = '';

/** @internal Vitest only */
export function resetOptimalMoveMemoForTests(): void {
    _lastOptimalMoveKey = '';
    _lastOptimalMovePick = '';
}

/** Player move pool for optimal selection (PP / HP / exhaustion gates). */
export function buildPlayerMoveSelectionList(game: GameRuntime, attacker: ICreature): string[] {
    const moves = attacker.currentMoves || [];
    if (!moves.length) return [];

    const hpRatio = getAttackerHpRatio(game, attacker);
    if (!attacker.movePp) attacker.movePp = {};
    moves.forEach(name => {
        if (!attacker.movePp[name]) {
            const def = getMoveDefinition(name);
            const basePp = getBasePPForMove(def);
            attacker.movePp[name] = { current: basePp, max: basePp };
        }
    });

    const withPp = moves.filter(name => {
        const info = attacker.movePp[name];
        if (!info || info.current <= 0) return false;
        const def = getMoveDefinition(name);
        if (moveBlockedByHpRequirement(def ?? null, hpRatio)) return false;
        if (moveBlockedByExhaustionRule(attacker, name, def)) return false;
        if (moveBlockedByRetaliationRule(attacker, def)) return false;
        return true;
    });
    if (withPp.length > 0) return withPp;

    return moves.filter(name => {
        const def = getMoveDefinition(name) ?? null;
        if (moveBlockedByHpRequirement(def, hpRatio)) return false;
        if (moveBlockedByExhaustionRule(attacker, name, def)) return false;
        if (moveBlockedByRetaliationRule(attacker, def)) return false;
        return true;
    });
}

/** First auto-advanced viable move in selection order, or '' if none deal damage. */
export function findFirstPlayerAdvancedViableMove(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    ctx: CombatContext = {},
): string {
    if (!game.unlockedFeatures?.autoFightAdvanced) return '';
    const list = buildPlayerMoveSelectionList(game, attacker);
    for (let i = 0; i < list.length; i++) {
        const moveName = list[i];
        const moveDef = getMoveDefinition(moveName);
        if (isPlayerAdvancedViableMove(game, attacker, target, moveDef, ctx)) {
            return moveName;
        }
    }
    return '';
}

export function pickBestMoveBySimulatedDamage(game: GameRuntime, attacker: ICreature, target: ICreature, ctx: CombatContext = {}): string {
    if (!game) return '';
    const isPlayerOptimal = !attacker.isEnemy && usesOptimalMoveSelection(game);
    const isEnemyOptimal = !!attacker.isEnemy;
    if (!isPlayerOptimal && !isEnemyOptimal) return '';
    const forcedRampage = resolveForcedRampageMove(attacker);
    if (forcedRampage && shouldHonorRampageLock(game, attacker, target, ctx)) {
        return forcedRampage;
    }
    const moves = attacker.currentMoves || [];
    if (!moves.length) return '';

    const hpRatio = getAttackerHpRatio(game, attacker);
    let list: string[];

    if (attacker.isEnemy) {
        list = moves.filter(name => {
            const def = getMoveDefinition(name) ?? null;
            if (moveBlockedByHpRequirement(def, hpRatio)) return false;
            if (moveBlockedByRetaliationRule(attacker, def)) return false;
            return true;
        });
    } else {
        list = buildPlayerMoveSelectionList(game, attacker);
    }

    if (list.length === 0) return '';

    const useAdvancedViableFilter = (isPlayerOptimal && !!game.unlockedFeatures?.autoFightAdvanced)
        || (attacker.isEnemy && isEnemyTrainerAdvancedAiActive(game));
    let scoringList = list;
    if (useAdvancedViableFilter) {
        scoringList = list.filter((moveName) => {
            const moveDef = getMoveDefinition(moveName);
            return isPlayerAdvancedViableMove(game, attacker, target, moveDef, ctx);
        });
        if (scoringList.length === 0) return '';
    }

    const statusPref = (!attacker.isEnemy
        && game.unlockedFeatures?.autoFightAdvanced
        && typeof game.autoFightMovePreference === 'number')
        ? game.autoFightMovePreference / 100
        : undefined;

    const ppSig = attacker.isEnemy
        ? ''
        : list.map((name) => `${name}:${attacker.movePp[name]?.current ?? 0}`).join(',');
    const memoKey = [
        attacker.isEnemy ? '1' : '0',
        attacker.uid ?? attacker.name,
        target.uid ?? target.name,
        hpRatio.toFixed(4),
        list.join(','),
        ppSig,
        typeof statusPref === 'number' ? statusPref.toFixed(2) : '',
        useAdvancedViableFilter ? 'adv' : '',
    ].join('|');
    if (memoKey === _lastOptimalMoveKey) return _lastOptimalMovePick;

    let bestName = null;
    let bestScore = -1;
    for (let i = 0; i < scoringList.length; i++) {
        const moveName = scoringList[i];
        if (!moveName) continue;
        const moveDef = getMoveDefinition(moveName);
        if (!moveDef) continue;
        const score = estimatePlayerMoveDamageForSelection(game, attacker, target, moveDef, ctx)
            + computeMoveSelectionBonus(game, attacker, target, moveDef, statusPref);
        if (score > bestScore) {
            bestScore = score;
            bestName = moveName;
        } else if (score === bestScore && bestName !== null && moveName) {
            if (moves.indexOf(moveName) < moves.indexOf(bestName)) bestName = moveName;
        }
    }
    _lastOptimalMoveKey = memoKey;
    _lastOptimalMovePick = bestName ?? '';
    return _lastOptimalMovePick;
}

