            const _loTrainer = isTrainerBattle(game);
            const _loPrev = attacker.isEnemy ? (attacker.currentHp || 0) : (_loTrainer ? (attacker.currentHp || 0) : (attacker.mainAccountCurrentHp || 0));
            const attackerDied = attacker.takeDamage(recoil, playerMainStats, false, 'special', 0, game);
