                const _mrPrev = attacker.isEnemy ? (attacker.currentHp || 0) : (_mrTrainer ? (attacker.currentHp || 0) : (attacker.mainAccountCurrentHp || 0));
                const attackerDied = attacker.takeDamage(moveRecoilAmount, playerMainStats, false, 'special', 0, game);
