    const attackVerb = combatText(game, '', 'attaque', 'attacks');
    const damageLabel = combatText(game, '', 'degats', 'damage');
    const forWord = combatText(game, '', 'pour', 'for');
    let message = `${attacker.name} ${attackVerb} ${target.name} ${forWord} <span class="damage-${attacker.type}">${formatNumber(totalDamage)} ${damageLabel}</span>`;
    if (wasUltimate) message += combatText(game, '', ' [ULTIME]', ' [ULTIMATE]');
    if (anyHitCrit) message += combatText(game, '', ' [CRITIQUE]', ' [CRITICAL]');
    logMessage(message);

    const spriteId = !attacker.isEnemy ? 'playerSprite' : 'enemySprite';
    const targetSpriteId = !attacker.isEnemy ? 'enemySprite' : 'playerSprite';
    const lungeEl = document.getElementById(spriteId)?.closest('.battle-sprite-anchor')
        ?? document.getElementById(spriteId);
    const hitEl = document.getElementById(targetSpriteId);
    lungeEl?.classList.add('attack-lunge');
    hitEl?.classList.add('take-hit');
