const COMBAT_LEGACY_GLOBALS: Record<string, unknown> = {
    combatText,
    applyPlayerOffensivePassiveDamageMods,
    applyCombatHeal,
    performAttackWithBonusLogic,
    winCombatLogic,
    playerCreatureFaintedLogic,
    pickNextCreatureAfterFaint,
    triggerAutoCatchLogic,
    updateATBLogic,
    processPendingAttacksLogic,
    executeCreatureTurnLogic,
    handleCombatLogic,
    handleSpecialModeVictoryLogic,
    tryCaptureLogic,
};

if (typeof globalThis !== 'undefined') {
    Object.assign(globalThis as Record<string, unknown>, COMBAT_LEGACY_GLOBALS);
}
