/**
 * @file autoCatchBallPicker.ts
 * Shared auto-catch ball selection (min catch % threshold + mastery-gated ladder).
 */

import { RARITY } from '../../constants/core.ts';
import { BALLS, CATCH_RATES, POKEMON_CATCH_RATES } from '../../constants/balance/dexAndCapture.js';
import { speciesRarityForCapture } from './captureSpeciesRarity.ts';
import type { GameRuntime } from '../types/game.js';

const BALL_LADDER_ALL = ['pokeball', 'greatball', 'hyperball', 'masterball'] as const;

export type AutoCatchSpecialKind = 'shiny' | 'roamer' | 'legendary';

export type AutoCatchCaptureContext = 'active' | AutoCatchSpecialKind;

export interface AutoCatchEnemy {
    name: string;
    rarity?: string;
    isShiny?: boolean;
    isRoaming?: boolean;
}

export interface AutoCatchBallSettings {
    minCatchChancePct: number;
    catchShiny?: boolean;
    catchRoamer?: boolean;
    catchLegendary?: boolean;
    /** Allow Master Ball when auto-catch triggers via active target list. Default false. */
    useMasterballActiveTargets?: boolean;
    useMasterballShiny?: boolean;
    useMasterballRoamer?: boolean;
    useMasterballLegendary?: boolean;
    /** @deprecated migrated to useMasterballShiny / useMasterballRoamer / useMasterballLegendary */
    useMasterballShinyRoamer?: boolean;
}

export interface PickAutoCatchBallOptions extends AutoCatchBallSettings {
    /** At least one enabled special category applies (100% threshold). */
    specialThresholdActive?: boolean;
    allowMasterball?: boolean;
}

function masteryUnlocked(game: GameRuntime, bonusType: string): boolean {
    return typeof game.getMasteryBonus === 'function' && (game.getMasteryBonus(bonusType) || 0) > 0;
}

function isSpeciesLegendaryForAutoCatch(game: GameRuntime, enemy: AutoCatchEnemy): boolean {
    return speciesRarityForCapture(game, enemy.name) === RARITY.LEGENDARY;
}

/** Which special categories apply to this enemy (priority order: shiny > roamer > legendary). */
export function getAutoCatchSpecialKinds(game: GameRuntime, enemy: AutoCatchEnemy): AutoCatchSpecialKind[] {
    const kinds: AutoCatchSpecialKind[] = [];
    if (enemy.isShiny) kinds.push('shiny');
    if (enemy.isRoaming) kinds.push('roamer');
    if (isSpeciesLegendaryForAutoCatch(game, enemy)) kinds.push('legendary');
    return kinds;
}

function isCatchKindEnabled(settings: AutoCatchBallSettings, kind: AutoCatchSpecialKind): boolean {
    if (kind === 'shiny') return settings.catchShiny !== false;
    if (kind === 'roamer') return settings.catchRoamer !== false;
    return settings.catchLegendary !== false;
}

/** Shiny, roamer, or naturally legendary species (not encounter-tier legendary bosses). */
export function isSpecialAutoCatchEnemy(game: GameRuntime, enemy: AutoCatchEnemy): boolean {
    return getAutoCatchSpecialKinds(game, enemy).length > 0;
}

/** At least one matching special category has its catch toggle ON. */
export function isAutoCatchSpecialEligible(
    game: GameRuntime,
    enemy: AutoCatchEnemy,
    settings: AutoCatchBallSettings,
): boolean {
    return getAutoCatchSpecialKinds(game, enemy).some((k) => isCatchKindEnabled(settings, k));
}

/** Master Ball context for ball ladder; priority shiny > roamer > legendary. */
export function resolveAutoCatchCaptureContext(
    game: GameRuntime,
    enemy: AutoCatchEnemy,
    settings: AutoCatchBallSettings,
): AutoCatchCaptureContext {
    const kinds = getAutoCatchSpecialKinds(game, enemy).filter((k) => isCatchKindEnabled(settings, k));
    if (kinds.includes('shiny')) return 'shiny';
    if (kinds.includes('roamer')) return 'roamer';
    if (kinds.includes('legendary')) return 'legendary';
    return 'active';
}

export function isMasterballAllowedForContext(
    settings: AutoCatchBallSettings,
    captureContext: AutoCatchCaptureContext,
): boolean {
    if (captureContext === 'active') return settings.useMasterballActiveTargets === true;
    if (captureContext === 'shiny') return settings.useMasterballShiny !== false;
    if (captureContext === 'roamer') return settings.useMasterballRoamer !== false;
    if (captureContext === 'legendary') return settings.useMasterballLegendary !== false;
    return false;
}

/** Balls allowed in auto-catch, cheapest first (mastery-gated). */
export function getAutoCatchBallLadder(game: GameRuntime): string[] {
    const ladder: string[] = ['pokeball'];
    if (masteryUnlocked(game, 'autocatch_great_ball')) ladder.push('greatball');
    if (masteryUnlocked(game, 'autocatch_hyper_ball')) ladder.push('hyperball');
    if (masteryUnlocked(game, 'autocatch_master_ball')) ladder.push('masterball');
    return ladder;
}

export function getEffectiveAutoCatchLadder(
    game: GameRuntime,
    allowMasterball: boolean,
): string[] {
    const ladder = getAutoCatchBallLadder(game);
    if (allowMasterball) return ladder;
    return ladder.filter((ballId) => ballId !== 'masterball');
}

/** Effective catch rate (0–1), aligned with tryCaptureLogic. */
export function getEffectiveCatchRate(
    game: GameRuntime,
    enemy: AutoCatchEnemy,
    ballId: string,
    options: { isAutoCatch?: boolean } = {},
): number {
    const balls = BALLS as Record<string, { catchMult?: number }>;
    const catchByName = (POKEMON_CATCH_RATES as Record<string, number>)[enemy.name];
    const baseChance = catchByName
        ?? ((CATCH_RATES as Record<string, number>)[enemy.rarity ?? ''] ?? 0.1);
    const charmBonus = typeof game.getCharmeurBonus === 'function' ? game.getCharmeurBonus() : 1.0;
    const accountCaptureBonus = game.getAccountTalentBonus
        ? (game.getAccountTalentBonus('capture_chance') || 0)
        : 0;
    const masteryCaptureBonus = game.getMasteryBonus
        ? (game.getMasteryBonus('capture_chance') || 0)
        : 0;
    const masteryAutoCatchBonus = options.isAutoCatch && game.getMasteryBonus
        ? (game.getMasteryBonus('autocatch_capture_bonus') || 0)
        : 0;
    const ballMult = ballId === 'masterball'
        ? 999
        : Number(balls[ballId]?.catchMult ?? 1);
    let rate = (baseChance * ballMult * charmBonus)
        + Math.max(0, accountCaptureBonus)
        + Math.max(0, masteryCaptureBonus)
        + Math.max(0, masteryAutoCatchBonus);
    rate = Math.min(1, Math.max(0, rate));
    if (ballId === 'masterball') rate = 1;
    return rate;
}

/** Special path: at least 100% target when an enabled special category applies. */
export function getEffectiveAutoCatchThresholdPct(options: PickAutoCatchBallOptions): number {
    const base = Math.max(0, Math.min(100, Math.round(Number(options.minCatchChancePct) || 0)));
    if (options.specialThresholdActive) {
        return Math.max(base, 100);
    }
    return base;
}

/**
 * Cheapest ball in the mastery ladder that meets the threshold and is in stock.
 * Fallback: most expensive available ball in ladder if none meet threshold.
 */
export function pickMinBallForThreshold(
    game: GameRuntime,
    enemy: AutoCatchEnemy,
    options: PickAutoCatchBallOptions,
): string | null {
    const threshold = getEffectiveAutoCatchThresholdPct(options) / 100;
    const allowMasterball = options.allowMasterball !== false;
    const ladder = getEffectiveAutoCatchLadder(game, allowMasterball);
    const items = game.items ?? {};

    for (const ballId of ladder) {
        if ((items[ballId] || 0) <= 0) continue;
        if (getEffectiveCatchRate(game, enemy, ballId, { isAutoCatch: true }) >= threshold) {
            return ballId;
        }
    }

    for (let i = ladder.length - 1; i >= 0; i--) {
        const ballId = ladder[i];
        if (ballId && (items[ballId] || 0) > 0) return ballId;
    }

    return null;
}

export function pickAutoCatchBall(
    game: GameRuntime,
    enemy: AutoCatchEnemy,
    settings: AutoCatchBallSettings,
    captureContext: AutoCatchCaptureContext,
): string | null {
    const specialThresholdActive = captureContext !== 'active';
    const allowMasterball = isMasterballAllowedForContext(settings, captureContext);
    return pickMinBallForThreshold(game, enemy, {
        minCatchChancePct: settings.minCatchChancePct,
        specialThresholdActive,
        allowMasterball,
    });
}

export { BALL_LADDER_ALL };
