/**
 * @file src/lib/moveSelectionScore.ts
 * Bonus de scoring pour la sélection automatique de move (hors dégâts bruts).
 */

import { BALANCE } from '../../constants/balance/balance.ts';
import { getAttackerHpRatio } from './combatHpRatio.ts';
import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';
import type { MoveStatChange } from '../types/combat.ts';
import { getExpectedMoveHits } from './resolveMoveHitCount.ts';
import { getRampageConfig, isRampageLocked } from './rampageMove.ts';

const OPT = (BALANCE.OPTIMAL_MOVE || {}) as Record<string, number>;

export function computeMoveSelectionBonus(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    moveDef: Record<string, unknown>,
    statusPreference?: number,
): number {
    const pref = typeof statusPreference === 'number'
        ? Math.max(0, Math.min(1, statusPreference))
        : 0;
    const statusWeight = 0.25 + 0.75 * pref;

    let bonus = 0;

    const status = typeof moveDef.status === 'string' ? moveDef.status : '';
    const statusChance = Number(moveDef.statusChance);
    const targetHasStatus = !!(target.hasStatusEffect && target.hasStatusEffect());
    const expectedHits = getExpectedMoveHits(moveDef);
    if (status && Number.isFinite(statusChance) && statusChance > 0 && !targetHasStatus) {
        bonus += (OPT.STATUS_PROC_VALUE ?? 15) * statusChance * expectedHits * statusWeight;
    }

    if (moveDef.selfStatusOnHit) {
        bonus += OPT.SELF_SLOW_ON_HIT_PENALTY ?? -8;
    }

    if (getRampageConfig(moveDef) && !isRampageLocked(attacker)) {
        bonus += OPT.RAMPAGE_PENALTY ?? -6;
    }

    const drain = Number(moveDef.drain);
    if (Number.isFinite(drain) && drain > 0) {
        const hpRatio = getAttackerHpRatio(game, attacker);
        if (hpRatio < 0.5) {
            bonus += (OPT.DRAIN_LOW_HP_VALUE ?? 20) * drain * statusWeight;
        }
    }

    const statChanges = Array.isArray(moveDef.statChanges) ? moveDef.statChanges as MoveStatChange[] : [];
    for (const change of statChanges) {
        if (change.target === 'self' && change.stages < 0) {
            const chance = Number(change.chance) || 0;
            bonus += (OPT.SELF_STAT_DROP_PENALTY ?? -8) * Math.abs(change.stages) * chance;
        } else if (change.target === 'opponent' && change.stages < 0) {
            const chance = Number(change.chance) || 0;
            bonus += (OPT.OPPONENT_STAT_DROP_VALUE ?? 4) * Math.abs(change.stages) * chance * statusWeight;
        }
    }

    return bonus;
}
