/**
 * Zone combat relay after faint — shared by live combatSystem and offline simulateCombat.
 */

import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';
import { isCreatureFaintedThisCombat } from './faintedThisCombat.ts';

/** Next team member after a zone-fight KO (same rules as live relay). */
export function pickNextCreatureAfterFaint(
    game: GameRuntime
): { creature: ICreature; index: number } | null {
    if (!Array.isArray(game.playerTeam)) return null;
    for (let i = 0; i < game.playerTeam.length; i++) {
        if (i === game.activeCreatureIndex) continue;
        const candidate = game.playerTeam[i];
        if (!candidate) continue;
        if (candidate.currentHp > 0 && !isCreatureFaintedThisCombat(game, candidate, i)) {
            return { creature: candidate as ICreature, index: i };
        }
    }
    return null;
}
