/**
 * @file src/lib/applyMoveSelfStatusOnHit.ts
 * Effet sur le lanceur après un coup réussi (ex. famille recharge → MIRED).
 */

import { STATUS_EFFECTS } from '../../constants/balance/talentsAndCombat.ts';
import { formatStatusFloatingText, formatStatusLabel } from './moveSecondaryEffects.ts';
import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';
import type { MoveSelfStatusOnHit } from '../types/combat.ts';

const BLOCKING_SELF_SLOW_OVERWRITE = new Set([
    STATUS_EFFECTS.FROZEN,
    STATUS_EFFECTS.STUNNED,
    STATUS_EFFECTS.SLEEP,
]);

function combatLang(game: GameRuntime | null | undefined): 'fr' | 'en' {
    const lang = game?.language;
    return String(lang || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
}

export function canApplySelfStatusOnHit(attacker: ICreature, selfStatus: MoveSelfStatusOnHit): boolean {
    if (!attacker.hasStatusEffect || !attacker.hasStatusEffect()) return true;
    const current = attacker.statusEffect?.type;
    if (!current || current === STATUS_EFFECTS.NONE) return true;
    if (BLOCKING_SELF_SLOW_OVERWRITE.has(current)) return false;
    if (selfStatus === 'mired' && current === STATUS_EFFECTS.MIRED) return true;
    return false;
}

export function applyMoveSelfStatusOnHit(ctx: {
    game?: GameRuntime | null;
    attacker: ICreature;
    move: Record<string, unknown> | null | undefined;
    totalApplied: number;
    sourceAttack: number;
    log?: (msg: string) => void;
    onProc?: (text: string) => void;
}): boolean {
    const { game, attacker, move, totalApplied, sourceAttack, log, onProc } = ctx;
    if (!move || totalApplied <= 0) return false;

    const selfStatus = move.selfStatusOnHit as MoveSelfStatusOnHit | undefined;
    if (!selfStatus) return false;
    if (!attacker.applyStatusEffect) return false;
    if (!canApplySelfStatusOnHit(attacker, selfStatus)) return false;

    if (attacker.hasStatusEffect?.() && attacker.statusEffect?.type === STATUS_EFFECTS.MIRED) {
        attacker.clearStatusEffect?.();
    }

    const statusType = selfStatus === 'mired' ? STATUS_EFFECTS.MIRED : selfStatus;
    const applied = attacker.applyStatusEffect(statusType, sourceAttack, attacker);
    if (!applied) return false;

    const statusName = typeof attacker.getStatusEffectName === 'function'
        ? attacker.getStatusEffectName()
        : formatStatusLabel(game, statusType);

    if (log) {
        const fr = `${attacker.name} est ralenti (${statusName}) !`;
        const en = `${attacker.name} is slowed (${statusName})!`;
        log(combatLang(game) === 'en' ? en : fr);
    }

    if (onProc) {
        onProc(formatStatusFloatingText(game, statusType));
    }

    return true;
}
