/**
 * @file src/lib/variablePowerByHp.ts
 * Puissance variable selon les PV restants (Contre / Reversal, Gigotage / Flail).
 */

import type { MoveData } from '../types/combat.ts';

export type VariableHpPowerMode = 'reversal' | 'flail';

/** Contre (Reversal) : paliers sur le % de PV restants. */
export function resolveReversalPower(hpRatio: number): number {
    const pct = Math.max(0, Math.min(1, hpRatio)) * 100;
    if (pct >= 71) return 20;
    if (pct >= 36) return 40;
    if (pct >= 21) return 80;
    if (pct >= 11) return 100;
    if (pct >= 5) return 150;
    return 200;
}

/** Gigotage (Flail) : P = floor(48 × hpRatio) puis paliers. */
export function resolveFlailPower(hpRatio: number): number {
    const ratio = Math.max(0, Math.min(1, hpRatio));
    const p = Math.floor(48 * ratio);
    if (p > 32) return 20;
    if (p >= 17) return 40;
    if (p >= 10) return 80;
    if (p >= 5) return 100;
    if (p >= 2) return 150;
    return 200;
}

export function resolvePowerFromHpRatio(hpRatio: number, mode: VariableHpPowerMode): number {
    if (mode === 'flail') return resolveFlailPower(hpRatio);
    return resolveReversalPower(hpRatio);
}

export function isVariableHpPowerMove(
    moveDef: MoveData | Record<string, unknown> | null | undefined,
): boolean {
    if (!moveDef) return false;
    const mode = moveDef.variableHpPowerMode;
    return mode === 'reversal' || mode === 'flail';
}

export function resolveVariableMovePower(
    moveDef: MoveData | Record<string, unknown>,
    hpRatio: number,
): number {
    const mode = moveDef.variableHpPowerMode as VariableHpPowerMode;
    return resolvePowerFromHpRatio(hpRatio, mode);
}
