/**
 * Piègeur passive talent: chip damage when an enemy enters battle.
 */

import type { GameRuntime } from '../types/game.ts';
import type { CreatureData, ICreature } from '../types/creature.ts';
import { scaleTalentRatio } from './eluTalentBoost.ts';
import { isTrainerBattle } from './combatHpRatio.ts';
import { isTrainerCombatMode, resolveOpponentTeamForTrainerCombat } from './trainerOpponentTeam.ts';
import { formatCombatFloatingNumber } from '../../formatters.ts';
import { logMessage } from '../ui/modals.ts';
import { showFloatingText } from '../ui/floatingText.ts';

export const PIEGEUR_ENTRY_HP_RATIO = 0.05;

export type HazardEntryTalentResult = {
    damage: number;
    applied: number;
    isDead: boolean;
};

type TeamMember = CreatureData | ICreature | null | undefined;

function isAliveTeamMember(creature: TeamMember): creature is CreatureData | ICreature {
    if (!creature) return false;
    if (typeof creature.isAlive === 'function') return creature.isAlive();
    const hp = creature.currentHp ?? creature.mainAccountCurrentHp;
    return (hp ?? 0) > 0;
}

/** Alive Piègeur with the highest maxHp (first in team order on tie; for Élu scaling). */
export function findPiegeurSourceMember(
    team: TeamMember[] | undefined,
): CreatureData | ICreature | null {
    if (!Array.isArray(team)) return null;
    let best: CreatureData | ICreature | null = null;
    let bestHp = -1;
    for (const member of team) {
        if (member?.passiveTalent !== 'piegeur' || !isAliveTeamMember(member)) continue;
        const hp = Number(member.maxHp) || 0;
        if (hp > bestHp) {
            bestHp = hp;
            best = member;
        }
    }
    return best;
}

export function teamHasPiegeurTalent(team: TeamMember[] | undefined): boolean {
    return findPiegeurSourceMember(team) != null;
}

/** Max HP used as Piègeur damage base: account bar (zone) or trapper Pokémon (trainer/tower/enemy). */
export function getPiegeurDamageHpBase(
    game: GameRuntime | null,
    source: CreatureData | ICreature,
): number {
    const sourceIsEnemy = !!(source as { isEnemy?: boolean }).isEnemy;
    if (game && (isTrainerBattle(game) || sourceIsEnemy || game.towerState?.isActive)) {
        return Math.max(1, Number(source.maxHp) || 1);
    }
    if (game && typeof game.getPlayerMaxHp === 'function') {
        return Math.max(1, Number(game.getPlayerMaxHp()) || 1);
    }
    return Math.max(1, Number(source.maxHp) || 1);
}

export function computeHazardEntryDamage(
    game: GameRuntime | null,
    enemy: CreatureData | ICreature,
    source: CreatureData | ICreature,
): number {
    const maxHp = getPiegeurDamageHpBase(game, source);
    let ratio = PIEGEUR_ENTRY_HP_RATIO;
    if (game && typeof game.getEluFactorFor === 'function') {
        ratio = scaleTalentRatio(ratio, game.getEluFactorFor(source));
    }
    return Math.max(1, Math.floor(maxHp * ratio));
}

/** Cap Piègeur chip so the target always survives with at least 1 HP. */
export function clampPiegeurAppliedDamage(
    target: CreatureData | ICreature,
    rawDamage: number,
    game: GameRuntime | null = null,
): number {
    const currentHp = getPiegeurTargetCurrentHp(target, game);
    if (rawDamage <= 0 || currentHp <= 1) return 0;
    return Math.min(rawDamage, currentHp - 1);
}

function getPiegeurTargetCurrentHp(
    target: CreatureData | ICreature,
    game: GameRuntime | null,
): number {
    if (game && (isTrainerBattle(game) || game.towerState?.isActive)) {
        return target.currentHp || 0;
    }
    return target.mainAccountCurrentHp ?? target.currentHp ?? 0;
}

/** Trainer modes where opponent teams can carry Piègeur (Subway, arena, gym, tower). */
export function isOpponentPiegeurBattleMode(game: GameRuntime): boolean {
    return isTrainerCombatMode(game);
}

/** Opponent roster for Piègeur lookups (bench carriers included). */
export function resolveOpponentTeamForPiegeur(game: GameRuntime): TeamMember[] | null {
    return resolveOpponentTeamForTrainerCombat(game);
}

function hazardEntryLogMessage(
    game: GameRuntime,
    enemyName: string,
    damage: number,
): void {
    if (typeof game.t === 'function') {
        logMessage(game.t('log.hazardEntryDamage', { name: enemyName, dmg: damage }));
        return;
    }
    const isEn = game.language === 'en';
    logMessage(
        isEn
            ? `Hazards deal ${damage} damage to ${enemyName}!`
            : `Les pièges infligent ${damage} dégâts à ${enemyName} !`,
    );
}

/** Live combat: apply Piègeur chip to an entering enemy. */
export function applyHazardEntryTalentOnEnemyLive(
    game: GameRuntime,
    enemy: CreatureData | ICreature | null | undefined,
    opts?: { silent?: boolean },
): HazardEntryTalentResult | null {
    if (!enemy || !teamHasPiegeurTalent(game.playerTeam)) return null;

    const source = findPiegeurSourceMember(game.playerTeam);
    if (!source) return null;

    const rawDamage = computeHazardEntryDamage(game, enemy, source);
    const appliedDamage = clampPiegeurAppliedDamage(enemy, rawDamage, game);
    if (appliedDamage <= 0) {
        return { damage: 0, applied: 0, isDead: false };
    }

    const playerMainStats = isTrainerBattle(game)
        ? ({} as Record<string, number>)
        : (typeof game.getEffectiveStats === 'function'
            ? game.getEffectiveStats()
            : game.playerMainStats ?? {});

    const prevHp = enemy.currentHp || 0;
    if (typeof enemy.takeDamage === 'function') {
        enemy.takeDamage(appliedDamage, playerMainStats, false, 'special', 0, game);
    }
    const applied = Math.max(0, prevHp - (enemy.currentHp || 0));

    if (!opts?.silent && !game.isOfflineSimulating) {
        hazardEntryLogMessage(game, String(enemy.name || ''), applied > 0 ? applied : appliedDamage);
        if (applied > 0 && typeof document !== 'undefined') {
            const container = document.getElementById('enemySpriteContainer');
            if (container) {
                showFloatingText(
                    `TRAP ${formatCombatFloatingNumber(game, applied)}`,
                    container,
                    'ft-damage-enemy',
                );
            }
        }
    }

    return { damage: applied, applied, isDead: false };
}

/** Offline sim: apply Piègeur chip via injected damage applier. */
export function applyHazardEntryTalentOnEnemySim(
    game: GameRuntime,
    enemy: CreatureData | ICreature | null | undefined,
    applyDamage: (damage: number) => number,
): HazardEntryTalentResult | null {
    if (!enemy || !teamHasPiegeurTalent(game.playerTeam)) return null;

    const source = findPiegeurSourceMember(game.playerTeam);
    if (!source) return null;

    const rawDamage = computeHazardEntryDamage(game, enemy, source);
    const appliedDamage = clampPiegeurAppliedDamage(enemy, rawDamage, game);
    if (appliedDamage <= 0) {
        return { damage: 0, applied: 0, isDead: false };
    }

    const prevHp = enemy.currentHp || 0;
    applyDamage(appliedDamage);
    const applied = Math.max(0, prevHp - (enemy.currentHp || 0));

    return { damage: applied, applied, isDead: false };
}

/** Live combat: apply opponent Piègeur chip to an entering player Pokémon. */
export function applyHazardEntryTalentOnPlayerLive(
    game: GameRuntime,
    player: CreatureData | ICreature | null | undefined,
    opts?: { silent?: boolean },
): HazardEntryTalentResult | null {
    if (!player || !isOpponentPiegeurBattleMode(game)) return null;

    const opponentTeam = resolveOpponentTeamForPiegeur(game);
    if (!opponentTeam || !teamHasPiegeurTalent(opponentTeam)) return null;

    const source = findPiegeurSourceMember(opponentTeam);
    if (!source) return null;

    const rawDamage = computeHazardEntryDamage(game, player, source);
    const appliedDamage = clampPiegeurAppliedDamage(player, rawDamage, game);
    if (appliedDamage <= 0) {
        return { damage: 0, applied: 0, isDead: false };
    }

    const playerMainStats = isTrainerBattle(game) || game.towerState?.isActive
        ? ({} as Record<string, number>)
        : (typeof game.getEffectiveStats === 'function'
            ? game.getEffectiveStats()
            : game.playerMainStats ?? {});

    const prevHp = getPiegeurTargetCurrentHp(player, game);
    if (typeof player.takeDamage === 'function') {
        player.takeDamage(appliedDamage, playerMainStats, false, 'special', 0, game);
    }
    const applied = Math.max(0, prevHp - getPiegeurTargetCurrentHp(player, game));

    if (!opts?.silent && !game.isOfflineSimulating) {
        hazardEntryLogMessage(game, String(player.name || ''), applied > 0 ? applied : appliedDamage);
        if (applied > 0 && typeof document !== 'undefined') {
            const container = document.getElementById('playerSpriteContainer');
            if (container) {
                showFloatingText(
                    `TRAP ${formatCombatFloatingNumber(game, applied)}`,
                    container,
                    'ft-damage-player',
                );
            }
        }
    }

    return { damage: applied, applied, isDead: false };
}

/** Offline sim: apply opponent Piègeur chip via injected damage applier. */
export function applyHazardEntryTalentOnPlayerSim(
    game: GameRuntime,
    player: CreatureData | ICreature | null | undefined,
    applyDamage: (damage: number) => number,
): HazardEntryTalentResult | null {
    if (!player || !isOpponentPiegeurBattleMode(game)) return null;

    const opponentTeam = resolveOpponentTeamForPiegeur(game);
    if (!opponentTeam || !teamHasPiegeurTalent(opponentTeam)) return null;

    const source = findPiegeurSourceMember(opponentTeam);
    if (!source) return null;

    const rawDamage = computeHazardEntryDamage(game, player, source);
    const appliedDamage = clampPiegeurAppliedDamage(player, rawDamage, game);
    if (appliedDamage <= 0) {
        return { damage: 0, applied: 0, isDead: false };
    }

    const prevHp = getPiegeurTargetCurrentHp(player, game);
    applyDamage(appliedDamage);
    const applied = Math.max(0, prevHp - getPiegeurTargetCurrentHp(player, game));

    return { damage: applied, applied, isDead: false };
}
