/**
 * @file src/lib/retaliationMove.ts
 * Moves de représailles (Vindicte, Contre, Riposte, etc.).
 */

import { BALANCE } from '../../constants/balance/balance.ts';
import { getTypeMultiplier } from './typeEffectiveness.ts';
import type { MoveData } from '../types/combat.ts';

export type RetaliationDamageCategory = 'any' | 'physical' | 'special';

export interface RetaliationCreature {
    _lastOpponentHitDamage?: number;
    _lastOpponentHitCategory?: 'physical' | 'special';
    type?: string;
    secondaryType?: string | null;
}

export function isRetaliationMove(
    moveDef: MoveData | Record<string, unknown> | null | undefined,
): boolean {
    if (!moveDef) return false;
    const mult = Number(moveDef.retaliationMultiplier);
    return Number.isFinite(mult) && mult > 0;
}

export function clearRetaliationState(creature: RetaliationCreature | null | undefined): void {
    if (!creature) return;
    creature._lastOpponentHitDamage = 0;
    creature._lastOpponentHitCategory = undefined;
}

export function recordOpponentHitDamage(
    creature: RetaliationCreature,
    applied: number,
    category: string | undefined,
): void {
    if (!applied || applied <= 0) return;
    creature._lastOpponentHitDamage = applied;
    creature._lastOpponentHitCategory = category === 'special' ? 'special' : 'physical';
}

function retaliationCategoryMatches(
    required: RetaliationDamageCategory | undefined,
    recorded: 'physical' | 'special' | undefined,
): boolean {
    const req = required || 'any';
    if (req === 'any') return true;
    if (!recorded) return false;
    return recorded === req;
}

export function getStoredRetaliationDamage(creature: RetaliationCreature): number {
    const value = Number(creature._lastOpponentHitDamage);
    return Number.isFinite(value) && value > 0 ? value : 0;
}

export function moveBlockedByRetaliationRule(
    creature: RetaliationCreature,
    moveDef: MoveData | Record<string, unknown> | null | undefined,
): boolean {
    if (!isRetaliationMove(moveDef)) return false;
    if (getStoredRetaliationDamage(creature) <= 0) return true;
    const required = (moveDef!.retaliationDamageCategory as RetaliationDamageCategory) || 'any';
    return !retaliationCategoryMatches(required, creature._lastOpponentHitCategory);
}

export interface RetaliationResolveInput {
    attacker: RetaliationCreature;
    moveDef: MoveData | Record<string, unknown>;
    target: RetaliationCreature;
}

export function resolveRetaliationDamage(
    input: RetaliationResolveInput,
): { damage: number; blocked: boolean } {
    const { attacker, moveDef, target } = input;
    if (moveBlockedByRetaliationRule(attacker, moveDef)) {
        return { damage: 0, blocked: true };
    }

    const mult = Number(moveDef.retaliationMultiplier) || 1;
    const stored = getStoredRetaliationDamage(attacker);
    let damage = Math.floor(stored * mult);

    if (moveDef.retaliationTypeless === true) {
        return { damage: Math.max(0, damage), blocked: false };
    }

    const moveType = String(moveDef.type || 'normal');
    const effectiveness = getTypeMultiplier(
        moveType,
        String(target.type || 'normal'),
        target.secondaryType ?? null,
    );
    if (effectiveness === 0) {
        return { damage: 0, blocked: false };
    }

    const hasStab = attacker.type === moveType
        || (attacker.secondaryType && attacker.secondaryType === moveType);
    const stabMult = hasStab ? (Number(BALANCE.STAB_MULTIPLIER) || 1.5) : 1;
    damage = Math.floor(damage * effectiveness * stabMult);
    return { damage: Math.max(0, damage), blocked: false };
}

export function consumeRetaliationCharge(
    creature: RetaliationCreature,
    moveDef: MoveData | Record<string, unknown> | null | undefined,
): void {
    if (!isRetaliationMove(moveDef)) return;
    clearRetaliationState(creature);
}

export function estimateRetaliationDamageForSelection(
    attacker: RetaliationCreature,
    target: RetaliationCreature,
    moveDef: MoveData | Record<string, unknown>,
): number {
    const { damage, blocked } = resolveRetaliationDamage({ attacker, moveDef, target });
    return blocked ? 0 : damage;
}
