/**
 * @file subwayCombatTeam.ts
 * Battle Subway enemy team generation (shared by combat and trainer dex preview).
 */

import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';
import { Creature } from '../../Creature.ts';
import { BALANCE } from '../../constants/balance/balance.ts';
import { RARITY, POKEMON_SECONDARY_TYPES } from '../../constants/core.ts';
import { type SubwayTrainerDef, type SubwayTrainerPokemon } from '../../constants/balance/subwayTrainers.ts';
import {
    getSubwayCurrentWagonIndex,
    getSubwayTrainersForDay,
    getSubwayWagonStatMult,
} from './subwayDailySet.ts';
import { HELD_ITEMS } from '../../constants/balance/towerAndItems.ts';
import { EPIC_TALENTS, LEGENDARY_TALENTS } from '../../constants/balance/talentsAndCombat.ts';
import { pickTrainerMoves } from './trainerMovesets.ts';

const VALID_TRAINER_TALENTS = new Set<string>([...EPIC_TALENTS, ...LEGENDARY_TALENTS]);

function getSubwayTrainerDef(battleIndex: number, trainers?: SubwayTrainerDef[]): SubwayTrainerDef {
    const roster = trainers ?? getSubwayTrainersForDay();
    const idx = Math.max(0, Math.min(roster.length - 1, battleIndex - 1));
    return roster[idx]!;
}

export function getSubwayBaseLevel(
    _game: GameRuntime,
    battleIndex: number,
    wagonIndex = 1,
): number {
    const cfg = BALANCE.SUBWAY_DIFFICULTY;
    const b = Math.max(1, Math.floor(Number(battleIndex) || 1));
    const w = Math.max(1, Math.floor(Number(wagonIndex) || 1));
    return Math.max(
        cfg.minLevel,
        cfg.baseLevel + (b - 1) * cfg.levelPerBattle + (w - 1) * cfg.levelPerWagon,
    );
}

/** Indicative stat multiplier for a wagon/combat (matches team generation). */
export function getSubwayStatMult(battleIndex: number, wagonIndex = 1): number {
    const cfg = BALANCE.SUBWAY_DIFFICULTY;
    const b = Math.max(1, Math.floor(Number(battleIndex) || 1));
    const w = Math.max(1, Math.floor(Number(wagonIndex) || 1));
    return cfg.baseStatMult
        * (1 + (b - 1) * cfg.statMultPerBattle)
        * getSubwayWagonStatMult(w);
}

/** Indicative level for UI previews (trainer dex). */
export function getSubwayPreviewLevel(
    game: GameRuntime,
    battleIndex: number,
    levelOffset = 0,
): number {
    const wagonIndex = getSubwayCurrentWagonIndex(game);
    return Math.max(1, getSubwayBaseLevel(game, battleIndex, wagonIndex) + levelOffset);
}

function resolveSubwayEntryRarity(entry: SubwayTrainerPokemon): string {
    if (entry.rarity === 'epic') return RARITY.EPIC;
    return RARITY.RARE;
}

function applySubwayTrainerPokemonBuild(
    creature: CreatureData,
    entry: SubwayTrainerPokemon,
    trainer: SubwayTrainerDef,
    statMult: number,
): void {
    const pokemonType = entry.type ?? trainer.type;
    const explicitMoves = entry.moves ?? trainer.fixedMovesets?.[entry.name] ?? null;
    creature.currentMoves = pickTrainerMoves(
        entry.name,
        pokemonType,
        explicitMoves,
        { ensureTypeDiversity: !explicitMoves },
    );

    if (entry.talent && VALID_TRAINER_TALENTS.has(entry.talent)) {
        creature.passiveTalent = entry.talent;
    } else {
        creature.assignRandomTalent?.();
    }

    if (entry.heldItem && (HELD_ITEMS as Record<string, unknown>)[entry.heldItem]) {
        creature.heldItem = entry.heldItem;
    }

    creature.maxHp = Math.floor(creature.maxHp * statMult);
    creature.attack = Math.floor(creature.attack * statMult);
    creature.spattack = Math.floor(creature.spattack * statMult);
    creature.defense = Math.floor(creature.defense * statMult);
    creature.spdefense = Math.floor(creature.spdefense * statMult);
    creature.speed = Math.floor(creature.speed * statMult);
    creature.currentHp = creature.maxHp;
    creature.actionGauge = 0;
    creature.actionThreshold = BALANCE.ATB_ACTION_THRESHOLD;
}

export function generateSubwayTrainerTeamLogic(
    game: GameRuntime,
    battleIndex: number,
    trainers?: SubwayTrainerDef[],
): { team: CreatureData[]; trainer: SubwayTrainerDef } {
    const trainer = getSubwayTrainerDef(battleIndex, trainers);
    const wagonIndex = getSubwayCurrentWagonIndex(game);
    const statMult = getSubwayStatMult(battleIndex, wagonIndex);
    const baseLevel = getSubwayBaseLevel(game, battleIndex, wagonIndex);
    const team: CreatureData[] = [];

    trainer.team.forEach((entry) => {
        const name = entry.name;
        const pokemonType = entry.type ?? trainer.type;
        const secondaryType = POKEMON_SECONDARY_TYPES[name] ?? null;
        const level = Math.max(1, baseLevel + (entry.levelOffset ?? 0));
        const creature = new Creature(
            name,
            pokemonType,
            level,
            resolveSubwayEntryRarity(entry),
            true,
            false,
            secondaryType,
            false,
            false,
        );
        (creature as CreatureData & { isGymTrainer?: boolean }).isGymTrainer = true;
        applySubwayTrainerPokemonBuild(creature, entry, trainer, statMult);
        team.push(creature);
    });

    return { team, trainer };
}
