/**
 * @file src/lib/resolveMoveHit.ts
 * Calcul de précision / esquive pour les moves (stages acc/eva + accuracy move).
 */

import type { ICreature } from '../types/creature.js';
import type { CombatStatKey } from '../types/combat.ts';

export function getMoveBaseAccuracy(move: Record<string, unknown> | null | undefined): number | null {
    if (!move) return 100;
    if (move.accuracy === null || move.accuracy === undefined) return null;
    const acc = Number(move.accuracy);
    return Number.isFinite(acc) ? acc : 100;
}

export function getEffectiveMoveAccuracy(
    attacker: ICreature,
    target: ICreature,
    move: Record<string, unknown> | null | undefined,
): number | null {
    const base = getMoveBaseAccuracy(move);
    if (base === null) return null;

    let effective = base;
    if (typeof attacker.getCombatStatStageMultiplier === 'function') {
        effective *= attacker.getCombatStatStageMultiplier('accuracy' as CombatStatKey);
    }
    if (typeof target.getCombatStatStageMultiplier === 'function') {
        effective /= target.getCombatStatStageMultiplier('evasion' as CombatStatKey);
    }
    return Math.min(100, Math.max(0, effective));
}

export function rollMoveHit(
    attacker: ICreature,
    target: ICreature,
    move: Record<string, unknown> | null | undefined,
    random: () => number = Math.random,
): boolean {
    const effective = getEffectiveMoveAccuracy(attacker, target, move);
    if (effective === null) return true;
    return random() * 100 < effective;
}
