export type { AutoFightAdvancedPreset } from '../types/game.ts';

export interface AutoFightAdvancedPresetValues {
    posture: number;
    movePreference: number;
    switchGainPct: number;
    options: Pick<
        AutoFightAdvancedOptions,
        'neverSendWeakMatchup' | 'avoidDoubleWeakness' | 'skipIfCanFinish' | 'respectPreferredActive'
    >;
}

export const AUTO_FIGHT_ADVANCED_PRESETS: Record<
    Exclude<AutoFightAdvancedPreset, 'custom'>,
    AutoFightAdvancedPresetValues
> = {
    safe: {
        posture: 20,
        movePreference: 0,
        switchGainPct: 0.30,
        options: {
            neverSendWeakMatchup: true,
            avoidDoubleWeakness: true,
            skipIfCanFinish: true,
            respectPreferredActive: true,
        },
    },
    balanced: {
        posture: 50,
        movePreference: 0,
        switchGainPct: 0.20,
        options: {
            neverSendWeakMatchup: true,
            avoidDoubleWeakness: true,
            skipIfCanFinish: true,
            respectPreferredActive: true,
        },
    },
    aggressive: {
        posture: 85,
        movePreference: 0,
        switchGainPct: 0.15,
        options: {
            neverSendWeakMatchup: true,
            avoidDoubleWeakness: false,
            skipIfCanFinish: true,
            respectPreferredActive: false,
        },
    },
};

/** Classic type advantage/disadvantage switches are superseded once Auto Fight Advanced is owned. */
export function usesLegacyTypeAutoSwitch(game: GameRuntime): boolean {
    return !game.unlockedFeatures?.autoFightAdvanced;
}

/** Optimal move simulation is always on when Auto Fight Advanced is owned. */
export function usesOptimalMoveSelection(game: GameRuntime): boolean {
    if (game.unlockedFeatures?.autoFightAdvanced) return true;
    return !!game.optimalMoveSelection;
}

const AUTO_CFG = (BALANCE.AUTO_SWITCH || {}) as Record<string, number>;
/** Double type weakness threshold in Poketime chart (1.5 × 1.5). */
export const DOUBLE_WEAKNESS_MULT = 2.25;

export function defaultAutoFightAdvancedOptions(): AutoFightAdvancedOptions {
    return {
        neverSendWeakMatchup: true,
        avoidDoubleWeakness: true,
        minHpPct: 0.25,
        skipIfCanFinish: true,
        minScoreGainPct: 0.20,
        respectPreferredActive: true,
        excludedSwitchIndices: [],
        preferXpEligible: false,
    };
}

/** True when combat XP can still change this creature's level. */
export function creatureCanGainCombatXp(game: GameRuntime, creature: CreatureData): boolean {
    if (!creature) return false;
    if (typeof creature.isAtMaxLevel === 'function' && creature.isAtMaxLevel()) return false;
    if (typeof game.isCreatureInUltimateSlot === 'function' && game.isCreatureInUltimateSlot(creature)) {
        return false;
    }
    return true;
}

export function getXpModeScoreFactor(
    game: GameRuntime,
    creature: CreatureData,
    options: AutoFightAdvancedOptions,
): number {
    if (!options.preferXpEligible) return 1;
    const cfg = AUTO_CFG;
    const malus = cfg.XP_MODE_MAX_MALUS ?? 0.85;
    const bonus = cfg.XP_MODE_ELIGIBLE_BONUS ?? 1.15;
    return creatureCanGainCombatXp(game, creature) ? bonus : malus;
}

/** One-time migration for saves that already owned Auto Fight Advanced before UI cleanup. */
export function migrateAutoFightAdvancedOwned(game: GameRuntime): void {
    if (!game.unlockedFeatures?.autoFightAdvanced) return;
    if (game._autoFightAdvancedMigratedV1) return;
    game._autoFightAdvancedMigratedV1 = true;

    game.autoSwitchAdvanced = true;
    game.optimalMoveSelection = true;
    game.autoSwitchDisadvantage = false;
    game.autoSwitchAdvantage = false;

    if (!game.autoFightAdvancedOptions || typeof game.autoFightAdvancedOptions !== 'object') {
        game.autoFightAdvancedOptions = defaultAutoFightAdvancedOptions();
        return;
    }
    const opts = game.autoFightAdvancedOptions;
    if (opts.respectPreferredActive === undefined) {
        opts.respectPreferredActive = true;
    }
    if (!Array.isArray(opts.excludedSwitchIndices)) {
        opts.excludedSwitchIndices = [];
    }
    if (!game.autoFightAdvancedPreset) {
        game.autoFightAdvancedPreset = detectAutoFightAdvancedPreset(game);
    }
}

function getActionThreshold(entity: CreatureData | null | undefined): number {
    const t = Number(entity?.actionThreshold);
    const def = BALANCE.ATB_ACTION_THRESHOLD ?? 10000;
    return Number.isFinite(t) && t > 0 ? t : def;
}

/** Mid-combat auto switch only when no combatant is ready to act and no attack is playing. */
export function canAutoSwitchAtAtbBreakpoint(game: GameRuntime): boolean {
    if (game.isAttacking) return false;
    const player = game.currentPlayerCreature;
    const enemy = game.currentEnemy;
    if (!player || !enemy) return false;
    const pThreshold = getActionThreshold(player);
    const eThreshold = getActionThreshold(enemy);
    const pGauge = Number(player.actionGauge) || 0;
    const eGauge = Number(enemy.actionGauge) || 0;
    return pGauge < pThreshold && eGauge < eThreshold;
}

function presetValuesMatch(game: GameRuntime, preset: Exclude<AutoFightAdvancedPreset, 'custom'>): boolean {
    const ref = AUTO_FIGHT_ADVANCED_PRESETS[preset];
    const opts = game.autoFightAdvancedOptions ?? defaultAutoFightAdvancedOptions();
    const gain = typeof opts.minScoreGainPct === 'number'
        ? opts.minScoreGainPct
        : (AUTO_CFG.MIN_SCORE_GAIN_ADVANCED ?? 0.20);
    if ((game.autoFightSwitchPosture ?? 50) !== ref.posture) return false;
    if ((game.autoFightMovePreference ?? 0) !== ref.movePreference) return false;
    if (Math.abs(gain - ref.switchGainPct) > 0.001) return false;
    for (const key of Object.keys(ref.options) as Array<keyof AutoFightAdvancedPresetValues['options']>) {
        if (opts[key] !== ref.options[key]) return false;
    }
    return true;
}

export function detectAutoFightAdvancedPreset(game: GameRuntime): AutoFightAdvancedPreset {
    if (presetValuesMatch(game, 'safe')) return 'safe';
    if (presetValuesMatch(game, 'balanced')) return 'balanced';
    if (presetValuesMatch(game, 'aggressive')) return 'aggressive';
    return 'custom';
}

export function applyAutoFightAdvancedPreset(
    game: GameRuntime,
    preset: AutoFightAdvancedPreset,
): void {
    if (preset === 'custom') {
        game.autoFightAdvancedPreset = 'custom';
        return;
    }
    const ref = AUTO_FIGHT_ADVANCED_PRESETS[preset];
    game._applyingAutoFightPreset = true;
    try {
        game.autoFightSwitchPosture = ref.posture;
        game.autoFightMovePreference = ref.movePreference;
        if (!game.autoFightAdvancedOptions || typeof game.autoFightAdvancedOptions !== 'object') {
            game.autoFightAdvancedOptions = defaultAutoFightAdvancedOptions();
        }
        const opts = game.autoFightAdvancedOptions;
        opts.minScoreGainPct = ref.switchGainPct;
        opts.neverSendWeakMatchup = ref.options.neverSendWeakMatchup;
        opts.avoidDoubleWeakness = ref.options.avoidDoubleWeakness;
        opts.skipIfCanFinish = ref.options.skipIfCanFinish;
        opts.respectPreferredActive = ref.options.respectPreferredActive;
        game.autoFightAdvancedPreset = preset;
    } finally {
        game._applyingAutoFightPreset = false;
    }
}

export function resolvePreferredActiveIndex(_game: GameRuntime): number {
    return 0;
}

export function isPreferredActiveSlot(game: GameRuntime): boolean {
    return game.activeCreatureIndex === 0;
}

/** Block advanced switch at combat entry when team slot 0 is active. */
export function shouldBlockAdvancedEntrySwitch(game: GameRuntime): boolean {
    const opts = game.autoFightAdvancedOptions;
    if (!opts?.respectPreferredActive) return false;
    return isPreferredActiveSlot(game);
}

function isExcludedSwitchIndex(game: GameRuntime, index: number): boolean {
    const list = game.autoFightAdvancedOptions?.excludedSwitchIndices;
    if (!Array.isArray(list)) return false;
    return list.includes(index);
}

export interface AdvancedSwitchScore {
    defScore: number;
    offScore: number;
    combined: number;
}

export interface AdvancedSwitchCandidate {
    index: number;
    creature: CreatureData;
    score: AdvancedSwitchScore;
}

export function getPlayerHpRatioForScoring(game: GameRuntime, creature: CreatureData): number {
    return getAttackerHpRatio(game, creature as unknown as ICreature);
}

function getEffectiveHp(game: GameRuntime, creature: CreatureData): number {
    if (isTrainerBattle(game)) {
        const max = creature.maxHp || (creature.stats && (creature.stats as { HP?: number }).HP) || 1;
        return Math.max(1, creature.currentHp || 0) || max * getPlayerHpRatioForScoring(game, creature);
    }
    const maxHp = typeof game.getPlayerMaxHp === 'function' ? game.getPlayerMaxHp() : (creature.maxHp || 1);
    const cur = creature.mainAccountCurrentHp ?? 0;
    return Math.max(1, cur > 0 ? cur : maxHp * getPlayerHpRatioForScoring(game, creature));
}

export function estimateBestMoveDamage(
    game: GameRuntime,
    attacker: CreatureData,
    target: CreatureData,
    asEnemy: boolean,
): number {
    const moves = attacker.currentMoves || [];
    if (!moves.length) return 0;

    const proxyAttacker = { ...attacker, isEnemy: asEnemy } as unknown as ICreature;
    const proxyTarget = { ...target, isEnemy: !asEnemy } as unknown as ICreature;

    let best = 0;
    for (const moveName of moves) {
        const moveDef = getMoveDefinition(moveName);
        if (!moveDef) continue;
        const dmg = estimatePlayerMoveDamageForSelection(game, proxyAttacker, proxyTarget, moveDef as Record<string, unknown>);
        if (dmg > best) best = dmg;
    }
    return best;
}

export function estimateDefensiveTypeFactor(enemy: CreatureData, player: CreatureData): number {
    const moves = enemy.currentMoves || [];
    if (!moves.length) return 1;
    let worst = 1;
    for (const moveName of moves) {
        const moveDef = getMoveDefinition(moveName);
        if (!moveDef || !moveDef.type) continue;
        const mult = getTypeMultiplier(
            moveDef.type as string,
            player.type,
            player.secondaryType ?? null,
        );
        if (mult < worst) worst = mult;
    }
    return worst;
}

function getOffensiveEffectiveness(game: GameRuntime, creature: CreatureData, enemy: CreatureData): number {
    if (typeof game.getCreatureVsEnemyEffectiveness === 'function') {
        return game.getCreatureVsEnemyEffectiveness(creature, enemy);
    }
    let eff = getTypeMultiplier(creature.type, enemy.type, enemy.secondaryType ?? null);
    if (creature.secondaryType) {
        eff = Math.max(eff, getTypeMultiplier(creature.secondaryType, enemy.type, enemy.secondaryType ?? null));
    }
    return eff;
}

/** Type of the player move that deals the most simulated damage to the given enemy candidate. */
export function getWorstPlayerMoveTypeAgainst(
    game: GameRuntime,
    player: CreatureData,
    enemyMember: CreatureData,
): string | null {
    const moves = player.currentMoves || [];
    if (!moves.length) return player.type ?? null;

    const proxyAttacker = { ...player, isEnemy: false } as unknown as ICreature;
    const proxyTarget = { ...enemyMember, isEnemy: true } as unknown as ICreature;

    let bestDmg = 0;
    let bestType: string | null = null;
    for (const moveName of moves) {
        const moveDef = getMoveDefinition(moveName);
        if (!moveDef) continue;
        const dmg = estimatePlayerMoveDamageForSelection(
            game,
            proxyAttacker,
            proxyTarget,
            moveDef as Record<string, unknown>,
        );
        if (dmg > bestDmg) {
            bestDmg = dmg;
            bestType = typeof moveDef.type === 'string' ? moveDef.type : null;
        }
    }
    return bestType ?? player.type ?? null;
}

/** Type of the enemy move that deals the most simulated damage to the given player candidate. */
export function getWorstEnemyMoveTypeAgainst(
    game: GameRuntime,
    enemy: CreatureData,
    player: CreatureData,
): string | null {
    const moves = enemy.currentMoves || [];
    if (!moves.length) return enemy.type ?? null;

    const proxyAttacker = { ...enemy, isEnemy: true } as unknown as ICreature;
    const proxyTarget = { ...player, isEnemy: false } as unknown as ICreature;

    let bestDmg = 0;
    let bestType: string | null = null;
    for (const moveName of moves) {
        const moveDef = getMoveDefinition(moveName);
        if (!moveDef) continue;
        const dmg = estimatePlayerMoveDamageForSelection(
            game,
            proxyAttacker,
            proxyTarget,
            moveDef as Record<string, unknown>,
        );
        if (dmg > bestDmg) {
            bestDmg = dmg;
            bestType = typeof moveDef.type === 'string' ? moveDef.type : null;
        }
    }
    return bestType ?? enemy.type ?? null;
}

export function hasDoubleWeakness(creature: CreatureData, offensiveType: string | null): boolean {
    if (!offensiveType || !creature.secondaryType) return false;
    const mult = getTypeMultiplier(
        offensiveType,
        creature.type,
        creature.secondaryType,
    );
    return mult >= DOUBLE_WEAKNESS_MULT;
}

/** Vitesse effective pour le scoring switch (alignée sur updateATBLogic). */
export function getCreatureSpeedForScoring(game: GameRuntime, creature: CreatureData): number {
    let speed = Number(creature.speed) || 1;
    if (typeof game.getEffectiveStats === 'function') {
        const stats = game.getEffectiveStats(creature as unknown as ICreature);
        const fromStats = Number(stats?.speed);
        if (Number.isFinite(fromStats) && fromStats > 0) {
            speed = fromStats;
        }
    }
    const creatureAsIc = creature as unknown as ICreature;
    if (typeof creatureAsIc.getSpeedMultiplier === 'function') {
        speed *= creatureAsIc.getSpeedMultiplier(game);
    }
    return Math.max(1, speed);
}

/**
 * Facteur posture-dépendant : pénalise offScore si le candidat est plus lent que l'ennemi.
 * Gate survie : 0 si plus lent et le premier coup entrant tue avant d'agir.
 */
export function computeSpeedOffenseFactor(
    playerSpeed: number,
    enemySpeed: number,
    posture: number,
    opts?: { incomingDamage?: number; effectiveHp?: number },
): number {
    const wOff = Math.max(0, Math.min(1, posture / 100));
    if (wOff <= 0) return 1;

    const pSpd = Math.max(1, playerSpeed);
    const eSpd = Math.max(1, enemySpeed);

    if (
        pSpd < eSpd
        && typeof opts?.incomingDamage === 'number'
        && typeof opts?.effectiveHp === 'number'
        && opts.incomingDamage >= opts.effectiveHp
    ) {
        return 0;
    }

    const ratio = Math.min(pSpd, eSpd) / Math.max(pSpd, eSpd);
    return 1 - wOff * (1 - ratio);
}

function getMemberOffensiveEffectiveness(
    game: GameRuntime,
    member: CreatureData,
    opponent: CreatureData,
    memberIsEnemy: boolean,
): number {
    if (!memberIsEnemy) {
        return getOffensiveEffectiveness(game, member, opponent);
    }
    let eff = getTypeMultiplier(member.type, opponent.type, opponent.secondaryType ?? null);
    if (member.secondaryType) {
        eff = Math.max(eff, getTypeMultiplier(member.secondaryType, opponent.type, opponent.secondaryType ?? null));
    }
    return eff;
}

function getMemberEffectiveHp(
    game: GameRuntime,
    member: CreatureData,
    memberIsEnemy: boolean,
): number {
    if (memberIsEnemy) {
        const max = member.maxHp || (member.stats && (member.stats as { HP?: number }).HP) || 1;
        const cur = member.currentHp || 0;
        return Math.max(1, cur > 0 ? cur : max * getPlayerHpRatioForScoring(game, member));
    }
    return getEffectiveHp(game, member);
}

/**
 * Score EHP/offense for a team member vs an opponent (player bench vs enemy, or enemy bench vs player).
 */
export function scoreMemberVsOpponentRaw(
    game: GameRuntime,
    member: CreatureData,
    opponent: CreatureData,
    options: AutoFightAdvancedOptions,
    posture: number,
    memberIsEnemy: boolean,
): Pick<AdvancedSwitchScore, 'defScore' | 'offScore'> {
    const incoming = estimateBestMoveDamage(game, opponent, member, !memberIsEnemy);
    const typeDefFactor = estimateDefensiveTypeFactor(opponent, member);
    const effectiveHp = getMemberEffectiveHp(game, member, memberIsEnemy);
    let defScore: number;
    if (!isTrainerBattle(game) && !memberIsEnemy) {
        defScore = Math.max(0.25, typeDefFactor) / Math.max(1, incoming);
    } else {
        defScore = (effectiveHp / Math.max(1, incoming)) * Math.max(0.25, typeDefFactor);
    }

    let offScore = estimateBestMoveDamage(game, member, opponent, memberIsEnemy);
    const eff = getMemberOffensiveEffectiveness(game, member, opponent, memberIsEnemy);
    offScore *= Math.max(0.5, eff);

    const memberSpeed = getCreatureSpeedForScoring(game, member);
    const opponentSpeed = getCreatureSpeedForScoring(game, opponent);
    offScore *= computeSpeedOffenseFactor(memberSpeed, opponentSpeed, posture, {
        incomingDamage: incoming,
        effectiveHp,
    });

    const xpFactor = memberIsEnemy ? 1 : getXpModeScoreFactor(game, member, options);
    defScore *= xpFactor;
    offScore *= xpFactor;

    return { defScore, offScore };
}

function scoreCreatureRaw(
    game: GameRuntime,
    creature: CreatureData,
    enemy: CreatureData,
    options: AutoFightAdvancedOptions,
    posture: number,
): Pick<AdvancedSwitchScore, 'defScore' | 'offScore'> {
    return scoreMemberVsOpponentRaw(game, creature, enemy, options, posture, false);
}

export function applyNormalizedCombined(
    entries: Array<{ index: number; creature: CreatureData; defScore: number; offScore: number }>,
    posture: number,
): AdvancedSwitchCandidate[] {
    const maxDef = Math.max(1, ...entries.map((e) => e.defScore));
    const maxOff = Math.max(1, ...entries.map((e) => e.offScore));
    const wOff = Math.max(0, Math.min(1, posture / 100));
    const wDef = 1 - wOff;
    const pureOffense = posture >= 100;

    return entries.map((e) => ({
        index: e.index,
        creature: e.creature,
        score: {
            defScore: e.defScore,
            offScore: e.offScore,
            combined: pureOffense
                ? e.offScore / maxOff
                : (e.defScore / maxDef) * wDef + (e.offScore / maxOff) * wOff,
        },
    }));
}

/** Score brut + combined non normalisé (legacy / tests unitaires sur offScore). */
export function scoreCreatureForAdvancedSwitch(
    game: GameRuntime,
    creature: CreatureData,
    enemy: CreatureData,
    posture: number,
    options: AutoFightAdvancedOptions,
): AdvancedSwitchScore {
    const { defScore, offScore } = scoreCreatureRaw(game, creature, enemy, options, posture);
    const normalized = applyNormalizedCombined(
        [{ index: 0, creature, defScore, offScore }],
        posture,
    );
    return normalized[0]?.score ?? { defScore, offScore, combined: 0 };
}

/**
 * Candidats avec scores normalisés sur l'équipe (max def/off) puis pondérés par posture.
 * `excludeIndex` : exclure un slot (ex. actif pour un switch).
 */
export function buildNormalizedAdvancedCandidates(
    game: GameRuntime,
    opts?: {
        excludeIndex?: number;
        minPp?: number;
        posture?: number;
        options?: AutoFightAdvancedOptions;
    },
): AdvancedSwitchCandidate[] {
    const enemy = game.currentEnemy;
    if (!enemy || !Array.isArray(game.playerTeam) || game.playerTeam.length === 0) return [];

    const posture = typeof opts?.posture === 'number' ? opts.posture : (game.autoFightSwitchPosture ?? 50);
    const options = opts?.options ?? game.autoFightAdvancedOptions;
    const minPp = typeof opts?.minPp === 'number' ? opts.minPp : 3;
    const excludeIndex = opts?.excludeIndex;

    const rawEntries: Array<{ index: number; creature: CreatureData; defScore: number; offScore: number }> = [];
    for (let i = 0; i < game.playerTeam.length; i++) {
        if (typeof excludeIndex === 'number' && i === excludeIndex) continue;
        if (isExcludedSwitchIndex(game, i)) continue;
        const creature = game.playerTeam[i];
        if (!creature?.isAlive?.()) continue;
        if (typeof game.creatureHasUsableMoves === 'function' && !game.creatureHasUsableMoves(creature, minPp)) {
            continue;
        }
        if (!passesAdvancedSwitchFilters(game, creature, enemy, options)) continue;

        const { defScore, offScore } = scoreCreatureRaw(game, creature, enemy, options, posture);
        rawEntries.push({ index: i, creature, defScore, offScore });
    }

    if (!rawEntries.length) return [];
    return applyNormalizedCombined(rawEntries, posture);
}

/**
 * Normalized switch candidates for an arbitrary team vs a single opponent.
 * Used by enemy Subway AI (enemy bench vs player active).
 */
export function buildNormalizedMemberVsOpponentCandidates(
    game: GameRuntime,
    team: CreatureData[],
    opponent: CreatureData,
    opts: {
        excludeIndex?: number;
        posture?: number;
        options?: AutoFightAdvancedOptions;
        memberIsEnemy?: boolean;
        passesFilters?: (
            game: GameRuntime,
            member: CreatureData,
            opponent: CreatureData,
            options: AutoFightAdvancedOptions,
        ) => boolean;
    },
): AdvancedSwitchCandidate[] {
    if (!team.length || !opponent) return [];

    const posture = typeof opts.posture === 'number' ? opts.posture : 50;
    const options = opts?.options ?? defaultAutoFightAdvancedOptions();
    const memberIsEnemy = opts.memberIsEnemy === true;
    const excludeIndex = opts.excludeIndex;
    const filterFn = opts.passesFilters ?? passesAdvancedSwitchFilters;

    const rawEntries: Array<{ index: number; creature: CreatureData; defScore: number; offScore: number }> = [];
    for (let i = 0; i < team.length; i++) {
        if (typeof excludeIndex === 'number' && i === excludeIndex) continue;
        const member = team[i];
        if (!member?.isAlive?.()) continue;
        if (!filterFn(game, member, opponent, options)) continue;

        const { defScore, offScore } = scoreMemberVsOpponentRaw(
            game,
            member,
            opponent,
            options,
            posture,
            memberIsEnemy,
        );
        rawEntries.push({ index: i, creature: member, defScore, offScore });
    }

    if (!rawEntries.length) return [];
    return applyNormalizedCombined(rawEntries, posture);
}

function getNormalizedScoreForTeamMember(
    game: GameRuntime,
    index: number,
    posture: number,
    options: AutoFightAdvancedOptions,
    minPp: number = 3,
): AdvancedSwitchScore | null {
    const all = buildNormalizedAdvancedCandidates(game, { posture, options, minPp });
    const found = all.find((c) => c.index === index);
    return found?.score ?? null;
}

export function passesAdvancedSwitchFilters(
    game: GameRuntime,
    creature: CreatureData,
    enemy: CreatureData,
    options: AutoFightAdvancedOptions,
): boolean {
    const eff = getOffensiveEffectiveness(game, creature, enemy);
    if (options.neverSendWeakMatchup && eff < 1) return false;

    const hpRatio = getPlayerHpRatioForScoring(game, creature);
    const minHp = typeof options.minHpPct === 'number' ? options.minHpPct : (AUTO_CFG.MIN_HP_PCT_ADVANCED ?? 0.25);
    if (hpRatio < minHp) return false;

    if (options.avoidDoubleWeakness) {
        const threatType = getWorstEnemyMoveTypeAgainst(game, enemy, creature);
        if (hasDoubleWeakness(creature, threatType)) return false;
    }

    return true;
}

type CombatStatQuad = { attack: number; spattack: number; defense: number; spdefense: number };

export type PlayerMoveSelectionCtx = {
    effectiveAttacker?: CombatStatQuad;
    attackerStatsIncludeTalentMult?: boolean;
    bonusDamageMult?: number;
    ultimateDamageMult?: number;
    ultimateDefensePen?: number;
    ultimateHits?: number;
    towerBuffs?: Record<string, unknown>;
};

/** True when an auto-advanced player move deals real damage (not type-immune, not 0-power status). */
export function isPlayerAdvancedViableMove(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    moveDef: Record<string, unknown> | null | undefined,
    ctx: PlayerMoveSelectionCtx = {},
): boolean {
    if (!moveDef) return false;
    const moveType = typeof moveDef.type === 'string' ? moveDef.type : '';
    if (moveType && isTypeImmune(moveType, target.type, target.secondaryType ?? null)) {
        return false;
    }
    const dmg = estimatePlayerMoveDamageForSelection(
        game,
        attacker,
        target,
        moveDef,
        ctx,
    );
    return dmg > 0;
}

/**
 * Auto-advanced: honor rampage lock only when the forced move deals real damage.
 * Clears furie when the locked move is immune / 0 dmg. Non-advanced: always honor.
 */
export function shouldHonorRampageLock(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    ctx: PlayerMoveSelectionCtx = {},
): boolean {
    const forced = resolveForcedRampageMove(attacker);
    if (!forced) return false;
    if (attacker.isEnemy || !game.unlockedFeatures?.autoFightAdvanced) {
        return true;
    }
    const moveDef = getMoveDefinition(forced);
    if (isPlayerAdvancedViableMove(game, attacker, target, moveDef, ctx)) {
        return true;
    }
    clearRampageState(attacker);
    return false;
}

/** Clear active player furie when the locked move cannot hurt the current enemy (auto advanced). */
export function clearPlayerRampageIfNotViable(
    game: GameRuntime,
    player: CreatureData | ICreature,
    enemy: CreatureData | ICreature,
): void {
    const playerIc = player as unknown as ICreature;
    if (playerIc.isEnemy || !game.unlockedFeatures?.autoFightAdvanced) return;
    if (!resolveForcedRampageMove(playerIc)) return;

    let sourceStats: CombatStatQuad | null = null;
    if (typeof game.getEffectiveStats === 'function') {
        sourceStats = game.getEffectiveStats(playerIc) as CombatStatQuad;
    }
    const ctx: PlayerMoveSelectionCtx = {
        effectiveAttacker: resolveAttackerStats(playerIc, sourceStats),
        attackerStatsIncludeTalentMult: sourceStats !== null,
    };
    shouldHonorRampageLock(game, playerIc, enemy as unknown as ICreature, ctx);
}

/** Dégâts du move que l'auto jouerait en combat live (aligné sur performAttackWithBonusLogic). */
export function estimateActiveCombatMoveDamage(
    game: GameRuntime,
    active: CreatureData,
    enemy: CreatureData,
): number {
    const activeIc = active as unknown as ICreature;
    const enemyIc = enemy as unknown as ICreature;

    let sourceStats: CombatStatQuad | null = null;
    if (!active.isEnemy && typeof game.getEffectiveStats === 'function') {
        sourceStats = game.getEffectiveStats(activeIc) as CombatStatQuad;
    }
    const effStats = resolveAttackerStats(activeIc, sourceStats);
    const ctx = {
        effectiveAttacker: effStats,
        attackerStatsIncludeTalentMult: sourceStats !== null,
    };

    let moveName = '';
    if (!active.isEnemy && usesOptimalMoveSelection(game)) {
        moveName = pickBestMoveBySimulatedDamage(game, activeIc, enemyIc, ctx);
    }
    if (!moveName) {
        if (game.unlockedFeatures?.autoFightAdvanced) {
            moveName = findFirstPlayerAdvancedViableMove(game, activeIc, enemyIc, ctx);
        } else {
            moveName = (typeof activeIc.getMove === 'function' ? activeIc.getMove() : '')
                || active.currentMoves?.[0]
                || '';
        }
    } else if (game.unlockedFeatures?.autoFightAdvanced) {
        const pickedDef = getMoveDefinition(moveName);
        if (!isPlayerAdvancedViableMove(game, activeIc, enemyIc, pickedDef, ctx)) {
            moveName = findFirstPlayerAdvancedViableMove(game, activeIc, enemyIc, ctx);
        }
    }

    if (!moveName) return 0;

    const moveDef = getMoveDefinition(moveName);
    if (!moveDef) return 0;

    const dmg = estimatePlayerMoveDamageForSelection(
        game,
        activeIc,
        enemyIc,
        moveDef as Record<string, unknown>,
        ctx,
    );
    return dmg > 0 ? dmg : 0;
}

function passesForcedAdvancedSwitchFilters(
    game: GameRuntime,
    creature: CreatureData,
    enemy: CreatureData,
    options: AutoFightAdvancedOptions,
): boolean {
    const hpRatio = getPlayerHpRatioForScoring(game, creature);
    const minHp = typeof options.minHpPct === 'number'
        ? options.minHpPct
        : (AUTO_CFG.MIN_HP_PCT_ADVANCED ?? 0.25);
    if (hpRatio < minHp) return false;

    if (options.avoidDoubleWeakness) {
        const threatType = getWorstEnemyMoveTypeAgainst(game, enemy, creature);
        if (hasDoubleWeakness(creature, threatType)) return false;
    }

    return true;
}

/** Bench pick for forced switch — ignores neverSendWeakMatchup; requires real combat move damage > 0. */
export function pickBestAdvancedForcedSwitchTarget(
    game: GameRuntime,
    opts?: {
        excludeIndex?: number;
        minPp?: number;
        options?: AutoFightAdvancedOptions;
    },
): AdvancedSwitchCandidate | null {
    const enemy = game.currentEnemy;
    if (!enemy || !Array.isArray(game.playerTeam) || game.playerTeam.length === 0) return null;

    const options = opts?.options ?? game.autoFightAdvancedOptions ?? defaultAutoFightAdvancedOptions();
    const minPp = typeof opts?.minPp === 'number' ? opts.minPp : 3;
    const excludeIndex = typeof opts?.excludeIndex === 'number'
        ? opts.excludeIndex
        : game.activeCreatureIndex;

    let bestIndex = -1;
    let bestDmg = 0;
    let bestCreature: CreatureData | null = null;

    for (let i = 0; i < game.playerTeam.length; i++) {
        if (typeof excludeIndex === 'number' && i === excludeIndex) continue;
        if (isExcludedSwitchIndex(game, i)) continue;
        const creature = game.playerTeam[i];
        if (!creature?.isAlive?.()) continue;
        if (typeof game.creatureHasUsableMoves === 'function' && !game.creatureHasUsableMoves(creature, minPp)) {
            continue;
        }
        if (!passesForcedAdvancedSwitchFilters(game, creature, enemy, options)) continue;

        const dmg = estimateActiveCombatMoveDamage(game, creature, enemy);
        if (dmg > bestDmg) {
            bestDmg = dmg;
            bestIndex = i;
            bestCreature = creature;
        }
    }

    if (bestIndex < 0 || !bestCreature) return null;

    const posture = game.autoFightSwitchPosture ?? 50;
    const score = scoreCreatureForAdvancedSwitch(game, bestCreature, enemy, posture, options);
    return { index: bestIndex, creature: bestCreature, score };
}

/** True when the active Pokémon's auto-selected move deals damage (immunity / 0-power moves → false). */
export function canActiveDealDamage(
    game: GameRuntime,
    active: CreatureData,
    enemy: CreatureData,
): boolean {
    return estimateActiveCombatMoveDamage(game, active, enemy) > 0;
}

export function canActiveFinishEnemy(
    game: GameRuntime,
    active: CreatureData,
    enemy: CreatureData,
    maxHits: number = AUTO_CFG.FINISH_KILL_MAX_HITS ?? 2,
): boolean {
    const perHit = estimateBestMoveDamage(game, active, enemy, false);
    if (perHit <= 0) return false;
    const enemyHp = enemy.currentHp || enemy.currentHP || enemy.maxHp || 1;
    return perHit * maxHits >= enemyHp;
}

/**
 * Force-switch when the active cannot hurt the enemy but a bench Pokémon can.
 * Mirrors legacy disadvantage-on-immunity without re-enabling legacy toggles.
 */
export function shouldForceAdvancedSwitchOnNoDamage(
    game: GameRuntime,
    active: CreatureData,
    best: AdvancedSwitchCandidate,
    options: AutoFightAdvancedOptions,
): boolean {
    const enemy = game.currentEnemy;
    if (!enemy) return false;
    if (options.skipIfCanFinish && canActiveFinishEnemy(game, active, enemy)) return false;
    if (canActiveDealDamage(game, active, enemy)) return false;
    return estimateActiveCombatMoveDamage(game, best.creature, enemy) > 0;
}

export function pickBestAdvancedSwitchTarget(
    game: GameRuntime,
    opts?: {
        excludeIndex?: number;
        minPp?: number;
        posture?: number;
        options?: AutoFightAdvancedOptions;
    },
): AdvancedSwitchCandidate | null {
    const excludeIndex = typeof opts?.excludeIndex === 'number' ? opts.excludeIndex : game.activeCreatureIndex;
    const candidates = buildNormalizedAdvancedCandidates(game, { ...opts, excludeIndex });
    if (!candidates.length) return null;
    candidates.sort((a, b) => b.score.combined - a.score.combined);
    return candidates[0] ?? null;
}

/** Best team slot at combat entry — uses same gain threshold as mid-combat unless entry blocked. */
export function pickBestAdvancedEntryTarget(
    game: GameRuntime,
    opts?: {
        minPp?: number;
        posture?: number;
        options?: AutoFightAdvancedOptions;
    },
): AdvancedSwitchCandidate | null {
    if (shouldBlockAdvancedEntrySwitch(game)) return null;

    const options = opts?.options ?? game.autoFightAdvancedOptions;
    const active = Array.isArray(game.playerTeam)
        ? game.playerTeam[game.activeCreatureIndex]
        : null;
    if (!active) return null;

    const best = pickBestAdvancedSwitchTarget(game, opts);
    if (!best || best.index === game.activeCreatureIndex) return null;
    if (!shouldAdvancedSwitch(game, active, best, options)) return null;
    return best;
}

/** Apply advanced offline entry switch with threshold + respect preferred. */
export function tryAdvancedOfflineEntrySwitch(game: GameRuntime): boolean {
    if (shouldBlockAdvancedEntrySwitch(game)) return false;

    const active = Array.isArray(game.playerTeam)
        ? game.playerTeam[game.activeCreatureIndex]
        : null;
    if (!active) return false;

    const options = game.autoFightAdvancedOptions;
    const best = pickBestAdvancedSwitchTarget(game as GameRuntime, {
        posture: game.autoFightSwitchPosture,
        options,
    });
    if (!best || best.index === game.activeCreatureIndex) return false;
    if (!shouldAdvancedSwitch(game, active, best, options)) return false;

    game.activeCreatureIndex = best.index;
    game.currentPlayerCreature = game.playerTeam[best.index] ?? null;
    return true;
}

export function shouldAdvancedSwitch(
    game: GameRuntime,
    active: CreatureData,
    best: AdvancedSwitchCandidate,
    options: AutoFightAdvancedOptions,
): boolean {
    const enemy = game.currentEnemy;
    if (!enemy) return false;

    if (shouldForceAdvancedSwitchOnNoDamage(game, active, best, options)) {
        return true;
    }

    if (options.skipIfCanFinish && canActiveFinishEnemy(game, active, enemy)) {
        return false;
    }

    const posture = game.autoFightSwitchPosture ?? 50;
    const activeIndex = game.activeCreatureIndex;
    const activeScore = typeof activeIndex === 'number' && activeIndex >= 0
        ? getNormalizedScoreForTeamMember(game, activeIndex, posture, options)
        : null;
    const gainPct = typeof options.minScoreGainPct === 'number'
        ? options.minScoreGainPct
        : (AUTO_CFG.MIN_SCORE_GAIN_ADVANCED ?? 0.20);

    const bestCombined = best.score.combined;
    const activeCombined = activeScore?.combined ?? 0;

    if (activeCombined <= 0) {
        return bestCombined > 0;
    }

    const relativeGain = (bestCombined - activeCombined) / activeCombined;
    return relativeGain >= gainPct;
}
