import type { GameRuntime } from '../types/game.js';

/** Plafond gameplay Mémoire d'Ascension (30 niveaux boutique × +1 %). */
export const TOWER_ASCENT_MEMORY_MAX_PCT = 0.30;

export function getTowerAscentMemoryStartPct(game: GameRuntime): number {
  return Math.min(TOWER_ASCENT_MEMORY_MAX_PCT, Math.max(0, Number((game.permanentBoosts && game.permanentBoosts.tower_start_pct) || 0)));
}

export function getTowerAscentMemoryMaxStartFloor(game: GameRuntime): number {
  const towerRecord = Math.max(0, Number(game.towerRecord) || 0);
  const startFloorBonus = Math.floor(towerRecord * getTowerAscentMemoryStartPct(game));
  return Math.max(1, 1 + startFloorBonus);
}

export function normalizeTowerAscentStartFloor(game: GameRuntime): void {
  const max = getTowerAscentMemoryMaxStartFloor(game);
  let preferred = Math.floor(Number(game.towerAscentStartFloor) || 0);
  if (!preferred || preferred > max) preferred = max;
  game.towerAscentStartFloor = Math.min(max, Math.max(1, preferred));
}

export function resolveTowerStartFloor(game: GameRuntime): number {
  normalizeTowerAscentStartFloor(game);
  return game.towerAscentStartFloor;
}
