/**
 * @file src/lib/rollCreatureCritHit.ts
 * Tirage critique par coup (multi-hit, attaques simples).
 */

import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';
import { getMoveCritRateBonus } from './moveCombatModifiers.ts';

export interface RollCreatureCritHitOptions {
    towerBuffs?: Record<string, number> | null;
    /** Ratio PV cible (Executor : crit forcé si < 30 %). */
    targetHealthRatio?: number;
    heldCritChance?: number;
    moveDef?: Record<string, unknown> | null;
    random?: () => number;
}

export function rollCreatureCritHit(
    game: GameRuntime,
    attacker: ICreature,
    opts: RollCreatureCritHitOptions = {},
): boolean {
    const {
        towerBuffs = null,
        targetHealthRatio = 1,
        heldCritChance = 0,
        moveDef = null,
        random = Math.random,
    } = opts;

    const moveCritBonus = getMoveCritRateBonus(moveDef);

    if (!attacker.isEnemy) {
        if (towerBuffs?.crit_chance && random() < towerBuffs.crit_chance) return true;
        if (game.upgrades?.['executor'] && targetHealthRatio < 0.30) return true;
        const critChance = (typeof game.getCreatureCritChance === 'function')
            ? game.getCreatureCritChance(attacker)
            : (0.05 + heldCritChance);
        return random() < Math.min(1, critChance + moveCritBonus);
    }
    return random() < Math.min(1, 0.05 + heldCritChance + moveCritBonus);
}
