/**
 * @file combatCaptureLogic.ts
 * Auto-catch during combat — extracted from combatSystem to avoid importing team.svelte store.
 */

import type { GameRuntime } from '../types/game.js';
import {
    isAutoCatchSpecialEligible,
    pickAutoCatchBall,
    resolveAutoCatchCaptureContext,
} from './autoCatchBallPicker.ts';

export function triggerAutoCatchLogic(game: GameRuntime): boolean {
    if (!game.currentEnemy) return false;
    if (!game.hasAutoCatcher) return false;
    if (game.combatState === 'capture') return false;
    if (game.towerState.isActive || game.arenaState.active || (game.gymTrainerState && game.gymTrainerState.active) || (game.subwayState && game.subwayState.isActive)) return false;

    const enemy = game.currentEnemy;
    const enemyPayload = {
        name: enemy.name,
        rarity: enemy.rarity,
        isShiny: enemy.isShiny,
        isRoaming: enemy.isRoaming,
    };

    const settings = game.normalizeAutoCatcherSettings
        ? game.normalizeAutoCatcherSettings()
        : (game.autoCatcherSettings || {
            enabled: true,
            catchShiny: true,
            catchRoamer: true,
            catchLegendary: true,
            minCatchChancePct: 75,
            useMasterballActiveTargets: false,
            useMasterballShiny: true,
            useMasterballRoamer: true,
            useMasterballLegendary: false,
        });

    const autoTargetsEnabled = settings.enabled !== false;

    if (typeof game._syncCaptureTargetsToCurrentZone === 'function') {
        game._syncCaptureTargetsToCurrentZone();
    }
    const targets: string[] = [];
    if (Array.isArray(game.captureTargets)) targets.push(...game.captureTargets);
    if (game.captureTarget && !targets.includes(game.captureTarget)) targets.push(game.captureTarget);
    const shouldCatchTarget = autoTargetsEnabled && game.captureMode === 2 && targets.includes(enemy.name);
    const shouldCatchSpecial = isAutoCatchSpecialEligible(game, enemyPayload, settings);
    if (!shouldCatchTarget && !shouldCatchSpecial) return false;

    const captureContext = shouldCatchSpecial
        ? resolveAutoCatchCaptureContext(game, enemyPayload, settings)
        : 'active';

    const ballToUse = pickAutoCatchBall(game, enemyPayload, settings, captureContext);

    if (!ballToUse || (game.items[ballToUse] || 0) <= 0) return false;

    game.combatState = 'capture';
    game.isAttacking = false;
    game.tryCapture(ballToUse, false, true);
    return true;
}
