/**
 * @file src/lib/combatTypeStatusProc.ts
 * Proc de statut type/rareté et Orbe Flamme — une chance par coup touché.
 */

import type { GameRuntime, GameStats } from '../types/game.js';
import type { ICreature } from '../types/creature.js';
import {
    STATUS_EFFECTS,
    STATUS_PROC_CHANCES,
    TYPE_TO_STATUS,
} from '../../constants/balance/talentsAndCombat.ts';
import { HELD_ITEMS } from '../../constants/balance/towerAndItems.ts';

const BUFF_STATUS_KEYS = ['reinforced', 'agile', 'thorny', 'enraged', 'puncher'];

function combatLang(game: GameRuntime | null | undefined): 'fr' | 'en' {
    if (game && typeof game.getLanguage === 'function') {
        const lang = game.getLanguage();
        if (lang === 'en') return 'en';
    }
    return 'fr';
}

function formatStatusLog(
    game: GameRuntime,
    creatureName: string,
    statusName: string,
    suffix = '',
): string {
    const fr = `${creatureName} est maintenant ${statusName} !${suffix}`;
    const en = `${creatureName} is now ${statusName}!${suffix}`;
    return combatLang(game) === 'en' ? en : fr;
}

export interface CombatTypeStatusProcOptions {
    playerMainStats?: Record<string, number> | null;
    sourceAttack?: number;
    log?: (msg: string) => void;
    random?: () => number;
}

function recordPlayerStatusInflicted(game: GameRuntime): void {
    if (!game.stats || typeof game.stats !== 'object') game.stats = {} as GameStats;
    game.stats.statusInflicted = (game.stats.statusInflicted || 0) + 1;
    if (typeof game.checkAchievements === 'function') game.checkAchievements('statusInflicted');
    if (typeof game.checkSpecialQuests === 'function') game.checkSpecialQuests('statusInflicted');
}

export function rollCombatTypeStatusProcOnHit(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    opts: CombatTypeStatusProcOptions = {},
): void {
    const { playerMainStats = null, sourceAttack = 0, log, random = Math.random } = opts;
    const baseAtk = (!attacker.isEnemy && playerMainStats)
        ? playerMainStats.attack
        : sourceAttack;

    if (!target.hasStatusEffect()) {
        const procChance = (STATUS_PROC_CHANCES[attacker.rarity] || 0)
            + (typeof game.getStatusProcBonus === 'function' ? game.getStatusProcBonus() : 0);
        if (random() < procChance) {
            const statusType = (TYPE_TO_STATUS as Record<string, string>)[attacker.type];
            if (statusType) {
                const isBuff = BUFF_STATUS_KEYS.includes(statusType);
                const effectTarget = isBuff ? attacker : target;
                effectTarget.applyStatusEffect(statusType, baseAtk, attacker);
                if (log) {
                    log(formatStatusLog(
                        game,
                        effectTarget.name,
                        effectTarget.getStatusEffectName(),
                    ));
                }
                if (!attacker.isEnemy) recordPlayerStatusInflicted(game);
            }
        }
    }

    if (!target.hasStatusEffect() && attacker.heldItem === 'flame_orb') {
        const flatChance = (HELD_ITEMS['flame_orb']?.effect?.burn_chance_flat) || 0.15;
        if (random() < flatChance) {
            target.applyStatusEffect(STATUS_EFFECTS.BURNED, baseAtk, attacker);
            if (log) {
                const suffix = combatLang(game) === 'en' ? ' [Flame Orb]' : ' [Orbe Flamme]';
                log(formatStatusLog(
                    game,
                    target.name,
                    target.getStatusEffectName(),
                    suffix,
                ));
            }
            if (!attacker.isEnemy) recordPlayerStatusInflicted(game);
        }
    }
}

/** Variante simulation offline (sans log UI). */
export function rollSimTypeStatusProcOnHit(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    sourceAttack: number,
    random: () => number = Math.random,
): void {
    if (!target.hasStatusEffect?.()) {
        const procChance = (STATUS_PROC_CHANCES?.[attacker.rarity] || 0)
            + (typeof game.getStatusProcBonus === 'function' ? game.getStatusProcBonus() : 0);
        if (random() < procChance) {
            const stType = (TYPE_TO_STATUS as Record<string, string>)[attacker.type];
            if (stType) {
                const isBuff = BUFF_STATUS_KEYS.includes(stType);
                const tgt = isBuff ? attacker : target;
                tgt.applyStatusEffect?.(stType, sourceAttack, attacker);
            }
        }
    }

    if (!target.hasStatusEffect?.() && attacker.heldItem === 'flame_orb') {
        const flatChance = (HELD_ITEMS['flame_orb']?.effect?.burn_chance_flat as number) || 0.15;
        if (random() < flatChance) {
            target.applyStatusEffect?.(STATUS_EFFECTS.BURNED, sourceAttack, attacker);
        }
    }
}
