/**
 * Passive talent helpers shared between live combat bridges and offline simulateCombat.
 * See gameCombatSystem.ts header comment OFFLINE_TALENT_PARITY for the full matrix.
 */

import type { GameRuntime } from '../types/game.ts';
import type { CreatureData, ICreature } from '../types/creature.ts';
import { STATUS_EFFECTS } from '../../constants/balance/talentsAndCombat.ts';
import { computePhoenixProcChance } from './eluTalentBoost.ts';
import { clearRetaliationState } from './retaliationMove.ts';
import { clearRampageState } from './rampageMove.ts';

/** Clears Sentinelle stacks for the whole team (zone combat end, arena start/end). */
export function resetSentinelleStacksForTeam(team: (CreatureData | null | undefined)[] | undefined): void {
    if (!Array.isArray(team)) return;
    for (const c of team) {
        if (c) c.sentinelleStacks = 0;
    }
}

/** Resets per-combat talent state (mirrors startCombat team reset). */
export function resetSimCombatTalentState(team: (CreatureData | null | undefined)[] | undefined): void {
    if (!Array.isArray(team)) return;
    resetSentinelleStacksForTeam(team);
    for (const c of team) {
        if (!c) continue;
        // sentinelleStacks cleared above
        c.berserkStacks = 0;
        c._acharnementStacks = 0;
        c._acharnementLastTarget = null;
        c._secondSouffleUsed = false;
        if (c.passiveTalent === 'abri') c._abriReady = true;
        clearRetaliationState(c);
        clearRampageState(c as ICreature);
    }
}

/** Abri: blocks first damaging hit once per combat. Returns true if fully blocked. */
export function trySimAbriBlock(creature: CreatureData, damage: number): boolean {
    if (creature.passiveTalent !== 'abri' || creature._abriReady === false || damage <= 0) return false;
    creature._abriReady = false;
    return true;
}

/** Second Souffle after damage: heal 40% max HP once when below 50%. */
export function applySimSecondSouffle(
    game: GameRuntime,
    creature: CreatureData,
    getCurrentHp: () => number,
    getMaxHp: () => number,
    applyHeal: (amount: number) => void,
): void {
    if (creature.passiveTalent !== 'second_souffle' || creature._secondSouffleUsed) return;
    const maxHp = getMaxHp();
    const cur = getCurrentHp();
    if (cur <= 0 || maxHp <= 0 || cur / maxHp >= 0.5) return;
    creature._secondSouffleUsed = true;
    let healRatio = 0.40;
    if (typeof game.getEluFactorFor === 'function') {
        healRatio *= game.getEluFactorFor(creature);
    }
    applyHeal(Math.floor(maxHp * healRatio));
}

/** Vampire: heal 20% of damage dealt (ELU amplified). */
export function computeSimVampireHeal(game: GameRuntime, attacker: CreatureData, damageDealt: number): number {
    if (attacker.passiveTalent !== 'vampire' || damageDealt <= 0) return 0;
    let heal = Math.floor(damageDealt * 0.20);
    if (heal > 0 && typeof game.getEluFactorFor === 'function') {
        heal = Math.floor(heal * game.getEluFactorFor(attacker));
    }
    return heal;
}

/** Reflexion on defender when hit by physical damage. Returns reflect damage to apply to attacker. */
export function computeSimReflexionDamage(
    game: GameRuntime,
    defender: CreatureData,
    attacker: CreatureData | null | undefined,
    damage: number,
    category: string | undefined,
): number {
    if (!attacker || damage <= 0) return 0;
    if (defender.passiveTalent !== 'reflexion' || category !== 'physical') return 0;
    if (attacker.passiveTalent === 'sans_repos') return 0;
    let reflectRatio = 0.12;
    if (defender.hasStatusEffect?.() && defender.statusEffect?.type === STATUS_EFFECTS.THORNY) {
        reflectRatio *= 1.5;
    }
    if (typeof game.getEluFactorFor === 'function') {
        reflectRatio *= game.getEluFactorFor(defender);
    }
    return Math.max(1, Math.floor(damage * reflectRatio));
}

/** Acharnement: increment consecutive-hit stacks on attacker. */
export function incrementSimAcharnement(attacker: CreatureData, target: CreatureData): void {
    if (attacker.passiveTalent !== 'acharnement') return;
    const targetId = target.isEnemy
        ? ('enemy_' + (target.name || 'unknown'))
        : ('player_' + (target.name || 'unknown'));
    if (attacker._acharnementLastTarget === targetId) {
        attacker._acharnementStacks = Math.min(3, (attacker._acharnementStacks || 0) + 1);
    } else {
        attacker._acharnementStacks = 1;
        attacker._acharnementLastTarget = targetId;
    }
}

/** Phoenix: 25% chance to avoid KO and heal. Returns true if revived. */
export function trySimPhoenixRevive(
    game: GameRuntime,
    creature: CreatureData,
    isTrainerBattle: boolean,
): boolean {
    const procChance = typeof game.getEluFactorFor === 'function'
        ? computePhoenixProcChance(game.getEluFactorFor(creature))
        : 0.25;
    if (creature.passiveTalent !== 'phoenix' || Math.random() >= procChance) return false;
    let healRatio = 0.5;
    if (typeof game.getEluFactorFor === 'function') {
        healRatio = Math.min(0.85, healRatio * game.getEluFactorFor(creature));
    }
    if (isTrainerBattle || creature.isEnemy) {
        creature.currentHp = Math.floor((creature.maxHp || 100) * healRatio);
    } else {
        const max = game.getPlayerMaxHp ? game.getPlayerMaxHp() : (creature.maxHp || 100);
        creature.mainAccountCurrentHp = Math.floor(max * healRatio);
    }
    return true;
}

/** Sentinelle: allies gain +1 stack when another team member faints. */
export function applySimSentinelleOnAllyFaint(
    team: (CreatureData | null | undefined)[] | undefined,
    faintedIndex: number,
    game?: GameRuntime | null,
): void {
    if (!Array.isArray(team)) return;
    let stacksChanged = false;
    team.forEach((c, idx) => {
        if (!c || c.passiveTalent !== 'sentinelle') return;
        if (idx === faintedIndex) return;
        const prev = c.sentinelleStacks || 0;
        c.sentinelleStacks = Math.min(5, prev + 1);
        if (c.sentinelleStacks !== prev) stacksChanged = true;
    });
    if (stacksChanged && game && typeof game.invalidateStatsCache === 'function') {
        game.invalidateStatsCache();
    }
}

/** Regeneration talent heal per second (3% max HP per sec, ELU). */
export function computeRegenerationTalentHeal(
    game: GameRuntime,
    creature: CreatureData,
    maxHp: number,
    deltaSeconds: number,
): number {
    if (creature.passiveTalent !== 'regeneration' || maxHp <= 0 || deltaSeconds <= 0) return 0;
    let regenRatio = 0.03 * deltaSeconds;
    if (typeof game.getEluFactorFor === 'function') {
        regenRatio *= game.getEluFactorFor(creature);
    }
    const heal = Math.floor(maxHp * regenRatio);
    if (deltaSeconds >= 1) return Math.max(1, heal);
    return heal;
}
