/**
 * @file src/lib/moveCombatModifiers.ts
 * Modificateurs de puissance / critique liés au move (Hex, Slash, etc.).
 */

import type { ICreature } from '../types/creature.ts';
import { isVariableHpPowerMove, resolveVariableMovePower } from './variablePowerByHp.ts';
import { getAttackerHpRatio } from './combatHpRatio.ts';
import type { GameRuntime } from '../types/game.js';

export function hasDoublePowerOnTargetStatus(moveDef: Record<string, unknown> | null | undefined): boolean {
    return !!(moveDef && moveDef.doublePowerOnTargetStatus === true);
}

export function resolveEffectiveMovePower(
    moveDef: Record<string, unknown> | null | undefined,
    ctx: {
        target?: ICreature | null;
        attacker?: ICreature | null;
        game?: GameRuntime | null;
        hpRatio?: number;
    } = {},
): number {
    if (!moveDef) return 0;
    const { target, attacker, game, hpRatio } = ctx;

    let power = typeof moveDef.power === 'number' ? moveDef.power : 0;
    if (isVariableHpPowerMove(moveDef)) {
        const ratio = typeof hpRatio === 'number'
            ? hpRatio
            : (attacker && game ? getAttackerHpRatio(game, attacker) : 1);
        power = resolveVariableMovePower(moveDef, ratio);
    }

    if (power > 0 && hasDoublePowerOnTargetStatus(moveDef)
        && target?.hasStatusEffect?.()) {
        power *= 2;
    }

    return power;
}

/** Bonus absolu au taux de critique (ex. +0.075 pour taux « élevé »). */
export function getMoveCritRateBonus(moveDef: Record<string, unknown> | null | undefined): number {
    if (!moveDef) return 0;
    const bonus = Number(moveDef.critRateBonus);
    return Number.isFinite(bonus) && bonus > 0 ? bonus : 0;
}

export function isPartialTrapMove(moveDef: Record<string, unknown> | null | undefined): boolean {
    return !!(moveDef && moveDef.partialTrap === true);
}

export function moveClearsPartialTrap(moveDef: Record<string, unknown> | null | undefined): boolean {
    return !!(moveDef && moveDef.clearsPartialTrap === true);
}
