/**
 * @file src/lib/towerBatchRuns.ts
 * Ascension en chaîne — helpers pour runs consécutives de Tour.
 */

import type { GameRuntime } from '../types/game.js';
import {
  getCombatEntryTicketCost,
  tryConsumeCombatEntryTicket,
} from './combatEntryTickets.ts';

export interface TowerBatchRunSummary {
  floorsCleared: number;
  marksGained: number;
  teamXpGained: number;
  pensionXpGained: number;
  runDurationMs: number;
  items: Record<string, number>;
  eggs: Record<string, number>;
  bestAbsoluteFloor: number;
  isForfeit?: boolean;
}

export interface TowerBatchAggregate {
  marksGained: number;
  floorsCleared: number;
  teamXpGained: number;
  pensionXpGained: number;
  items: Record<string, number>;
  eggs: Record<string, number>;
  bestAbsoluteFloor: number;
  newRecord: boolean;
}

export interface TowerBatchQueue {
  runsTotal: number;
  runsCompleted: number;
  /** Figé au lancement : 1ère run gratuite si quête Vertige active. */
  firstRunFree: boolean;
  startedAt: number;
  aggregate: TowerBatchAggregate;
  perRun: TowerBatchRunSummary[];
}

const MAX_BATCH_UPGRADE_LEVEL = 9;

export function getTowerMaxBatchRuns(game: GameRuntime): number {
  const level = Math.max(
    0,
    Math.floor(Number(game.permanentBoosts?.tower_batch_runs) || 0),
  );
  return 1 + Math.min(MAX_BATCH_UPGRADE_LEVEL, level);
}

export function clampTowerBatchSize(game: GameRuntime, size?: number): number {
  const max = getTowerMaxBatchRuns(game);
  const raw = Math.floor(Number(size ?? game.towerBatchSize) || 1);
  return Math.min(max, Math.max(1, raw));
}

export function isTowerClimbQuestActive(game: GameRuntime): boolean {
  return !!(
    game.quests &&
    game.quests.some((q) => q.id === 'story_tower_climb' && q.accepted && !q.completed)
  );
}

/** Tickets requis pour lancer un batch (gate d'entrée ; 1ère run gratuite si quête Vertige). */
export function getTowerBatchTicketsRequired(game: GameRuntime, batchSize: number): number {
  const size = Math.max(1, Math.floor(batchSize) || 1);
  if (isTowerClimbQuestActive(game)) {
    return Math.max(0, size - 1);
  }
  return size;
}

/** Coût en tickets pour une run donnée dans un batch (1-based). */
export function getTowerRunTicketCost(firstRunFree: boolean, runNumber: number): number {
  const run = Math.max(1, Math.floor(runNumber) || 1);
  if (run === 1 && firstRunFree) return 0;
  return getCombatEntryTicketCost();
}

/** Consomme le ticket de la run indiquée ; retourne false si insuffisant. */
export function tryConsumeTowerRunTicket(
  game: GameRuntime,
  runNumber: number,
  firstRunFree: boolean,
): boolean {
  const cost = getTowerRunTicketCost(firstRunFree, runNumber);
  return tryConsumeCombatEntryTicket(game, cost);
}

export function createEmptyTowerBatchAggregate(): TowerBatchAggregate {
  return {
    marksGained: 0,
    floorsCleared: 0,
    teamXpGained: 0,
    pensionXpGained: 0,
    items: {},
    eggs: {},
    bestAbsoluteFloor: 0,
    newRecord: false,
  };
}

function mergeCountMaps(
  target: Record<string, number>,
  source: Record<string, number> | undefined,
): void {
  if (!source) return;
  for (const key of Object.keys(source)) {
    const amount = Math.floor(Number(source[key]) || 0);
    if (amount <= 0) continue;
    target[key] = (target[key] || 0) + amount;
  }
}

export function mergeRunIntoTowerBatchAggregate(
  aggregate: TowerBatchAggregate,
  run: TowerBatchRunSummary,
  isNewRecord: boolean,
): void {
  aggregate.marksGained += Math.max(0, Math.floor(run.marksGained) || 0);
  aggregate.floorsCleared += Math.max(0, Math.floor(run.floorsCleared) || 0);
  aggregate.teamXpGained += Math.max(0, Math.floor(run.teamXpGained) || 0);
  aggregate.pensionXpGained += Math.max(0, Math.floor(run.pensionXpGained) || 0);
  aggregate.bestAbsoluteFloor = Math.max(
    aggregate.bestAbsoluteFloor,
    Math.max(0, Math.floor(run.bestAbsoluteFloor) || 0),
  );
  if (isNewRecord) aggregate.newRecord = true;
  mergeCountMaps(aggregate.items, run.items);
  mergeCountMaps(aggregate.eggs, run.eggs);
}

export function buildTowerBatchRunSummary(
  runStats: NonNullable<GameRuntime['towerState']['runStats']> | undefined,
  absoluteFloorsCleared: number,
  isForfeit: boolean,
): TowerBatchRunSummary {
  const stats = runStats || {};
  return {
    floorsCleared: Math.max(0, Math.floor(Number(stats.floorsCleared) || 0)),
    marksGained: Math.max(0, Math.floor(Number(stats.marksGained) || 0)),
    teamXpGained: Math.max(0, Math.floor(Number(stats.teamXpGained) || 0)),
    pensionXpGained: Math.max(0, Math.floor(Number(stats.pensionXpGained) || 0)),
    runDurationMs: Math.max(1000, Math.floor(Number(stats.runDurationMs) || 0)),
    items: { ...(stats.items || {}) },
    eggs: { ...(stats.eggs || {}) },
    bestAbsoluteFloor: Math.max(0, Math.floor(absoluteFloorsCleared) || 0),
    isForfeit: isForfeit || undefined,
  };
}

export function setTowerBatchSizeLogic(game: GameRuntime, size: number): void {
  const max = getTowerMaxBatchRuns(game);
  game.towerBatchSize = Math.min(max, Math.max(1, Math.floor(size) || 1));
  if (typeof game.saveGame === 'function') game.saveGame();
}
