/**
 * Trainer-mode talents triggered when an opponent Pokémon faints (Phoenix, Dernière Volonté, Sentinelle).
 */

import type { GameRuntime } from '../types/game.ts';
import type { CreatureData, ICreature } from '../types/creature.ts';
import { isTrainerBattle } from './combatHpRatio.ts';
import { combatText } from './combatApi.ts';
import { logMessage } from '../ui/modals.ts';
import {
    applyDerniereVolonteOnFaintLive,
    applyDerniereVolonteOnFaintSim,
} from './derniereVolonteTalent.ts';
import {
    applySimSentinelleOnAllyFaint,
    trySimPhoenixRevive,
} from './simCombatPassiveTalents.ts';
import { computePhoenixProcChance } from './eluTalentBoost.ts';
import {
    isTrainerCombatMode,
    resolveOpponentFaintedIndex,
    resolveOpponentTeamForTrainerCombat,
} from './trainerOpponentTeam.ts';

type FaintCreature = CreatureData | ICreature;

function phoenixHealRatio(game: GameRuntime, creature: FaintCreature): number {
    let ratio = 0.5;
    if (typeof game.getEluFactorFor === 'function') {
        ratio = Math.min(0.85, ratio * game.getEluFactorFor(creature));
    }
    return ratio;
}

function phoenixProcChance(game: GameRuntime, creature: FaintCreature): number {
    return typeof game.getEluFactorFor === 'function'
        ? computePhoenixProcChance(game.getEluFactorFor(creature))
        : 0.25;
}

/** Live: try Phoenix revive on a fainting creature. Returns true if revived. */
export function tryPhoenixReviveLive(game: GameRuntime, creature: FaintCreature | null | undefined): boolean {
    if (!creature || creature.passiveTalent !== 'phoenix') return false;

    const trainerBattle = isTrainerBattle(game) || !!game.towerState?.isActive;
    const hpToCheck = creature.isEnemy
        ? (creature.currentHp ?? 0)
        : (trainerBattle ? (creature.currentHp ?? 0) : (creature.mainAccountCurrentHp ?? 0));
    if (hpToCheck > 0) return false;

    if (Math.random() >= phoenixProcChance(game, creature)) return false;

    const healRatio = phoenixHealRatio(game, creature);
    if (trainerBattle || creature.isEnemy) {
        creature.currentHp = Math.floor((creature.maxHp || 100) * healRatio);
    } else if (typeof game.getPlayerMaxHp === 'function') {
        const restoredHp = Math.floor(game.getPlayerMaxHp() * healRatio);
        creature.mainAccountCurrentHp = restoredHp;
        if (creature.maxHp) creature.currentHp = Math.min(creature.maxHp, restoredHp);
    }

    logMessage(combatText(
        game,
        '',
        'PHOENIX ! {name} renait de ses cendres !',
        'PHOENIX! {name} rises from its ashes!',
        { name: String(creature.name || '') },
    ));
    return true;
}

export function applyOpponentSentinelleOnAllyFaint(
    game: GameRuntime,
    faintedEnemy: FaintCreature | null | undefined,
): void {
    if (!faintedEnemy || !isTrainerCombatMode(game)) return;
    const team = resolveOpponentTeamForTrainerCombat(game);
    if (!team) return;
    const faintedIdx = resolveOpponentFaintedIndex(game, faintedEnemy);
    if (faintedIdx < 0) return;
    applySimSentinelleOnAllyFaint(team, faintedIdx, game);
}

export type EnemyFaintTalentResult = {
    phoenixRevived: boolean;
};

/**
 * Phoenix, Dernière Volonté, and Sentinelle when an opponent faints.
 * Returns phoenixRevived=true if combat should continue (no victory yet).
 */
export function handleOpponentFaintTrainerTalents(
    game: GameRuntime,
    faintedEnemy: FaintCreature | null | undefined,
    opts?: {
        sim?: boolean;
        applyPlayerDamage?: (damage: number) => number;
    },
): EnemyFaintTalentResult {
    if (!faintedEnemy) return { phoenixRevived: false };

    if (opts?.sim) {
        if (trySimPhoenixRevive(game, faintedEnemy as CreatureData, !!isTrainerBattle(game) || !!game.towerState?.isActive)) {
            return { phoenixRevived: true };
        }
    } else if (tryPhoenixReviveLive(game, faintedEnemy)) {
        if (typeof game.updateCombatDisplay === 'function') game.updateCombatDisplay();
        return { phoenixRevived: true };
    }

    const player = game.currentPlayerCreature;
    if (player) {
        if (opts?.sim && opts.applyPlayerDamage) {
            applyDerniereVolonteOnFaintSim(
                game,
                faintedEnemy,
                player,
                opts.applyPlayerDamage,
            );
        } else {
            applyDerniereVolonteOnFaintLive(game, faintedEnemy, player);
        }
    }

    applyOpponentSentinelleOnAllyFaint(game, faintedEnemy);
    return { phoenixRevived: false };
}

/** Re-arm Abri when a trainer Pokémon enters battle. */
export function rearmAbriOnEntry(creature: FaintCreature | null | undefined): void {
    if (creature?.passiveTalent === 'abri') {
        creature._abriReady = true;
    }
}

/** Offline sim: Phoenix / Dernière Volonté / Sentinelle before victory. Returns true if combat continues. */
export function trySimEnemyFaintBeforeVictory(
    game: GameRuntime,
    faintedEnemy: CreatureData,
    applyPlayerDamage: (damage: number) => number,
): boolean {
    return handleOpponentFaintTrainerTalents(game, faintedEnemy, {
        sim: true,
        applyPlayerDamage,
    }).phoenixRevived;
}
