/**
 * @file src/lib/resolveMoveHitCount.ts
 * Nombre de coups pour une attaque (ulti multi-hit ou moves classiques PokeAPI).
 */

import { resolveLoadedDiceHitFloor } from './subwayHeldItems.ts';

export interface ResolveMoveHitCountOptions {
    wasUltimate?: boolean;
    ultimateHits?: number;
    random?: () => number;
    heldItem?: string | null;
}

export function getExpectedMoveHits(
    move: Record<string, unknown> | null | undefined,
    ultimateHits = 0,
): number {
    if (ultimateHits > 1) return ultimateHits;
    const min = Number(move?.minHits);
    const max = Number(move?.maxHits);
    if (Number.isFinite(min) && Number.isFinite(max) && max > 1 && min >= 1) {
        return (min + max) / 2;
    }
    return 1;
}

export function resolveMoveHitCount(
    move: Record<string, unknown> | null | undefined,
    opts: ResolveMoveHitCountOptions = {},
): number {
    const { wasUltimate = false, ultimateHits = 1, random = Math.random } = opts;
    if (wasUltimate) return Math.max(1, ultimateHits || 1);

    const min = Number(move?.minHits);
    const max = Number(move?.maxHits);
    if (Number.isFinite(min) && Number.isFinite(max) && max > 1 && min >= 1) {
        const lo = Math.max(1, min);
        const hi = Math.max(lo, max);
        const floor = opts.heldItem === 'loaded_dice' ? resolveLoadedDiceHitFloor(lo, hi) : lo;
        return floor + Math.floor(random() * (hi - floor + 1));
    }
    return 1;
}
