/**
 * @file subwayDailySet.ts
 * Resolves the active Battle Subway daily trainer roster.
 */

import type { GameRuntime } from '../types/game.js';
import type { SubwaySetProgressEntry } from '../types/game/state.ts';
import {
    SUBWAY_DAILY_SETS,
    SUBWAY_BATTLES_PER_WAGON,
    type SubwayDailySet,
    type SubwayTrainerDef,
    type SubwayTrainerPokemon,
} from '../../constants/balance/subwayTrainers.ts';
import { BALANCE } from '../../constants/balance/balance.ts';

export const SUBWAY_SUNDAY_SET_ID = 'subway_daily_sunday';

const EMPTY_PROGRESS: SubwaySetProgressEntry = { bestStreak: 0, wagonsCleared: 0 };

export interface SubwaySetProgressRow {
    setId: string;
    dayIndex: number;
    label: string;
    themeType: string;
    bestStreak: number;
    wagonsCleared: number;
    isToday: boolean;
}

export function getSubwayDailySetIndex(now = Date.now()): number {
    return new Date(now).getDay();
}

export function getSubwayDailySet(now = Date.now()): SubwayDailySet {
    const dayIndex = getSubwayDailySetIndex(now);
    const set = SUBWAY_DAILY_SETS.find((s) => s.dayIndex === dayIndex);
    return set ?? SUBWAY_DAILY_SETS[0]!;
}

export function getSubwayTrainersForDay(now = Date.now()): SubwayTrainerDef[] {
    return getSubwayDailySet(now).trainers;
}

export function getSubwayWagonLevelOffset(wagonIndex: number): number {
    const w = Math.max(1, Math.floor(Number(wagonIndex) || 1));
    return (w - 1) * BALANCE.SUBWAY_DIFFICULTY.levelPerWagon;
}

export function getSubwayWagonStatMult(wagonIndex: number): number {
    const w = Math.max(1, Math.floor(Number(wagonIndex) || 1));
    return 1 + (w - 1) * BALANCE.SUBWAY_DIFFICULTY.statMultPerWagon;
}

/** Active wagon for a daily set (run in progress or next challenge from progress). */
export function getSubwayCurrentWagonIndex(game: GameRuntime, setId?: string): number {
    const resolvedSetId = setId ?? getSubwayDailySet().id;
    if (
        game.subwayState?.isActive
        && (!setId || game.subwayState.dailySetId === resolvedSetId)
    ) {
        return Math.max(1, Number(game.subwayState.wagonIndex) || 1);
    }
    migrateLegacySubwayProgress(game);
    ensureSubwayWeeklyProgress(game);
    return getSubwaySetProgressEntry(game, resolvedSetId).wagonsCleared + 1;
}

export function ensureSubwaySetProgress(game: GameRuntime): Record<string, SubwaySetProgressEntry> {
    if (!game.subwaySetProgress || typeof game.subwaySetProgress !== 'object') {
        game.subwaySetProgress = {};
    }
    return game.subwaySetProgress;
}

export function getSubwaySetProgressEntry(
    game: GameRuntime,
    setId: string,
): SubwaySetProgressEntry {
    const entry = game.subwaySetProgress?.[setId];
    if (!entry) return { ...EMPTY_PROGRESS };
    return {
        bestStreak: Math.max(0, Number(entry.bestStreak) || 0),
        wagonsCleared: Math.max(0, Number(entry.wagonsCleared) || 0),
    };
}

export function recomputeSubwayGlobalAggregates(game: GameRuntime): void {
    const entries = Object.values(ensureSubwaySetProgress(game));
    game.subwayBestStreak = entries.reduce((max, e) => Math.max(max, e.bestStreak), 0);
    game.subwayWagonsCleared = entries.reduce((sum, e) => sum + e.wagonsCleared, 0);
}

/**
 * Resets wagon progress when the ISO week changes. First-time saves adopt the current week
 * without resetting (grandfather existing progress).
 * @returns true when wagonsCleared was reset for the new week
 */
export function ensureSubwayWeeklyProgress(game: GameRuntime): boolean {
    const weekKey = typeof game._currentWeekKey === 'function' ? game._currentWeekKey() : '';
    if (!weekKey) return false;

    const stored = game.subwayWagonWeekKey ?? '';
    if (!stored) {
        game.subwayWagonWeekKey = weekKey;
        return false;
    }
    if (stored === weekKey) return false;

    for (const set of SUBWAY_DAILY_SETS) {
        const entry = getSubwaySetProgressEntry(game, set.id);
        entry.wagonsCleared = 0;
        ensureSubwaySetProgress(game)[set.id] = entry;
    }
    game.subwayWagonWeekKey = weekKey;
    recomputeSubwayGlobalAggregates(game);
    return true;
}

/** Legacy global streak/wagons → Sunday set (pre-daily-rotation saves). */
export function migrateLegacySubwayProgress(game: GameRuntime): void {
    const progress = ensureSubwaySetProgress(game);
    const hasPerSetData = Object.values(progress).some(
        (e) => (e.bestStreak ?? 0) > 0 || (e.wagonsCleared ?? 0) > 0,
    );
    if (hasPerSetData) return;

    const legacyStreak = Math.max(0, Number(game.subwayBestStreak) || 0);
    const legacyWagons = Math.max(0, Number(game.subwayWagonsCleared) || 0);
    if (legacyStreak <= 0 && legacyWagons <= 0) return;

    progress[SUBWAY_SUNDAY_SET_ID] = {
        bestStreak: legacyWagons,
        wagonsCleared: legacyWagons,
    };
}

/**
 * Legacy saves stored per-run win counts (1–7) in bestStreak.
 * PB is now the highest wagon index cleared with a perfect 7/7.
 */
export function migrateSubwayPersonalBestWagonSemantics(game: GameRuntime): void {
    if (game.subwayPbWagonSemanticsV1) return;

    migrateLegacySubwayProgress(game);
    const progress = ensureSubwaySetProgress(game);
    for (const entry of Object.values(progress)) {
        const streak = Math.max(0, Number(entry.bestStreak) || 0);
        const wagons = Math.max(0, Number(entry.wagonsCleared) || 0);
        if (streak <= 0) continue;
        if (streak > SUBWAY_BATTLES_PER_WAGON) continue;

        if (streak < SUBWAY_BATTLES_PER_WAGON) {
            entry.bestStreak = wagons;
        } else {
            entry.bestStreak = wagons > 0 ? Math.max(wagons, 1) : streak;
        }
    }

    game.subwayPbWagonSemanticsV1 = true;
    recomputeSubwayGlobalAggregates(game);
}

function resolveSubwayLang(game: GameRuntime): 'fr' | 'en' {
    if (typeof game.normalizeLanguage === 'function') {
        return game.normalizeLanguage(game.language) === 'en' ? 'en' : 'fr';
    }
    return game.language === 'en' ? 'en' : 'fr';
}

export function getSubwaySetProgressRows(
    game: GameRuntime,
    now = Date.now(),
): SubwaySetProgressRow[] {
    migrateLegacySubwayProgress(game);
    migrateSubwayPersonalBestWagonSemantics(game);
    ensureSubwayWeeklyProgress(game);
    const lang = resolveSubwayLang(game);
    const todayIndex = getSubwayDailySetIndex(now);
    return SUBWAY_DAILY_SETS.map((set) => {
        const entry = getSubwaySetProgressEntry(game, set.id);
        return {
            setId: set.id,
            dayIndex: set.dayIndex,
            label: set.label[lang] ?? set.label.fr,
            themeType: set.themeType,
            bestStreak: entry.bestStreak,
            wagonsCleared: entry.wagonsCleared,
            isToday: set.dayIndex === todayIndex,
        };
    });
}

/** Matches subwaySystem / preview type resolution. */
export function resolveSubwayPokemonPrimaryType(
    entry: SubwayTrainerPokemon,
    trainer: SubwayTrainerDef,
): string {
    return entry.type ?? trainer.type;
}

const MONO_TYPE_MAX_SHARE = 0.8;

/** Fails if any trainer team is single-type or the wagon is effectively monotype. */
export function assertSubwaySetNotMonotype(set: SubwayDailySet): void {
    const wagonTypeCounts = new Map<string, number>();
    let totalSlots = 0;

    for (const trainer of set.trainers) {
        const teamTypes = new Set<string>();
        for (const entry of trainer.team) {
            const primaryType = resolveSubwayPokemonPrimaryType(entry, trainer);
            teamTypes.add(primaryType);
            wagonTypeCounts.set(primaryType, (wagonTypeCounts.get(primaryType) ?? 0) + 1);
            totalSlots += 1;
        }
        if (teamTypes.size < 2) {
            throw new Error(
                `Subway set "${set.id}" trainer "${trainer.id}" has only one primary type in team`,
            );
        }
    }

    if (wagonTypeCounts.size < 3) {
        throw new Error(
            `Subway set "${set.id}" has fewer than 3 distinct primary types across the wagon`,
        );
    }

    for (const [, count] of wagonTypeCounts) {
        if (count / totalSlots > MONO_TYPE_MAX_SHARE) {
            throw new Error(
                `Subway set "${set.id}" has a type occupying more than ${MONO_TYPE_MAX_SHARE * 100}% of slots`,
            );
        }
    }
}
