/**
 * Dernière Volonté passive talent: chip damage to the active enemy when the bearer faints.
 */

import type { GameRuntime } from '../types/game.ts';
import type { CreatureData, ICreature } from '../types/creature.ts';
import {
    DERNIERE_VOLONTE_BEARER_HP_RATIO,
    DERNIERE_VOLONTE_ENEMY_HP_RATIO,
} from '../../constants/balance/talentsAndCombat.ts';
import { scaleTalentRatio } from './eluTalentBoost.ts';
import { isTrainerBattle } from './combatHpRatio.ts';
import { clampPiegeurAppliedDamage, getPiegeurDamageHpBase } from './hazardEntryTalent.ts';
import { formatCombatFloatingNumber } from '../../formatters.ts';
import { logMessage } from '../ui/modals.ts';
import { showFloatingText } from '../ui/floatingText.ts';

export type DerniereVolonteTalentResult = {
    damage: number;
    applied: number;
};

type Combatant = CreatureData | ICreature;

function derniereVolonteLogMessage(
    game: GameRuntime,
    targetName: string,
    damage: number,
): void {
    if (typeof game.t === 'function') {
        logMessage(game.t('log.derniereVolonteDamage', { name: targetName, dmg: damage }));
        return;
    }
    const isEn = game.language === 'en';
    logMessage(
        isEn
            ? `Last Will deals ${damage} damage to ${targetName}!`
            : `Dernière Volonté inflige ${damage} dégâts à ${targetName} !`,
    );
}

export function computeDerniereVolonteDamage(
    game: GameRuntime | null,
    fainted: Combatant,
    target: Combatant,
): number {
    if (fainted.passiveTalent !== 'derniere_volonte') return 0;

    const bearerMax = getPiegeurDamageHpBase(game, fainted);
    const targetMax = Math.max(1, Number(target.maxHp) || 1);
    let bearerRatio = DERNIERE_VOLONTE_BEARER_HP_RATIO;
    let enemyRatio = DERNIERE_VOLONTE_ENEMY_HP_RATIO;
    if (game && typeof game.getEluFactorFor === 'function') {
        const elu = game.getEluFactorFor(fainted);
        bearerRatio = scaleTalentRatio(bearerRatio, elu);
        enemyRatio = scaleTalentRatio(enemyRatio, elu);
    }
    return Math.max(1, Math.floor(bearerMax * bearerRatio) + Math.floor(targetMax * enemyRatio));
}

/** Live combat: chip the active opponent when a Dernière Volonté bearer faints. */
export function applyDerniereVolonteOnFaintLive(
    game: GameRuntime,
    fainted: Combatant | null | undefined,
    target: Combatant | null | undefined,
    opts?: { silent?: boolean },
): DerniereVolonteTalentResult | null {
    if (!fainted || !target || fainted.passiveTalent !== 'derniere_volonte') return null;

    const rawDamage = computeDerniereVolonteDamage(game, fainted, target);
    const appliedDamage = clampPiegeurAppliedDamage(target, rawDamage);
    if (appliedDamage <= 0) {
        return { damage: 0, applied: 0 };
    }

    const attackerStats = target.isEnemy
        ? (typeof game.getEffectiveStats === 'function'
            ? game.getEffectiveStats()
            : game.playerMainStats ?? {})
        : ({} as Record<string, number>);
    const playerMainStats = isTrainerBattle(game)
        ? ({} as Record<string, number>)
        : attackerStats;

    const prevHp = target.isEnemy
        ? (target.currentHp || 0)
        : (isTrainerBattle(game) ? (target.currentHp || 0) : (target.mainAccountCurrentHp ?? target.currentHp ?? 0));
    if (typeof target.takeDamage === 'function') {
        target.takeDamage(appliedDamage, playerMainStats, false, 'special', 0, game);
    }
    const nextHp = target.isEnemy
        ? (target.currentHp || 0)
        : (isTrainerBattle(game) ? (target.currentHp || 0) : (target.mainAccountCurrentHp ?? target.currentHp ?? 0));
    const applied = Math.max(0, prevHp - nextHp);

    if (!opts?.silent && !game.isOfflineSimulating) {
        derniereVolonteLogMessage(game, String(target.name || ''), applied > 0 ? applied : appliedDamage);
        if (applied > 0 && typeof document !== 'undefined') {
            const containerId = target.isEnemy ? 'enemySpriteContainer' : 'playerSpriteContainer';
            const container = document.getElementById(containerId);
            if (container) {
                showFloatingText(
                    `LAST ${formatCombatFloatingNumber(game, applied)}`,
                    container,
                    target.isEnemy ? 'ft-damage-enemy' : 'ft-damage-player',
                );
            }
        }
    }

    return { damage: applied, applied };
}

/** Offline sim: chip via injected damage applier. */
export function applyDerniereVolonteOnFaintSim(
    game: GameRuntime,
    fainted: Combatant | null | undefined,
    target: Combatant | null | undefined,
    applyDamage: (damage: number) => number,
): DerniereVolonteTalentResult | null {
    if (!fainted || !target || fainted.passiveTalent !== 'derniere_volonte') return null;

    const rawDamage = computeDerniereVolonteDamage(game, fainted, target);
    const appliedDamage = clampPiegeurAppliedDamage(target, rawDamage);
    if (appliedDamage <= 0) {
        return { damage: 0, applied: 0 };
    }

    const prevHp = target.isEnemy
        ? (target.currentHp || 0)
        : (isTrainerBattle(game) ? (target.currentHp || 0) : (target.mainAccountCurrentHp ?? target.currentHp ?? 0));
    applyDamage(appliedDamage);
    const nextHp = target.isEnemy
        ? (target.currentHp || 0)
        : (isTrainerBattle(game) ? (target.currentHp || 0) : (target.mainAccountCurrentHp ?? target.currentHp ?? 0));
    const applied = Math.max(0, prevHp - nextHp);

    return { damage: applied, applied };
}
