export function towerFormatText(text: string, vars: Record<string, unknown> = {}): string {
    return coerceStr(text, '').replace(/\{(\w+)\}/g, (_, k: string) => coerceStr(vars[k], ''));
}

export function towerLang(game: GameRuntime): string {
    if (!game || typeof game.normalizeLanguage !== 'function') return 'fr';
    return game.normalizeLanguage(game.language);
}

export function towerText(game: GameRuntime, key: string, fallbackFr: string, fallbackEn: string, vars: Record<string, unknown> = {}): string {
    if (game && typeof game.t === 'function' && key) {
        const translated = game.t(key, vars);
        if (translated && translated !== key) return translated;
    }
    const fallback = towerLang(game) === 'en' ? fallbackEn : fallbackFr;
    return towerFormatText(fallback, vars);
}

export function towerLocalizedShopName(game: GameRuntime, key: string, fallbackName: string): string {
    const fallback = String(fallbackName || key || '');
    if (game && typeof game.getLocalizedShopEntryName === 'function') {
        return game.getLocalizedShopEntryName('towerShop', key, fallback);
    }
    return fallback;
}

export function towerPct(value: unknown): number {
    return Math.round(Number(value || 0) * 100);
}

