export function pickTowerDropItem(): TowerDropEntry | null {
    if (!Array.isArray(TOWER_ITEM_DROP_TABLE) || TOWER_ITEM_DROP_TABLE.length === 0) return null;
    const totalWeight = TOWER_ITEM_DROP_TABLE.reduce((acc, e) => acc + (Number(e.weight) || 0), 0);
    if (totalWeight <= 0) return null;
    let roll = Math.random() * totalWeight;
    for (let i = 0; i < TOWER_ITEM_DROP_TABLE.length; i++) {
        const entry = TOWER_ITEM_DROP_TABLE[i];
        if (!entry) continue;
        roll -= (Number(entry.weight) || 0);
        if (roll <= 0) return entry;
    }
    return arrayAt(TOWER_ITEM_DROP_TABLE, TOWER_ITEM_DROP_TABLE.length - 1) ?? null;
}

export function towerItemIconHtml(itemDef: { name?: string; img?: string; icon?: string;[key: string]: unknown } | null): string {
    if (!itemDef) return `<span class="tower-relic-icon-fallback">?</span>`;
    if (itemDef.img) return `<img src="${itemDef.img}" alt="" class="tower-relic-icon-img">`;
    const rawIcon = typeof itemDef.icon === 'string' ? itemDef.icon.trim() : '';
    if (rawIcon) return `<span class="tower-relic-icon-fallback">${rawIcon}</span>`;
    return `<span class="tower-relic-icon-fallback">?</span>`;
}

export function grantTowerDropItem(game: GameRuntime, itemKey: string, amount: number): void {
    const qty = Math.max(1, Math.floor(Number(amount) || 1));
    if (itemKey === 'talent_reroll') {
        game.talentRerolls = (game.talentRerolls || 0) + qty;
        const def = ALL_ITEMS[itemKey] ?? null;
        const name = typeof game.getLocalizedItemName === 'function'
            ? game.getLocalizedItemName(itemKey, String(def && def.name || undefined), def)
            : (def && def.name) || itemKey;
        logMessage(towerText(
            game,
            '',
            'Butin de Tour : {name} x{qty} (total: {total})',
            'Tower loot: {name} x{qty} (total: {total})',
            { name, qty, total: game.talentRerolls }
        ));
        if (typeof game.syncTalentConsumablesInInventory === 'function') game.syncTalentConsumablesInInventory();
    } else if (itemKey === 'talent_choice') {
        game.talentChoices = (game.talentChoices || 0) + qty;
        const def = ALL_ITEMS[itemKey] ?? null;
        const name = typeof game.getLocalizedItemName === 'function'
            ? game.getLocalizedItemName(itemKey, String(def && def.name || undefined), def)
            : (def && def.name) || itemKey;
        logMessage(towerText(
            game,
            '',
            'Butin de Tour : {name} x{qty} (total: {total})',
            'Tower loot: {name} x{qty} (total: {total})',
            { name, qty, total: game.talentChoices }
        ));
        if (typeof game.syncTalentConsumablesInInventory === 'function') game.syncTalentConsumablesInInventory();
    } else {
        if (typeof game.addItem === 'function') {
            game.addItem(itemKey, qty);
        }
    }
    if (typeof game.updateItemsDisplay === 'function') game.updateItemsDisplay();
}

export function towerItemRarityLabel(game: GameRuntime, rarity: string): string {
    return towerRarityLabel(game, rarity);
}

export function buildTowerItemChoiceEntry(): { isItem: boolean; itemKey: string; itemDef: Record<string, unknown>; amount: number; rarity: string } | null {
    const entry = pickTowerDropItem();
    if (!entry) return null;
    const def = ALL_ITEMS[entry.key] ?? null;
    if (!def) return null;
    return {
        isItem: true,
        itemKey: entry.key,
        itemDef: def,
        amount: Math.max(1, Math.floor(Number(entry.amount) || 1)),
        rarity: (def.rarity as string) || entry.rarity || 'common'
    };
}

export function towerRelicIconHtml(relicKey: string, relicDef: Record<string, unknown> | null): string {
    const rawIcon = relicDef && typeof relicDef.icon === 'string' ? relicDef.icon.trim() : '';
    // Les anciens icones corrompus apparaissent souvent comme "?", "??", "???".
    const isCorruptedTextIcon = !!rawIcon && /^[?\s]+$/.test(rawIcon);
    const spriteUrl = TOWER_RELIC_ICON_URLS[relicKey];

    if (rawIcon && rawIcon.startsWith('<img')) {
        return rawIcon;
    }
    if (spriteUrl) {
        return `<img src="${spriteUrl}" alt="" class="tower-relic-icon-img">`;
    }
    if (rawIcon && !isCorruptedTextIcon) {
        return `<span class="tower-relic-icon-fallback">${rawIcon}</span>`;
    }
    return `<span class="tower-relic-icon-fallback">?</span>`;
}

