export function towerRelicName(game: GameRuntime, relicKey: string, relicDef: Record<string, unknown> | null): string {
    const lang = towerLang(game);
    const map = TOWER_RELIC_I18N[lang] || {};
    const item = map[relicKey] as { name?: string; desc?: (v: TowerRelicDescValue) => string } | undefined;
    if (item && item.name) return item.name;
    return coalesceStr(relicDef?.name, relicKey);
}

export function towerRelicDescription(game: GameRuntime, relicKey: string, relicDef: Record<string, unknown> | null, value: number): string {
    const lang = towerLang(game);
    const map = TOWER_RELIC_I18N[lang] || {};
    const item = map[relicKey];
    if (item && typeof item.desc === 'function') return item.desc(value);
    const getDescription = relicDef?.getDescription;
    if (typeof getDescription === 'function') return (getDescription as (v: number) => string)(value);
    return '';
}

/** Valeur utilisee pour le rappel d'effet dans les listes (priorite legendaire si disponible). */
export function towerRelicSampleValueForHint(relicDef: Record<string, unknown> | null): number | null {
    if (!relicDef || !relicDef.values) return null;
    const values = relicDef.values as Record<string, number>;
    const forcedRarity = relicDef.forcedRarity as string | undefined;
    if (forcedRarity && values[forcedRarity] != null) {
        return Number(values[forcedRarity]);
    }
    const order = [RARITY.LEGENDARY, RARITY.EPIC, RARITY.RARE, RARITY.COMMON];
    for (let i = 0; i < order.length; i++) {
        const r = order[i];
        if (r === undefined) continue;
        if (values[r] != null) return Number(values[r]);
    }
    return null;
}

/** Libelle d'option (nom — effet) + titre complet pour infobulle. */
export function towerRelicPriorityOptionParts(game: GameRuntime, relicKey: string, relicDef: Record<string, unknown> | null): { text: string; title: string } {
    const name = towerRelicName(game, relicKey, relicDef);
    const value = towerRelicSampleValueForHint(relicDef);
    if (value == null) return { text: name, title: name };
    const desc = towerRelicDescription(game, relicKey, relicDef, value);
    const full = `${name} — ${desc}`;
    let text = full;
    const maxLen = 96;
    if (text.length > maxLen) text = `${text.slice(0, maxLen - 1)}…`;
    return { text, title: full };
}

export function towerRarityLabel(game: GameRuntime, rarity: string): string {
    const isEn = towerLang(game) === 'en';
    const key = String(rarity || '').toLowerCase();
    if (key === 'common') return isEn ? 'Common' : 'Commun';
    if (key === 'rare') return 'Rare';
    if (key === 'epic') return isEn ? 'Epic' : 'Epique';
    if (key === 'legendary') return isEn ? 'Legendary' : 'Legendaire';
    return String(rarity || '');
}

/** Piègeur and other on-entry effects when a tower enemy enters combat. */
export function onTowerEnemyEntered(
    game: GameRuntime,
    enemy: CreatureData | ICreature | null | undefined,
): void {
    if (!enemy) return;
    applyHazardEntryTalentOnEnemyEntry(game, enemy as ICreature);
}

export function initTowerRunState(game: GameRuntime, options: { isChainedRun?: boolean } = {}): void {
    healTeamForTowerRun(game);

    const startFloor = resolveTowerStartFloor(game);
    const startFloorBonus = startFloor - 1;
    const relicRerollsPerRun = Math.max(0, Math.floor(Number((game.permanentBoosts && game.permanentBoosts.relic_reroll) || 0)));

    game.towerState = {
        isActive: true,
        currentFloor: startFloor,
        currentEnemyIndex: 0,
        enemyTeam: generateTowerEnemyTeamLogic(game, startFloor),
        buffs: { attack_mult: 1, defense_mult: 1, lifesteal: 0, crit_chance: 0 },
        relicPicksRemaining: 0,
        relicOfferFloor: 0,
        relicRerollsRemaining: relicRerollsPerRun,
        runStats: {
            startMarques: game.triumphMarks || 0,
            startFloor,
            marksGained: 0,
            items: {},
            eggs: {},
            floorsCleared: 0,
            teamXpGained: 0,
            pensionXpGained: 0,
            runStartedAt: Date.now(),
        }
    };
    if (game.stats) {
        game.stats.towerRunsPlayed = (game.stats.towerRunsPlayed || 0) + 1;
    }

    game.currentEnemy = arrayAt(game.towerState.enemyTeam, 0) ?? null;
    onTowerEnemyEntered(game, game.currentEnemy);
    game.combatState = 'starting';
    game.combatStartTime = Date.now();
    resetCombatTurnTally(game);

    const batch = game.towerBatchQueue;
    if (batch && options.isChainedRun) {
        logMessage(towerText(
            game,
            '',
            'Ascension en chaine : run {current}/{total}.',
            'Chain ascent: run {current}/{total}.',
            { current: batch.runsCompleted + 1, total: batch.runsTotal }
        ));
    }

    if (startFloorBonus > 0) {
        logMessage(towerText(
            game,
            '',
            "Memoire d'Ascension active : depart etage {floor} (+{bonus}).",
            'Ascent Memory active: starting on floor {floor} (+{bonus}).',
            { floor: startFloor, bonus: startFloorBonus }
        ));
    }
    logMessage(towerText(
        game,
        '',
        'Etage {floor} : Le dresseur envoie {enemy} !',
        'Floor {floor}: The trainer sends {enemy}!',
        { floor: startFloor, enemy: game.currentEnemy?.name ?? '???' }
    ));
    game.triggerAutoSelect();
    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'shop', 'items', 'combat']);
}

export function startTowerRunLogic(game: GameRuntime): void {
    if (game.championsTowerState?.isActive) {
        logMessage(towerText(
            game,
            '',
            'Terminez d\'abord la Tour des Champions.',
            'Finish the Champions Tower first.',
        ));
        return;
    }
    if (game.subwayState?.isActive) {
        logMessage(towerText(
            game,
            '',
            'Terminez d\'abord le Battle Subway.',
            'Finish the Battle Subway first.'
        ));
        return;
    }
    if (game.towerState.isActive) {
        logMessage(towerText(
            game,
            '',
            'Une tentative est deja en cours !',
            'A run is already in progress!'
        ));
        return;
    }
    const arenaActive = !!(game.arenaState && game.arenaState.active);
    const gymTrainerActive = !!(game.gymTrainerState && game.gymTrainerState.active);
    const trainerCombatInProgress = (game.combatState === 'fighting' || game.combatState === 'starting');
    const trainerBattleLikelyOngoing = trainerCombatInProgress || !!game.currentEnemy;

    if (arenaActive && trainerBattleLikelyOngoing) {
        logMessage(towerText(
            game,
            '',
            "Terminez d'abord votre defi d'Arene avant de lancer la Tour.",
            'Finish your Arena challenge before starting the Tower.'
        ));
        return;
    }
    if (gymTrainerActive && trainerBattleLikelyOngoing) {
        logMessage(towerText(
            game,
            '',
            "Terminez d'abord le combat de dresseur en cours avant de lancer la Tour.",
            'Finish the ongoing trainer battle before starting the Tower.'
        ));
        return;
    }

    if (arenaActive) {
        logMessage(towerText(
            game,
            '',
            "Etat d'Arene residuel detecte, nettoyage avant lancement de la Tour.",
            'Residual Arena state detected, cleaning it before starting the Tower.'
        ));
        if (typeof game.resetArenaState === 'function') {
            game.resetArenaState();
        } else if (game.arenaState) {
            game.arenaState.active = false;
            game.arenaState.arenaId = null;
            game.arenaState.championTeam = [];
            game.arenaState.currentChampionIndex = 0;
        }
    }
    if (gymTrainerActive) {
        logMessage(towerText(
            game,
            '',
            "Etat de dresseur residuel detecte, nettoyage avant lancement de la Tour.",
            'Residual trainer state detected, cleaning it before starting the Tower.'
        ));
        game.gymTrainerState = null;
    }

    const batchSize = clampTowerBatchSize(game);
    const ticketsRequired = getTowerBatchTicketsRequired(game, batchSize);
    const towerQuestActive = isTowerClimbQuestActive(game);
    const firstRunFree = towerQuestActive;

    if (game.combatTickets < ticketsRequired && !(towerQuestActive && batchSize === 1)) {
        logMessage(towerText(
            game,
            '',
            "Vous n'avez pas assez de Tickets de Combat ! ({have}/{need})",
            'Not enough Combat Tickets! ({have}/{need})',
            { have: game.combatTickets, need: ticketsRequired }
        ));
        return;
    }

    if (typeof game.enterGameContext === 'function') {
        game.enterGameContext('tower');
    }

    if (batchSize > 1) {
        game.towerBatchQueue = {
            runsTotal: batchSize,
            runsCompleted: 0,
            firstRunFree,
            startedAt: Date.now(),
            aggregate: createEmptyTowerBatchAggregate(),
            perRun: [],
        };
    } else {
        game.towerBatchQueue = null;
    }

    if (!tryConsumeTowerRunTicket(game, 1, firstRunFree)) {
        game.towerBatchQueue = null;
        if (typeof game.leaveGameContext === 'function') {
            game.leaveGameContext();
        }
        logMessage(towerText(
            game,
            '',
            "Vous n'avez pas assez de Tickets de Combat ! ({have}/{need})",
            'Not enough Combat Tickets! ({have}/{need})',
            { have: game.combatTickets, need: 1 }
        ));
        return;
    }

    if (batchSize > 1) {
        logMessage(towerText(
            game,
            '',
            'Ascension en chaine : {count} runs planifiees — 1 ticket par run.',
            'Chain ascent: {count} runs planned — 1 ticket per run.',
            { count: batchSize }
        ));
    } else if (!towerQuestActive) {
        logMessage(towerText(
            game,
            '',
            "Un Ticket de Combat est utilise. L'ascension de la Tour commence !",
            'A Combat Ticket was used. The Tower climb begins!'
        ));
    } else {
        logMessage(towerText(
            game,
            '',
            "Tour gratuite (quete Le Vertige en cours). L'ascension commence !",
            'Free Tower run (Vertigo quest active). The climb begins!'
        ));
    }

    initTowerRunState(game);
}
export function generateTowerEnemyTeamLogic(game: GameRuntime, floor: number): Array<CreatureData & Record<string, unknown>> {
    const team = [];
    const te = BALANCE.TOWER_ENEMY;
    const maxDexId = te.DEX_ROTATION_MAX_ID;
    const targetId = ((floor - 1) % maxDexId) + 1;
    const pokemonName = Object.keys(POKEMON_SPRITE_IDS).find(key => POKEMON_SPRITE_IDS[key] === targetId) || "MissingNo";
    const isBossFloor = floor % te.BOSS_FLOOR_INTERVAL === 0;
    const type = game.findTypeForPokemon(pokemonName);
    const secondaryType = POKEMON_SECONDARY_TYPES[pokemonName] || null;
    let rarity: string = RARITY.COMMON;
    if (isBossFloor) rarity = RARITY.LEGENDARY;

    const creature = new Creature(pokemonName, type, floor, rarity, true, false, secondaryType, isBossFloor, false);

    const bal = BALANCE;
    const baseMult = bal.TOWER_ENEMY_BASE_MULT;
    const linearGrowth = 1 + (floor * bal.TOWER_ENEMY_LINEAR_PER_FLOOR);
    const expoGrowth = Math.pow(bal.TOWER_ENEMY_EXP_BASE, floor);
    let multiplier = baseMult * linearGrowth * expoGrowth;
    if (isBossFloor) {
        multiplier *= bal.TOWER_BOSS_FLOOR_MULT;
        (creature).assignRandomTalent?.();
    }

    creature.maxHp = Math.floor(creature.maxHp * multiplier);
    creature.attack = Math.floor(creature.attack * multiplier);
    creature.spattack = Math.floor(creature.spattack * multiplier);
    creature.defense = Math.floor(creature.defense * multiplier);
    creature.spdefense = Math.floor(creature.spdefense * multiplier);
    creature.speed = Math.floor(creature.speed * multiplier);
    creature.currentHp = creature.maxHp;
    team.push(creature);
    return team;
}

export function nextTowerFloorLogic(game: GameRuntime): void {
    if (game.towerState.currentFloor % BALANCE.TOWER_ENEMY.BOSS_FLOOR_INTERVAL === 0) {
        game.combatState = 'waiting';
        game.currentEnemy = null;
        offerTowerRelicLogic(game);
        return;
    }
    proceedToNextFloorLogic(game);
}

export function proceedToNextFloorLogic(game: GameRuntime): void {
    game.towerState.currentFloor++;
    if (typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('towerFloor');
    }
    logMessage(towerText(
        game,
        '',
        "Passage a l'etage {floor}.",
        'Moving to floor {floor}.',
        { floor: game.towerState.currentFloor }
    ));
    game.towerState.enemyTeam = generateTowerEnemyTeamLogic(game, game.towerState.currentFloor);
    game.towerState.currentEnemyIndex = 0;
    game.currentEnemy = arrayAt(game.towerState.enemyTeam, 0) ?? null;
    onTowerEnemyEntered(game, game.currentEnemy);
    game.combatState = 'starting';
    game.combatStartTime = Date.now();
    resetCombatTurnTally(game);
    game.triggerAutoSelect();
    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'shop', 'items']);
}
function finalizeTowerRunAfterCombat(game: GameRuntime): void {
    if (typeof game.leaveGameContext === 'function') {
        game.leaveGameContext();
    }

    game.towerState = { isActive: false, currentFloor: 0, currentEnemyIndex: 0, enemyTeam: [], buffs: {} };
    game.combatState = 'waiting';
    game.lastCombatTime = Date.now();
    game.currentEnemy = null;

    game.playerTeam.forEach((c: CreatureWithHeal) => {
        if (typeof c.heal === 'function') c.heal();
    });
    restoreZoneHpPoolOnTeam(game);

    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'shop', 'items']);
    game.saveGame();
}

export function endTowerRunLogic(game: GameRuntime, isForfeit: boolean = false): void {
    const floorReached = game.towerState.currentFloor;
    const absoluteFloorsCleared = floorReached - 1;
    const startFloor = (game.towerState && game.towerState.runStats && game.towerState.runStats.startFloor) || 1;
    const floorsCleared = Math.max(0, absoluteFloorsCleared - (startFloor - 1));
    const isNewRecord = absoluteFloorsCleared > game.towerRecord;
    if (isNewRecord) {
        game.towerRecord = absoluteFloorsCleared;
        const towerReward = absoluteFloorsCleared * 100;
        if (towerReward > 0 && typeof game.addCombatPokedollars === 'function') {
            game.addCombatPokedollars(towerReward, 'silent');
        } else if (towerReward > 0) {
            game.pokedollars += towerReward;
        }
    }
    if (!game.stats) game.stats = {} as GameStats;
    game.stats.towerFloorsClimbed = (game.stats.towerFloorsClimbed || 0) + Math.max(0, floorsCleared);
    if (isForfeit) {
        game.stats.towerRunsForfeited = (game.stats.towerRunsForfeited || 0) + 1;
    }
    if (typeof game.checkAchievements === 'function') game.checkAchievements('towerFloorsClimbed');
    if (game.checkSpecialQuests) game.checkSpecialQuests('towerFloor');

    if (game.towerState.runStats) {
        game.towerState.runStats.floorsCleared = floorsCleared;
        finalizeTowerRunDuration(game.towerState.runStats);
    }

    const batch = game.towerBatchQueue;
    if (batch) {
        const runSummary = buildTowerBatchRunSummary(
            game.towerState.runStats,
            absoluteFloorsCleared,
            isForfeit,
        );
        batch.perRun.push(runSummary);
        mergeRunIntoTowerBatchAggregate(batch.aggregate, runSummary, isNewRecord);
        batch.runsCompleted += 1;

        const batchFinished = isForfeit || batch.runsCompleted >= batch.runsTotal;
        if (!batchFinished) {
            const nextRun = batch.runsCompleted + 1;
            if (!tryConsumeTowerRunTicket(game, nextRun, batch.firstRunFree)) {
                logMessage(towerText(
                    game,
                    '',
                    'Tickets insuffisants : le batch est interrompu apres {completed}/{total} run(s).',
                    'Not enough tickets: batch stopped after {completed}/{total} run(s).',
                    { completed: batch.runsCompleted, total: batch.runsTotal },
                ));
                showTowerBatchCompletionModalLogic(game, batch, false);
                game.towerBatchQueue = null;
                finalizeTowerRunAfterCombat(game);
                return;
            }
            initTowerRunState(game, { isChainedRun: true });
            return;
        }

        showTowerBatchCompletionModalLogic(game, batch, isForfeit);
        game.towerBatchQueue = null;
        finalizeTowerRunAfterCombat(game);
        return;
    }

    showTowerCompletionModalLogic(game, floorsCleared, isNewRecord, isForfeit);
    finalizeTowerRunAfterCombat(game);
}

export function isTowerRelicCappedLogic(game: GameRuntime, key: string, relic: Record<string, unknown>): boolean {
    const buffs = (game && game.towerState && game.towerState.buffs) ? game.towerState.buffs : {};

    // Reliques "uniques" : deja obtenues une fois dans le run.
    if (relic && relic.unique) {
        if (key === 'executioner' && Number(buffs.execute_percent || 0) > 0) return true;
        if (key === 'shadow_cloak' && Number(buffs.dodge_chance || 0) > 0) return true;
        if (key === 'first_blood' && Number(buffs.first_blood_bonus || 0) > 0) return true;
    }

    // Reliques a cap global.
    if (key === 'spike_armor' && Number(buffs.reflect_percent || 0) >= 0.25) return true;
    if (key === 'armor_breaker' && Number(buffs.armor_break_pct || 0) >= 0.75) return true;
    if (key === 'ultimate_overclock' && Number(buffs.ult_charge_bonus || 0) >= 0.10) return true;
    if (key === 'triumph_prime' && Number(buffs.triumph_marks_flat || 0) >= 3) return true;

    return false;
}

export function getTowerRelicPicksPerBoss(game: GameRuntime): number {
    const bonus = Math.max(0, Math.floor(Number((game.permanentBoosts && game.permanentBoosts.boss_relic_pick_bonus) || 0)));
    return Math.min(2, 1 + bonus);
}

export function rollTowerRelicChoices(game: GameRuntime, availableKeys: string[]): TowerRelicChoice[] {
    const rollRarity = () => {
        const r = Math.random() * 100;
        if (r < 60) return RARITY.COMMON;
        if (r < 90) return RARITY.RARE;
        if (r < 98) return RARITY.EPIC;
        return RARITY.LEGENDARY;
    };

    const choices: Array<{ key: string; rarity: string }> = [];
    const countToPick = Math.min(3, availableKeys.length);
    let safety = 0;
    while (choices.length < countToPick && safety < 200) {
        safety++;
        const rolledRarity = rollRarity();
        const remainingKeys = availableKeys.filter(k => !choices.some(c => c.key === k));
        if (remainingKeys.length === 0) break;

        const compatibleKeys = remainingKeys.filter(k => {
            const relic = TOWER_RELICS[k];
            if (!relic || !relic.values) return false;
            if (relic.forcedRarity) {
                return relic.forcedRarity === rolledRarity && (relic.values)[rolledRarity] != null;
            }
            return (relic.values)[rolledRarity] != null;
        });

        let keyToAdd: string | null = null;
        let rarityToAdd: string = rolledRarity;
        if (compatibleKeys.length > 0) {
            keyToAdd = compatibleKeys[Math.floor(Math.random() * compatibleKeys.length)] ?? null;
        } else {
            keyToAdd = remainingKeys[Math.floor(Math.random() * remainingKeys.length)] ?? null;
        }
        if (!keyToAdd) continue;
        const relic = recordGet(TOWER_RELICS as Record<string, typeof TOWER_RELICS[string]>, keyToAdd);
        if (!compatibleKeys.length) {
            rarityToAdd = relic?.forcedRarity ? String(relic.forcedRarity) : rolledRarity;
            const relicValues = relic?.values as Record<string, number> | undefined;
            if (relicValues && relicValues[rarityToAdd] == null) {
                const availableRarities = Object.keys(relicValues);
                if (availableRarities.length === 0) continue;
                rarityToAdd = availableRarities[0] ?? rolledRarity;
            }
        }

        if (!choices.some(c => c.key === keyToAdd)) {
            choices.push({ key: keyToAdd, rarity: rarityToAdd });
        }
    }
    return choices;
}

export function clearTowerRelicAutoTimers(game: GameRuntime): void {
    if (!game) return;
    if (game._towerRelicAutoT1) clearTimeout(game._towerRelicAutoT1);
    if (game._towerRelicAutoT2) clearTimeout(game._towerRelicAutoT2);
    game._towerRelicAutoT1 = null;
    game._towerRelicAutoT2 = null;
}

export function towerRelicRarityRank(rarity: string): number {
    const key = String(rarity || '').toLowerCase();
    if (key === RARITY.LEGENDARY) return 4;
    if (key === RARITY.EPIC) return 3;
    if (key === RARITY.RARE) return 2;
    if (key === RARITY.COMMON) return 1;
    return 0;
}

export function towerRelicChoiceMatchesPriorityWant(c: TowerRelicChoice, want: { key: string | null; minRarity: string }): boolean {
    if (!want || !c || isTowerRelicItemChoice(c)) return false;
    if (want.key === TOWER_RELIC_PRIORITY_BY_RARITY) return true;
    return !isTowerRelicItemChoice(c) && c.key === want.key;
}

/**
 * Parmi un sous-ensemble d’indices, applique P1?P4 + seuils minRarity ; sinon -1.
 * @param {{ minSlotIndex?: number, maxSlotIndex?: number }} [range] — bornes inclusives de slots (défaut 0..3).
 */
export function pickTowerRelicAutoPriorityAmongIndices(game: GameRuntime, choices: TowerRelicChoice[], indices: number[], slots: Array<{ key: string | null; minRarity: string }>, range?: { start?: number; end?: number; minSlotIndex?: number; maxSlotIndex?: number }): number {
    const r = range || {};
    const pMin = Math.max(0, Math.min(TOWER_RELIC_AUTO_PRIORITY_SLOT_COUNT - 1, r.minSlotIndex != null ? r.minSlotIndex : 0));
    const pMax = Math.max(pMin, Math.min(TOWER_RELIC_AUTO_PRIORITY_SLOT_COUNT - 1, r.maxSlotIndex != null ? r.maxSlotIndex : TOWER_RELIC_AUTO_PRIORITY_SLOT_COUNT - 1));
    for (let p = pMin; p <= pMax; p++) {
        const slot = slots[p];
        if (!slot || !slot.key) continue;
        const want = slot.key;
        const minRank = towerRelicRarityRank(slot.minRarity || RARITY.COMMON);

        let bestIdx = -1;
        let bestRollRank = -1;
        for (let k = 0; k < indices.length; k++) {
            const i = indices[k];
            if (i === undefined) continue;
            const c = choices[i];
            if (!c || !towerRelicChoiceMatchesPriorityWant(c, { key: want, minRarity: slot.minRarity })) continue;
            const rollRank = towerRelicRarityRank(c.rarity || '');
            if (rollRank < minRank) continue;
            if (rollRank > bestRollRank || (rollRank === bestRollRank && bestIdx >= 0 && i < bestIdx)) {
                bestRollRank = rollRank;
                bestIdx = i;
            }
        }
        if (bestIdx >= 0) return bestIdx;
    }
    return -1;
}

/**
 * Sans « Par rareté » en P4 : tranche de rareté max dans le pool, puis P1?P4 sur cette tranche.
 * Avec « Par rareté » en P4 : P1?P3 sur tout le pool (y compris jets moins rares), puis si aucun match,
 * même repli que sans priorités (tranche max + P1?P4 pour départager).
 */
export function pickTowerRelicAutoIndex(game: GameRuntime, choices: TowerRelicChoice[]): number {
    if (!choices || choices.length === 0) return 0;
    callGameVoid(game, game.normalizeTowerRelicAutoSettings);
    const settings = game.towerRelicAutoSettings || {};
    const slots = Array.isArray(settings.prioritySlots) ? settings.prioritySlots : [];
    const blacklist = new Set(settings.blacklist || []);
    const skipItemLoot = !!settings.skipItemLoot;

    const allIdx = choices.map((_, i) => i);
    const relicPool = allIdx.filter((i) => {
        const c = choices[i];
        if (!c || isTowerRelicItemChoice(c)) return false;
        return !blacklist.has(c.key);
    });
    const fullPool = allIdx.filter((i) => {
        const c = choices[i];
        if (!c) return false;
        if (isTowerRelicItemChoice(c)) return true;
        return !blacklist.has(c.key);
    });
    let pool: number[];
    if (skipItemLoot) {
        if (relicPool.length === 0) return -1;
        pool = relicPool;
    } else {
        pool = fullPool.length ? fullPool : allIdx;
    }

    const slot4 = slots[3];
    const p4ByRarity = slot4 && slot4.key === TOWER_RELIC_PRIORITY_BY_RARITY;
    if (p4ByRarity) {
        const early = pickTowerRelicAutoPriorityAmongIndices(
            game,
            choices,
            pool,
            slots,
            { maxSlotIndex: 2 }
        );
        if (early >= 0) return early;
    }

    let maxR = -1;
    for (let j = 0; j < pool.length; j++) {
        const i = pool[j];
        if (i === undefined) continue;
        const choiceAt = choices[i];
        const r = towerRelicRarityRank(choiceAt?.rarity || '');
        if (r > maxR) maxR = r;
    }

    const topTier: number[] = [];
    for (let j = 0; j < pool.length; j++) {
        const i = pool[j];
        if (i === undefined) continue;
        const choiceAt = choices[i];
        if (towerRelicRarityRank(choiceAt?.rarity || '') === maxR) topTier.push(i);
    }

    const poolFirst = pool[0];
    if (topTier.length === 0) return poolFirst ?? 0;
    const topFirst = topTier[0];
    if (topTier.length === 1 && topFirst !== undefined) return topFirst;

    const prioIdx = pickTowerRelicAutoPriorityAmongIndices(game, choices, topTier, slots);
    if (prioIdx >= 0) return prioIdx;

    return Math.min(...topTier);
}

export function updateTowerRelicControlsLogic(game: GameRuntime): void {
    const grid = document.getElementById('relicOptionsGrid');
    if (!grid || !grid.parentElement) return;

    let controlsRow = document.getElementById('relicControlsRow');
    if (!controlsRow) {
        controlsRow = document.createElement('div');
        controlsRow.id = 'relicControlsRow';
        controlsRow.style.marginTop = '14px';
        controlsRow.style.display = 'flex';
        controlsRow.style.justifyContent = 'center';
        controlsRow.style.gap = '10px';
        grid.parentElement.appendChild(controlsRow);
    }
    controlsRow.innerHTML = '';

    const rerollsLeft = Math.max(0, Math.floor(Number((game.towerState && game.towerState.relicRerollsRemaining) || 0)));
    if (rerollsLeft <= 0) {
        controlsRow.remove();
        return;
    }

    const rerollBtn = document.createElement('button');
    rerollBtn.className = 'shop-buy-btn relic-reroll-btn';
    rerollBtn.textContent = towerText(
        game,
        '',
        'Reroll reliques ({count})',
        'Reroll relics ({count})',
        { count: rerollsLeft }
    );
    rerollBtn.addEventListener('click', () => {
        if (!game.towerState || (game.towerState.relicRerollsRemaining || 0) <= 0) return;
        game.towerState.relicRerollsRemaining = (game.towerState.relicRerollsRemaining ?? 0) - 1;
        logMessage(towerText(
            game,
            '',
            'Reroll utilise. Restant: {count}.',
            'Reroll used. Remaining: {count}.',
            { count: game.towerState.relicRerollsRemaining }
        ));
        offerTowerRelicLogic(game);
    });
    controlsRow.appendChild(rerollBtn);
}

export function offerTowerRelicLogic(game: GameRuntime): void {
    const modal = document.getElementById('relicModal');
    if (!modal) return;

    if (!game.towerState) return;
    clearTowerRelicAutoTimers(game);
    game._towerRelicOfferGen = (game._towerRelicOfferGen || 0) + 1;
    const offerGen = game._towerRelicOfferGen;

    const currentFloor = Number(game.towerState.currentFloor) || 0;
    const isNewBossOffer = game.towerState.relicOfferFloor !== currentFloor;
    if (isNewBossOffer) {
        game.towerState.relicOfferFloor = currentFloor;
        game.towerState.relicPicksRemaining = getTowerRelicPicksPerBoss(game);
    }
    if ((game.towerState.relicPicksRemaining || 0) <= 0) {
        game.towerState.relicOfferFloor = 0;
        proceedToNextFloorLogic(game);
        return;
    }

    const bodyLabelText = towerText(
        game,
        '',
        'Choisissez une relique ({remaining} choix restant(s)).',
        'Choose a relic ({remaining} pick(s) remaining).',
        { remaining: game.towerState.relicPicksRemaining }
    );

    const availableKeys = Object.keys(TOWER_RELICS).filter(key => {
        const relic = recordGet(TOWER_RELICS as Record<string, Record<string, unknown>>, key);
        return relic != null && !isTowerRelicCappedLogic(game, key, relic);
    });
    if (availableKeys.length === 0) {
        logMessage(towerText(
            game,
            '',
            'Aucune relique supplementaire disponible (caps atteints).',
            'No additional relic is available (caps reached).'
        ));
        game.towerState.relicPicksRemaining = 0;
        game.towerState.relicOfferFloor = 0;
        closeRelicModal();
        proceedToNextFloorLogic(game);
        return;
    }

    const choices = rollTowerRelicChoices(game, availableKeys);
    if (!choices || choices.length === 0) {
        logMessage(towerText(
            game,
            '',
            'Aucune relique valide tiree, passage a la suite.',
            'No valid relic rolled, moving on.'
        ));
        game.towerState.relicPicksRemaining = 0;
        game.towerState.relicOfferFloor = 0;
        closeRelicModal();
        proceedToNextFloorLogic(game);
        return;
    }

    // Contrebande de la Tour : chaque slot de relique a une chance (permanentBoosts.tower_item_drop_chance)
    // d'etre remplace par un objet aleatoire tire dans TOWER_ITEM_DROP_TABLE.
    const itemDropChance = Math.max(0, Math.min(1,
        Number((game.permanentBoosts && game.permanentBoosts.tower_item_drop_chance) || 0)
    ));
    if (itemDropChance > 0) {
        for (let idx = 0; idx < choices.length; idx++) {
            if (Math.random() < itemDropChance) {
                const itemChoice = buildTowerItemChoiceEntry();
                if (itemChoice) choices[idx] = itemChoice as TowerRelicChoice;
            }
        }
    }

    const autoOn = !!(game.unlockedFeatures && game.unlockedFeatures.towerRelicAuto
        && game.towerRelicAutoSettings && game.towerRelicAutoSettings.enabled);

    let html = '';
    choices.forEach((choice, idx) => {
        if (choice && isTowerRelicItemChoice(choice)) {
            const def = choice.itemDef;
            const rarity = choice.rarity || 'common';
            const rarityLabel = towerItemRarityLabel(game, rarity);
            const baseName = coalesceStr(def?.name, choice.itemKey);
            let name = baseName;
            if (typeof game.getLocalizedItemName === 'function') {
                name = game.getLocalizedItemName(choice.itemKey, baseName, def);
            }
            let descHtml = '';
            if (!autoOn) {
                const baseDesc = coerceStr(def?.description, '');
                let desc = baseDesc;
                const localizeDescKey = 'getLocalizedItemDescription' as const;
                const localizeDesc = game[localizeDescKey];
                if (typeof localizeDesc === 'function') {
                    desc = coerceStr(
                        (localizeDesc as (key: string, fb: string, def?: Record<string, unknown>) => string)(
                            choice.itemKey,
                            baseDesc,
                            def,
                        ),
                        baseDesc,
                    );
                }
                descHtml = `<div style="font-size:11px; color:#ccc; line-height: 1.3;">${desc}</div>`;
            }
            const iconHtml = towerItemIconHtml(def ?? null);
            const badge = towerText(game, '', 'Butin', 'Loot');
            const qtyLabel = choice.amount > 1 ? ` <span style="color:#fbbf24; font-weight:700;">x${choice.amount}</span>` : '';
            html += `<div class="relic-card relic-${rarity} relic-item-card" data-choice-idx="${idx}" data-item-key="${choice.itemKey}" data-item-amount="${choice.amount}" data-item-rarity="${rarity}">
                <div class="relic-badge badge-${rarity}">${badge} (${rarityLabel})</div>
                <div class="tower-relic-icon-wrap">${iconHtml}</div>
                <div style="font-weight:bold; margin:4px 0; color:#fff;">${name}${qtyLabel}</div>
                ${descHtml}
            </div>`;
        } else {
            const relic = recordGet(TOWER_RELICS as Record<string, Record<string, unknown>>, choice.key) ?? null;
            const relicValues = (relic?.values ?? {}) as Record<string, number>;
            const value = relicValues[choice.rarity] ?? 0;
            const rarityLabel = towerRarityLabel(game, choice.rarity);
            const name = towerRelicName(game, choice.key, relic);
            const descHtml = autoOn
                ? ''
                : `<div style="font-size:11px; color:#ccc; line-height: 1.3;">${towerRelicDescription(game, choice.key, relic, value)}</div>`;
            const iconHtml = towerRelicIconHtml(choice.key, relic);
            html += `<div class="relic-card relic-${choice.rarity}" data-choice-idx="${idx}" data-key="${choice.key}" data-relic-rarity="${choice.rarity}">
                <div class="relic-badge badge-${choice.rarity}">${rarityLabel}</div>
                <div class="tower-relic-icon-wrap">${iconHtml}</div>
                <div style="font-weight:bold; margin:4px 0; color:#fff;">${name}</div>
                ${descHtml}
            </div>`;
        }
    });
    let relicChoiceLocked = false;
    const pickRelic = (card: HTMLElement | null) => {
        if (!card || relicChoiceLocked) return;
        clearTowerRelicAutoTimers(game);
        relicChoiceLocked = true;
        if (card.classList.contains('relic-item-card')) {
            const itemKey = card.dataset.itemKey || '';
            const amount = Math.max(1, Math.floor(Number(card.dataset.itemAmount) || 1));
            selectTowerItemChoiceLogic(game, itemKey, amount);
            return;
        }
        const rarity = card.dataset.relicRarity || card.dataset.rarity || '';
        selectTowerRelicLogic(game, card.dataset.key || '', rarity);
    };

    const bindRelicCards = (gridEl: HTMLElement) => {
        gridEl.querySelectorAll('.relic-card').forEach((card) => {
            const c = card as HTMLElement;
            c.setAttribute('role', 'button');
            c.setAttribute('tabindex', '0');
            c.addEventListener('click', () => pickRelic(c));
            c.addEventListener('keydown', (e) => {
                if ((e).key === 'Enter' || (e).key === ' ') {
                    e.preventDefault();
                    pickRelic(c);
                }
            });
        });
    };

    void import('./src/bridge/relicModalBridge.js').then(async (bridge) => {
        await bridge.showRelicModalWhenPainted({
            bodyLabel: autoOn ? '' : bodyLabelText,
            gridHtml: html,
            passive: autoOn,
        });
        const grid = document.getElementById('relicOptionsGrid');
        if (!grid) return;
        bindRelicCards(grid);
        updateTowerRelicControlsLogic(game);
        if (autoOn) {
            callGameVoid(game, game.normalizeTowerRelicAutoSettings);
        }
        if (!autoOn) return;
        const pickIdx = pickTowerRelicAutoIndex(game, choices);
        if (pickIdx < 0) return;
        const cardEl = grid.querySelector<HTMLElement>(`.relic-card[data-choice-idx="${pickIdx}"]`);
        if (!cardEl) return;
        const reduced = !!(game.reducedMotion);
        const delayMs = reduced ? Math.round(TOWER_RELIC_AUTO_PICK_DELAY_MS * 0.5) : TOWER_RELIC_AUTO_PICK_DELAY_MS;
        const hlMs = reduced ? Math.round(TOWER_RELIC_AUTO_HIGHLIGHT_MS * 0.5) : TOWER_RELIC_AUTO_HIGHLIGHT_MS;
        const choice = choices[pickIdx];
        game._towerRelicAutoT1 = setTimeout(() => {
            if (game._towerRelicOfferGen !== offerGen || relicChoiceLocked) return;
            cardEl.classList.add('relic-card-auto-highlight');
            game._towerRelicAutoT2 = setTimeout(() => {
                if (game._towerRelicOfferGen !== offerGen || relicChoiceLocked) {
                    cardEl.classList.remove('relic-card-auto-highlight');
                    return;
                }
                cardEl.classList.remove('relic-card-auto-highlight');
                if (choice && isTowerRelicItemChoice(choice)) {
                    const def = choice.itemDef;
                    const baseName = coalesceStr(def?.name, choice.itemKey);
                    let nm = baseName;
                    if (typeof game.getLocalizedItemName === 'function') {
                        nm = game.getLocalizedItemName(choice.itemKey, baseName, def);
                    }
                    logMessage(towerText(
                        game,
                        '',
                        'Auto : butin {name}',
                        'Auto: loot {name}',
                        { name: nm }
                    ));
                } else if (choice) {
                    const relic = recordGet(TOWER_RELICS as Record<string, Record<string, unknown>>, choice.key) ?? null;
                    if (relic) {
                        logMessage(towerText(
                            game,
                            '',
                            'Auto : {name}',
                            'Auto: {name}',
                            { name: towerRelicName(game, choice.key, relic) }
                        ));
                    }
                }
                pickRelic(cardEl);
            }, hlMs);
        }, delayMs);
    });
}

/**
 * Empreinte du pilote de reliques : évite de refaire panel.innerHTML à chaque updateDisplay(),
 * ce qui démontait le DOM et fermait les listes des <select> (priorités) en plein run Tour.
 * Appeler après normalizeTowerRelicAutoSettings().
 */
export function computeTowerRelicAutoPanelSig(game: GameRuntime): string {
    const lang = towerLang(game);
    const relicCatalog = Object.keys(TOWER_RELICS).sort().join(',');
    if (!game.unlockedFeatures || !game.unlockedFeatures.towerRelicAuto) {
        return `${lang}|locked|${relicCatalog}`;
    }
    const s = game.towerRelicAutoSettings;
    const prio = (s.prioritySlots || []).map((sl) => ({
        key: sl && sl.key != null ? sl.key : null,
        minRarity: sl && sl.minRarity ? sl.minRarity : RARITY.COMMON
    }));
    const bl = [...(s.blacklist || [])].slice().sort();
    return `${lang}|${s.enabled ? '1' : '0'}|${s.skipItemLoot ? '1' : '0'}|${JSON.stringify(prio)}|${JSON.stringify(bl)}|${relicCatalog}`;
}

function notifyTowerPanelChanged(_game: GameRuntime): void {
    publishTowerChanged();
}

export interface TowerRelicAutoPanelBuild {
    visible: boolean;
    html: string;
    sig: string;
}

function towerRelicAutoTooltip(game: GameRuntime, key: string, fallbackFr: string, fallbackEn: string): string {
    const fullKey = `tower.relicAuto.${key}`;
    if (typeof game.t === 'function') {
        const got = game.t(fullKey);
        if (got && got !== fullKey) return got;
    }
    return towerText(game, '', fallbackFr, fallbackEn);
}

function towerTooltipDataAttrs(title: string, desc: string): string {
    const safeTitle = escapeHtml(title).replace(/"/g, '&quot;');
    const safeDesc = escapeHtml(desc).replace(/"/g, '&quot;');
    return `data-tooltip-title="${safeTitle}" data-tooltip-desc="${safeDesc}"`;
}

export function buildTowerRelicAutoPanelHtml(game: GameRuntime): TowerRelicAutoPanelBuild {
    if (!game.unlockedFeatures || !game.unlockedFeatures.towerRelicAuto) {
        return { visible: false, html: '', sig: '' };
    }
    callGameVoid(game, game.normalizeTowerRelicAutoSettings);
    const renderSig = computeTowerRelicAutoPanelSig(game);
    const s = game.towerRelicAutoSettings;
    const relicKeys = Object.keys(TOWER_RELICS);
    const esc = escapeHtml;

    const noneOpt = towerText(game, '', '— Aucune —', '— None —');
    const rarityFloors = [RARITY.COMMON, RARITY.RARE, RARITY.EPIC, RARITY.LEGENDARY];
    const minRarityOptionLabel = (r: string) => {
        if (r === RARITY.COMMON) {
            return towerText(game, '', 'Jet min. : toute rareté', 'Min roll: any rarity');
        }
        return towerText(
            game,
            '',
            'Jet min. : {r}+',
            'Min roll: {r}+',
            { r: towerRarityLabel(game, r) }
        );
    };

    const metaByRarityLabel = towerText(game, '', 'Par rareté', 'By rarity');

    const keysTakenByOtherPrioSlots = (excludeSlot: number) => {
        const set = new Set<string>();
        for (let i = 0; i < TOWER_RELIC_AUTO_PRIORITY_SLOT_COUNT; i++) {
            if (i === excludeSlot) continue;
            const ps = s.prioritySlots && s.prioritySlots[i];
            if (ps && ps.key) set.add(ps.key);
        }
        return set;
    };
    const prioOptionDisabledAttr = (optionVal: string, currentKey: string | null, takenElsewhere: Set<string>) => {
        if (!optionVal || !takenElsewhere.has(optionVal)) return '';
        if (currentKey === optionVal) return '';
        return ' disabled';
    };

    const prioBlocks = Array.from({ length: TOWER_RELIC_AUTO_PRIORITY_SLOT_COUNT }, (_, slot) => {
        const slotDef = (s.prioritySlots && s.prioritySlots[slot])
            ? s.prioritySlots[slot]
            : { key: null, minRarity: RARITY.COMMON };
        const taken = keysTakenByOtherPrioSlots(slot);
        const curKey = slotDef.key || null;
        const relicOpts = relicKeys.map((k) => {
            const rk = recordGet(TOWER_RELICS as Record<string, Record<string, unknown>>, k) ?? null;
            const parts = towerRelicPriorityOptionParts(game, k, rk);
            const sel = (slotDef.key === k) ? ' selected' : '';
            const dis = prioOptionDisabledAttr(k, curKey, taken);
            return `<option value="${esc(k)}" title="${esc(parts.title)}"${dis}${sel}>${esc(parts.text)}</option>`;
        });
        const disMeta = prioOptionDisabledAttr(TOWER_RELIC_PRIORITY_BY_RARITY, curKey, taken);
        const opts = [
            `<option value="">${esc(noneOpt)}</option>`,
            `<option value="${esc(TOWER_RELIC_PRIORITY_BY_RARITY)}"${disMeta}${slotDef.key === TOWER_RELIC_PRIORITY_BY_RARITY ? ' selected' : ''}>${esc(metaByRarityLabel)}</option>`
        ].concat(relicOpts).join('');
        const minOpts = rarityFloors.map((r) => {
            const sel = ((slotDef.minRarity || RARITY.COMMON) === r) ? ' selected' : '';
            return `<option value="${esc(r)}"${sel}>${esc(minRarityOptionLabel(r))}</option>`;
        }).join('');
        const lbl = towerText(
            game,
            '',
            'Priorite {n}',
            'Priority {n}',
            { n: slot + 1 }
        );
        const minTooltip = towerRelicAutoTooltip(
            game,
            'minRarityTooltip',
            'Rareté minimale du jet pour accepter cette relique',
            'Minimum rolled rarity to accept this relic',
        );
        return `<div class="tower-relic-auto-prio-row">` +
            `<span class="tower-relic-auto-prio-slot-label">${esc(lbl)}</span>` +
            `<div class="tower-relic-auto-prio-fields">` +
                `<select id="towerRelicAutoP${slot}" class="tower-relic-auto-select tower-relic-auto-prio-key">${opts}</select>` +
                `<select id="towerRelicAutoMinR${slot}" class="tower-relic-auto-select tower-relic-auto-minr" ${towerTooltipDataAttrs(lbl, minTooltip)}>${minOpts}</select>` +
            `</div>` +
        `</div>`;
    }).join('');

    const blacklistMax = 3;
    const blCount = s.blacklist.length;
    const blItems = relicKeys.map((k) => {
        const rk = recordGet(TOWER_RELICS as Record<string, Record<string, unknown>>, k) ?? null;
        const label = towerRelicName(game, k, rk);
        const isOn = s.blacklist.includes(k);
        const checked = isOn ? ' checked' : '';
        const disabled = !isOn && blCount >= blacklistMax ? ' disabled' : '';
        return `<label class="tower-relic-auto-bl-item${disabled ? ' tower-relic-auto-bl-disabled' : ''}"><input type="checkbox" class="tower-relic-auto-bl-cb" data-tower-relic-bl="${esc(k)}"${checked}${disabled}/><span>${esc(label)}</span></label>`;
    }).join('');

    const panelTitle = towerText(game, '', 'Pilote de reliques', 'Relic pilot');
    const panelTooltip = towerRelicAutoTooltip(
        game,
        'panelTooltip',
        'Configure les priorités, la liste noire et l\'auto-sélection des reliques de run.',
        'Configure priorities, blacklist, and auto-pick for run relics.',
    );
    const skipLootLabel = towerText(game, '', 'Ignorer les butins (Contrebande)', 'Skip loot items (Smuggling)');
    const skipLootTooltip = towerRelicAutoTooltip(
        game,
        'skipLootTooltip',
        'Le pilote ne choisit que des reliques de run ; les butins (balls, capsules, etc.) restent a choisir a la main.',
        'The pilot only picks run relics; loot (balls, capsules, etc.) must be chosen manually.',
    );
    const html =
        `<div class="tower-relic-auto-panel-inner">` +
            `<h4 class="tower-relic-auto-title" ${towerTooltipDataAttrs(panelTitle, panelTooltip)}>${panelTitle}</h4>` +
            `<label class="tower-relic-auto-enable"><input type="checkbox" id="towerRelicAutoEnabledCb"${s.enabled ? ' checked' : ''}/>` +
            `<span>${towerText(game, '', 'Activer l\'auto-selection a chaque offre', 'Enable auto-pick on each offer')}</span></label>` +
            `<label class="tower-relic-auto-enable" ${towerTooltipDataAttrs(skipLootLabel, skipLootTooltip)}><input type="checkbox" id="towerRelicAutoSkipLootCb"${s.skipItemLoot ? ' checked' : ''}/>` +
            `<span>${skipLootLabel}</span></label>` +
            `<div class="tower-relic-auto-prio-block">${prioBlocks}</div>` +
            `<div class="tower-relic-auto-bl-title">${towerText(game, '', 'Liste noire — max. 3 reliques (evitees si possible)', 'Blacklist — max 3 relics (avoided when possible)')}</div>` +
            `<div class="tower-relic-auto-blacklist">${blItems}</div>` +
        `</div>`;
    return { visible: true, html, sig: renderSig };
}

