/**
 * @file src/lib/masteryCombat.ts
 * Runtime combat state + helpers for Fighter mastery tiers 51–54.
 */

import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';
import { getAttackerHpRatio } from './combatHpRatio.ts';

export interface MasteryCombatState {
    /** Armed after ally faint; consumed on next player offensive action. */
    revengeArmed: boolean;
    /** Charges remaining for switch-in damage reduction (usually 0 or 1). */
    switchInShieldCharges: number;
    /** Enemy KOs this combat (for streak damage). */
    koStreak: number;
}

export const MASTERY_LOW_HP_THRESHOLD = 0.30;
export const MASTERY_KO_STREAK_DAMAGE_CAP = 0.15;

export function createDefaultMasteryCombatState(): MasteryCombatState {
    return {
        revengeArmed: false,
        switchInShieldCharges: 0,
        koStreak: 0,
    };
}

export function resetMasteryCombatState(game: GameRuntime): void {
    game.masteryCombat = createDefaultMasteryCombatState();
}

function ensureState(game: GameRuntime): MasteryCombatState {
    if (!game.masteryCombat) {
        game.masteryCombat = createDefaultMasteryCombatState();
    }
    return game.masteryCombat;
}

export function armMasteryRevengeOnAllyFaint(game: GameRuntime): void {
    const bonus = game.getMasteryBonus?.('revenge_damage_mult') || 0;
    if (bonus <= 0) return;
    ensureState(game).revengeArmed = true;
}

export function armMasterySwitchInShield(game: GameRuntime): void {
    const bonus = game.getMasteryBonus?.('switch_in_shield') || 0;
    if (bonus <= 0) return;
    ensureState(game).switchInShieldCharges = 1;
}

export function incrementMasteryKoStreak(game: GameRuntime): void {
    const perKo = game.getMasteryBonus?.('ko_streak_damage_mult') || 0;
    if (perKo <= 0) return;
    ensureState(game).koStreak += 1;
}

/**
 * Outgoing damage multiplier for player → enemy (revenge + low HP + KO streak).
 * Consumes revenge when applied.
 */
export function applyMasteryOutgoingDamageMods(
    game: GameRuntime,
    attacker: ICreature,
    damage: number,
): number {
    if (!(damage > 0) || attacker.isEnemy) return damage;
    let out = damage;
    const state = ensureState(game);

    const revengeBonus = game.getMasteryBonus?.('revenge_damage_mult') || 0;
    if (state.revengeArmed && revengeBonus > 0) {
        out = Math.floor(out * (1 + revengeBonus));
        state.revengeArmed = false;
    }

    const lowHpBonus = game.getMasteryBonus?.('low_hp_damage_mult') || 0;
    if (lowHpBonus > 0 && getAttackerHpRatio(game, attacker) < MASTERY_LOW_HP_THRESHOLD) {
        out = Math.floor(out * (1 + lowHpBonus));
    }

    const perKo = game.getMasteryBonus?.('ko_streak_damage_mult') || 0;
    if (perKo > 0 && state.koStreak > 0) {
        const streakBonus = Math.min(MASTERY_KO_STREAK_DAMAGE_CAP, state.koStreak * perKo);
        out = Math.floor(out * (1 + streakBonus));
    }

    return out;
}

/**
 * Incoming damage multiplier for enemy → player (switch-in shield).
 * Consumes one shield charge when applied.
 */
export function applyMasteryIncomingDamageMods(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    damage: number,
): number {
    if (!(damage > 0) || !attacker.isEnemy || target.isEnemy) return damage;
    const state = ensureState(game);
    const shield = game.getMasteryBonus?.('switch_in_shield') || 0;
    if (state.switchInShieldCharges <= 0 || shield <= 0) return damage;
    state.switchInShieldCharges -= 1;
    return Math.floor(damage * (1 - Math.min(0.9, shield)));
}

/** Berry production: time reduction → rate multiplier. */
export function berryProductionRateFromTimeReduction(reduction: number): number {
    const r = Math.max(0, Math.min(0.5, Number(reduction) || 0));
    if (r <= 0) return 1;
    return 1 / (1 - r);
}
